import React from 'react';
import { createRoot } from 'react-dom/client';
import { HashRouter } from 'react-router-dom';
import { ErrorBoundary } from 'react-error-boundary';

import RoutesComponent from './app.tsx';
import './index.css';
import { createPortal } from 'react-dom';
import { Toaster } from '@client/src/components/ui/sonner';

// GitHub Pages 静态托管：部署在子目录（如 /game5/）下，用 Hash 路由保证
// 任意深层路由刷新不 404。

function SimpleErrorFallback({ error }: { error: Error }) {
  return (
    <div style={{ padding: 24, fontFamily: 'sans-serif', color: '#b91c1c' }}>
      <h2>页面出错了</h2>
      <p>{error.message}</p>
    </div>
  );
}

const MainApp = () => {
  return (
    <HashRouter>
      <ErrorBoundary
        fallbackRender={({ error }) => <SimpleErrorFallback error={error as Error} />}
      >
        <RoutesComponent />
        {createPortal(<Toaster />, document.body)}
      </ErrorBoundary>
    </HashRouter>
  );
};

createRoot(document.getElementById('root')!).render(<MainApp />);
