import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Coins,
  ArrowLeft,
  Trophy,
  Crown,
  Swords,
  Lock,
  Sparkles,
  Zap,
} from 'lucide-react';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { useAutoSave } from '@client/src/hooks/useAutoSave';
import { casinoApi } from '@client/src/api';
import {
  getPlayerLevelInfo,
  isCasinoUnlocked,
} from '@client/src/utils/casino-levels';
import type {
  PlayerState,
  TexasState,
  TexasHand,
  CasinoTier,
} from '@shared/api.interface';

const DEFAULT_MIN_BET = 10000;
const QUICK_CHIPS = [10000, 50000, 100000, 500000];
const CASINO_TIER = 5;

const TIER_MIN_BET: Record<number, number> = {
  2: 10,
  3: 100,
  4: 1000,
  5: 10000,
};

const TIER_PATH: Record<number, string> = {
  2: '/hundred-yuan',
  3: '/thousand-yuan',
  4: '/ten-thousand-yuan',
  5: '/million-yuan',
};
const UNLOCK_EXP = 50000;

const SUIT_SYMBOLS = ['♠', '♥', '♦', '♣'];
const SUIT_COLORS = ['text-gray-900', 'text-red-600', 'text-blue-600', 'text-emerald-600'];

function getRankLabel(rank: number): string {
  if (rank === 14) return 'A';
  if (rank === 13) return 'K';
  if (rank === 12) return 'Q';
  if (rank === 11) return 'J';
  return String(rank);
}

const formatChips = (n: number): string => n.toLocaleString('zh-CN');

const TexasArena: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const path = location.pathname;
  let tier: CasinoTier | null = null;
  if (path.startsWith('/hundred-yuan')) tier = 2;
  else if (path.startsWith('/thousand-yuan')) tier = 3;
  else if (path.startsWith('/ten-thousand-yuan')) tier = 4;
  else if (path.startsWith('/million-yuan')) tier = 5;

  const minBet = tier ? TIER_MIN_BET[tier] ?? DEFAULT_MIN_BET : DEFAULT_MIN_BET;
  const backPath = tier ? TIER_PATH[tier] ?? '/' : '/';

  const { playerState, setPlayerState, loading, token } = useGameAuth();
  const [betAmount, setBetAmount] = useState<number>(minBet);
  const [customInput, setCustomInput] = useState<string>('');
  const [gameState, setGameState] = useState<TexasState | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [revealedDealer, setRevealedDealer] = useState<boolean>(false);
  const [dealtCount, setDealtCount] = useState<number>(0);

  useAutoSave(playerState);

  useEffect(() => {
    if (!loading && !token) {
      navigate('/login', { replace: true });
    }
  }, [loading, token, navigate]);

  useEffect(() => {
    setBetAmount(minBet);
  }, [minBet]);

  const levelInfo = useMemo(
    () => (playerState ? getPlayerLevelInfo(playerState.experience) : null),
    [playerState],
  );

  const unlocked = useMemo(
    () =>
      playerState
        ? isCasinoUnlocked(playerState.experience, CASINO_TIER)
        : false,
    [playerState],
  );

  const hasLoanWarning = useMemo(() => {
    if (!playerState) return false;
    return playerState.loanPrincipal > 0;
  }, [playerState]);

  const handleQuickChip = useCallback(
    (amount: number) => {
      if (isProcessing) return;
      setBetAmount(amount);
      setCustomInput('');
    },
    [isProcessing],
  );

  const handleCustomChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (isProcessing) return;
      const val = e.target.value.replace(/[^0-9]/g, '');
      setCustomInput(val);
      const num = parseInt(val, 10);
      if (!isNaN(num) && num > 0) {
        setBetAmount(num);
      }
    },
    [isProcessing],
  );

  const dealSequence = useCallback(async (state: TexasState) => {
    setDealtCount(0);
    setRevealedDealer(false);
    for (let i = 1; i <= 5; i += 1) {
      await new Promise<void>((resolve) => {
        setTimeout(resolve, 120);
      });
      setDealtCount(i);
    }
    setIsProcessing(false);
    void state;
  }, []);

  const showdownSequence = useCallback(async (state: TexasState) => {
    setIsProcessing(true);
    setRevealedDealer(false);
    await new Promise<void>((resolve) => {
      setTimeout(resolve, 400);
    });
    setRevealedDealer(true);
    await new Promise<void>((resolve) => {
      setTimeout(resolve, 800);
    });
    setIsProcessing(false);
    void state;
  }, []);

  const handleDeal = useCallback(async () => {
    if (isProcessing || !playerState) return;
    if (betAmount < minBet) {
      toast.error(`最低下注 ${formatChips(minBet)} 筹码`);
      return;
    }
    if (betAmount > playerState.chipBalance) {
      toast.error('筹码不足，请减少下注金额');
      return;
    }

    setIsProcessing(true);
    setGameState(null);
    setDealtCount(0);
    setRevealedDealer(false);

    try {
      const result: TexasState = await casinoApi.texasAction('deal', betAmount, tier ?? 5);
      setGameState(result);
      if (result.playerState) {
        setPlayerState(result.playerState);
      }
      void dealSequence(result);
    } catch (err) {
      logger.error('德州扑克发牌失败', err);
      toast.error('发牌失败，请稍后重试');
      setIsProcessing(false);
    }
  }, [
    isProcessing,
    playerState,
    betAmount,
    setPlayerState,
    dealSequence,
  ]);

  const handleCall = useCallback(async () => {
    if (isProcessing || !gameState) return;
    if (!playerState) return;
    if (betAmount > playerState.chipBalance - gameState.betAmount) {
      toast.error('筹码不足，无法跟注');
      return;
    }

    setIsProcessing(true);
    try {
      const result: TexasState = await casinoApi.texasAction('call');
      setGameState(result);
      if (result.playerState) {
        setPlayerState(result.playerState);
      }
      void showdownSequence(result);
    } catch (err) {
      logger.error('德州扑克跟注失败', err);
      toast.error('跟注失败，请稍后重试');
      setIsProcessing(false);
    }
  }, [isProcessing, gameState, playerState, betAmount, setPlayerState, showdownSequence]);

  const handleFold = useCallback(async () => {
    if (isProcessing || !gameState) return;

    setIsProcessing(true);
    try {
      const result: TexasState = await casinoApi.texasAction('fold');
      setGameState(result);
      if (result.playerState) {
        setPlayerState(result.playerState);
      }
      setRevealedDealer(false);
      setIsProcessing(false);
    } catch (err) {
      logger.error('德州扑克弃牌失败', err);
      toast.error('弃牌失败，请稍后重试');
      setIsProcessing(false);
    }
  }, [isProcessing, gameState, setPlayerState]);

  const handleReset = useCallback(() => {
    setGameState(null);
    setDealtCount(0);
    setRevealedDealer(false);
  }, []);

  const isPlayerTurn = gameState?.phase === 'playerTurn';
  const isShowdown = gameState?.phase === 'showdown' || gameState?.phase === 'finished';
  const isFinished = gameState?.phase === 'finished';
  const playerWon = gameState?.playerWon === true;
  const playerLost = gameState?.playerWon === false;

  const canDeal =
    !isProcessing &&
    !gameState &&
    playerState &&
    betAmount >= minBet &&
    betAmount <= playerState.chipBalance &&
    unlocked;

  const playerHand: TexasHand | null = gameState?.playerHand ?? null;
  const dealerHand: TexasHand | null = gameState?.dealerHand ?? null;

  const playerRankLabel = playerHand?.description ?? '';
  const dealerRankLabel = dealerHand?.description ?? '';

  return (
    <div className="min-h-screen text-foreground flex flex-col relative overflow-hidden">
      {/* Background */}
      <div
        className="absolute inset-0 -z-10"
        style={{
          background: `
            radial-gradient(ellipse at 50% 0%, #3b0a0a 0%, #1a0505 40%, #0d0202 80%),
            linear-gradient(180deg, #1a0505 0%, #0d0202 100%)
          `,
        }}
      />
      <div
        className="absolute inset-0 -z-10 opacity-30"
        style={{
          backgroundImage: `
            radial-gradient(circle at 20% 30%, rgba(251, 191, 36, 0.1) 0%, transparent 40%),
            radial-gradient(circle at 80% 70%, rgba(220, 38, 38, 0.15) 0%, transparent 40%)
          `,
        }}
      />
      <div
        className="absolute top-0 left-1/2 -translate-x-1/2 -z-10 w-[700px] h-[500px] opacity-40"
        style={{
          background:
            'radial-gradient(ellipse at center top, rgba(251, 191, 36, 0.3) 0%, transparent 70%)',
        }}
      />
      <div
        className="absolute bottom-0 left-0 right-0 -z-10 h-[300px] opacity-25"
        style={{
          background:
            'radial-gradient(ellipse at 50% 100%, rgba(127, 29, 29, 0.6) 0%, transparent 70%)',
        }}
      />

      {/* Header */}
      <header className="flex items-center justify-between px-4 py-3 border-b border-amber-800/40 bg-[#1a0505]/80 backdrop-blur-sm">
        <button
          type="button"
          onClick={() => navigate(backPath)}
          className="p-2 rounded-lg hover:bg-amber-900/30 transition-colors"
          aria-label="返回"
        >
          <ArrowLeft className="w-5 h-5 text-amber-300" />
        </button>
        <div className="flex items-center gap-2">
          <Crown className="w-5 h-5 text-amber-400" />
          <h1 className="text-base font-bold text-amber-100 tracking-wide">
            帝国赌场 · 德州扑克
          </h1>
        </div>
        <div className="flex items-center gap-1.5 bg-amber-950/60 px-3 py-1.5 rounded-full border border-amber-700/40">
          <Coins className="w-4 h-4 text-amber-400" />
          <span className="text-sm font-semibold text-amber-200">
            {playerState ? formatChips(playerState.chipBalance) : '--'}
          </span>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4 py-4 pb-6">
        <div className="max-w-md mx-auto space-y-4">
          {/* Lock overlay */}
          {!unlocked && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
              className="bg-[#2a0a0a]/90 border border-amber-700/40 rounded-2xl p-5 shadow-2xl shadow-amber-950/50 backdrop-blur-sm"
            >
              <div className="flex flex-col items-center text-center">
                <div className="w-16 h-16 rounded-full bg-gradient-to-br from-amber-800 to-red-900 flex items-center justify-center shadow-lg shadow-amber-900/50 mb-3 ring-2 ring-amber-600/30">
                  <Lock className="w-8 h-8 text-amber-300" />
                </div>
                <div className="text-lg font-bold text-amber-100 mb-1">
                  帝国赌场尚未解锁
                </div>
                <div className="text-sm text-amber-400/70 mb-4">
                  需 {formatChips(UNLOCK_EXP)} 经验解锁帝国赌场
                </div>
                <div className="w-full bg-amber-950/60 rounded-full h-2 mb-2 overflow-hidden">
                  <div
                    className="h-full bg-gradient-to-r from-amber-500 to-yellow-400 rounded-full"
                    style={{
                      width: `${Math.min(
                        100,
                        Math.round(
                          ((playerState?.experience ?? 0) / UNLOCK_EXP) * 100,
                        ),
                      )}%`,
                    }}
                  />
                </div>
                <div className="text-xs text-amber-500/70">
                  当前经验 {formatChips(playerState?.experience ?? 0)} /{' '}
                  {formatChips(UNLOCK_EXP)}
                </div>
              </div>
            </motion.div>
          )}

          {/* Player info */}
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="bg-[#2a0a0a]/80 border border-amber-800/40 rounded-2xl p-4 shadow-lg backdrop-blur-sm"
          >
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 rounded-full bg-gradient-to-br from-amber-400 to-red-600 flex items-center justify-center shadow-md shadow-amber-900/50 ring-2 ring-amber-500/30">
                  <Trophy className="w-6 h-6 text-amber-50" />
                </div>
                <div>
                  <div className="text-sm font-bold text-amber-100">
                    Lv.{levelInfo?.level ?? 1} ·{' '}
                    {levelInfo?.levelName ?? '新手赌客'}
                  </div>
                  <div className="text-xs text-amber-400/70">
                    经验 {levelInfo?.currentExp ?? 0} /{' '}
                    {levelInfo?.nextLevelExp ?? 50}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-xs text-amber-300/80">
                <Coins className="w-4 h-4 text-amber-400" />
                <span className="font-semibold text-sm">
                  {playerState ? formatChips(playerState.chipBalance) : '--'}
                </span>
              </div>
            </div>
            <div className="h-2 bg-amber-950/60 rounded-full overflow-hidden mb-3">
              <motion.div
                className="h-full bg-gradient-to-r from-amber-500 to-yellow-400 rounded-full"
                initial={{ width: 0 }}
                animate={{ width: `${levelInfo?.progress ?? 0}%` }}
                transition={{ duration: 0.8, ease: 'easeOut' }}
              />
            </div>
            <div className="flex items-center justify-center gap-2 text-xs bg-gradient-to-r from-amber-950/50 via-red-900/40 to-amber-950/50 rounded-lg px-3 py-2 border border-amber-700/30">
              <Crown className="w-4 h-4 text-amber-400" />
              <span className="text-amber-200 font-medium">
                帝国赌场 · 百万元场
              </span>
              <Sparkles className="w-3.5 h-3.5 text-amber-300" />
            </div>
          </motion.div>

          {/* Loan warning */}
          {hasLoanWarning && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              className="bg-amber-950/30 border border-amber-700/40 rounded-xl px-4 py-3 flex items-start gap-3"
            >
              <Zap className="w-5 h-5 text-amber-400 flex-shrink-0 mt-0.5" />
              <div>
                <div className="text-sm font-semibold text-amber-200">
                  尚有贷款未还清
                </div>
                <div className="text-xs text-amber-400/70 mt-0.5">
                  本金 {formatChips(playerState?.loanPrincipal ?? 0)} · 利率{' '}
                  {Math.round((playerState?.loanInterestRate ?? 0) * 100)}% ·
                  剩余 {playerState?.loanGamesRemaining ?? 0} 局
                </div>
              </div>
            </motion.div>
          )}

          {/* Texas table */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="relative bg-gradient-to-br from-[#2a0a0a] via-[#4a0e0e] to-[#1a0505] border-2 border-amber-600/50 rounded-3xl p-5 shadow-2xl shadow-amber-950/70"
          >
            <div className="absolute inset-0 rounded-3xl border border-amber-400/20 m-1 pointer-events-none" />
            <div className="absolute top-2 left-1/2 -translate-x-1/2 w-24 h-1 bg-gradient-to-r from-transparent via-amber-400 to-transparent opacity-60" />

            <div className="text-center mb-4">
              <div className="inline-flex items-center gap-2 bg-amber-950/60 px-4 py-1 rounded-full border border-amber-700/40">
                <Crown className="w-4 h-4 text-amber-400" />
                <span className="text-sm font-semibold text-amber-200 tracking-widest">
                  百 万 元 场
                </span>
                <Crown className="w-4 h-4 text-amber-400" />
              </div>
            </div>

            {/* Dealer hand */}
            <div className="mb-4">
              <div
                className={`text-center mb-2 text-sm font-bold ${
                  isShowdown && playerLost
                    ? 'text-amber-300 drop-shadow-[0_0_8px_rgba(251_191_36_0.6)]'
                    : 'text-amber-200/80'
                }`}
              >
                庄 家
                {isShowdown && playerLost && (
                  <Sparkles className="inline w-4 h-4 ml-1 text-amber-300" />
                )}
              </div>
              <div className="flex justify-center gap-1.5">
                {[0, 1, 2, 3, 4].map((idx: number) => {
                  const card = dealerHand?.cards?.[idx];
                  const showFace = isShowdown && revealedDealer && !!card;
                  const isRed = card ? card.suit === 1 || card.suit === 2 : false;
                  const rotation = (idx - 2) * 4;
                  return (
                    <motion.div
                      key={`dealer-${idx}`}
                      initial={{ opacity: 0, y: -20, rotate: rotation - 5 }}
                      animate={
                        isPlayerTurn || isShowdown
                          ? { opacity: 1, y: 0, rotate: rotation }
                          : { opacity: 0, y: -20, rotate: rotation - 5 }
                      }
                      transition={{ duration: 0.3, delay: idx * 0.08 }}
                      style={{ transformOrigin: 'bottom center' }}
                    >
                      <div
                        className={`w-12 h-[72px] rounded-lg shadow-lg flex flex-col justify-between p-1 ${
                          showFace
                            ? 'bg-gradient-to-br from-amber-50 to-amber-100 border border-amber-400/50'
                            : 'bg-gradient-to-br from-red-800 via-red-900 to-red-950 border border-amber-600/50'
                        }`}
                      >
                        {showFace && card ? (
                          <>
                            <div
                              className={`text-[10px] font-black leading-none ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              <div>{getRankLabel(card.rank)}</div>
                              <div className="text-[9px]">
                                {SUIT_SYMBOLS[card.suit]}
                              </div>
                            </div>
                            <div
                              className={`text-center text-lg font-black ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              {SUIT_SYMBOLS[card.suit]}
                            </div>
                            <div
                              className={`text-[10px] font-black leading-none text-right rotate-180 ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              <div>{getRankLabel(card.rank)}</div>
                              <div className="text-[9px]">
                                {SUIT_SYMBOLS[card.suit]}
                              </div>
                            </div>
                          </>
                        ) : (
                          <div className="w-full h-full rounded-md border border-amber-500/30 flex items-center justify-center bg-gradient-to-br from-red-700 via-red-800 to-red-900">
                            <Crown className="w-4 h-4 text-amber-400/70" />
                          </div>
                        )}
                      </div>
                    </motion.div>
                  );
                })}
              </div>
              {isShowdown && revealedDealer && dealerHand && (
                <motion.div
                  initial={{ opacity: 0, scale: 0.5 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ duration: 0.4, type: 'spring' }}
                  className={`text-center mt-2 text-base font-bold ${
                    playerLost
                      ? 'text-amber-300 drop-shadow-[0_0_8px_rgba(251_191_36_0.8)]'
                      : 'text-amber-200/70'
                  }`}
                >
                  {dealerRankLabel}
                </motion.div>
              )}
            </div>

            {/* Status / VS */}
            <div className="flex items-center justify-center py-2">
              <div className="flex flex-col items-center">
                <div
                  className={`text-xs font-bold mb-1 ${
                    isShowdown
                      ? 'text-amber-400'
                      : 'text-amber-300/60'
                  }`}
                >
                  {gameState?.message || (gameState ? 'VS' : '等待下注')}
                </div>
                {isPlayerTurn && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.4, type: 'spring' }}
                    className="flex items-center gap-1.5"
                  >
                    <Swords className="w-4 h-4 text-amber-400" />
                    <span className="text-xs font-semibold text-amber-300">
                      你的回合
                    </span>
                    <Swords className="w-4 h-4 text-amber-400" />
                  </motion.div>
                )}
                {isShowdown && revealedDealer && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.5, type: 'spring' }}
                    className="w-12 h-12 rounded-full bg-gradient-to-br from-amber-400 to-yellow-600 flex items-center justify-center shadow-lg shadow-amber-500/50 ring-2 ring-yellow-300"
                  >
                    {playerWon ? (
                      <Trophy className="w-6 h-6 text-amber-900" />
                    ) : playerLost ? (
                      <Crown className="w-6 h-6 text-amber-900" />
                    ) : (
                      <Sparkles className="w-6 h-6 text-amber-900" />
                    )}
                  </motion.div>
                )}
              </div>
            </div>

            {/* Player hand */}
            <div className="mt-4">
              <div
                className={`text-center mb-2 text-sm font-bold ${
                  isShowdown && playerWon
                    ? 'text-amber-300 drop-shadow-[0_0_8px_rgba(251_191_36_0.6)]'
                    : 'text-amber-200/80'
                }`}
              >
                你 的 牌
                {isShowdown && playerWon && (
                  <Sparkles className="inline w-4 h-4 ml-1 text-amber-300" />
                )}
              </div>
              <div className="flex justify-center gap-1.5">
                {[0, 1, 2, 3, 4].map((idx: number) => {
                  const card = playerHand?.cards?.[idx];
                  const revealed = idx < dealtCount && !!card;
                  const isRed = card ? card.suit === 1 || card.suit === 2 : false;
                  const rotation = (idx - 2) * 4;
                  return (
                    <motion.div
                      key={`player-${idx}`}
                      initial={{ opacity: 0, y: 20, rotate: rotation + 5 }}
                      animate={
                        revealed
                          ? { opacity: 1, y: 0, rotate: rotation }
                          : { opacity: 0, y: 20, rotate: rotation + 5 }
                      }
                      transition={{ duration: 0.3, delay: idx * 0.08 }}
                      style={{ transformOrigin: 'top center' }}
                    >
                      <div
                        className={`w-12 h-[72px] rounded-lg shadow-lg flex flex-col justify-between p-1 ${
                          revealed && card
                            ? 'bg-gradient-to-br from-amber-50 to-amber-100 border border-amber-400/50'
                            : 'bg-gradient-to-br from-red-800 via-red-900 to-red-950 border border-amber-600/50'
                        }`}
                      >
                        {revealed && card ? (
                          <>
                            <div
                              className={`text-[10px] font-black leading-none ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              <div>{getRankLabel(card.rank)}</div>
                              <div className="text-[9px]">
                                {SUIT_SYMBOLS[card.suit]}
                              </div>
                            </div>
                            <div
                              className={`text-center text-lg font-black ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              {SUIT_SYMBOLS[card.suit]}
                            </div>
                            <div
                              className={`text-[10px] font-black leading-none text-right rotate-180 ${
                                SUIT_COLORS[card.suit] ?? 'text-gray-900'
                              }`}
                            >
                              <div>{getRankLabel(card.rank)}</div>
                              <div className="text-[9px]">
                                {SUIT_SYMBOLS[card.suit]}
                              </div>
                            </div>
                          </>
                        ) : (
                          <div className="w-full h-full rounded-md border border-amber-500/30 flex items-center justify-center bg-gradient-to-br from-red-700 via-red-800 to-red-900">
                            <Crown className="w-4 h-4 text-amber-400/70" />
                          </div>
                        )}
                      </div>
                    </motion.div>
                  );
                })}
              </div>
              {playerHand && dealtCount >= 5 && (
                <motion.div
                  initial={{ opacity: 0, scale: 0.5 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ duration: 0.4, type: 'spring' }}
                  className={`text-center mt-2 text-base font-bold ${
                    isShowdown && playerWon
                      ? 'text-amber-300 drop-shadow-[0_0_8px_rgba(251_191_36_0.8)]'
                      : 'text-amber-200'
                  }`}
                >
                  {playerRankLabel}
                </motion.div>
              )}
            </div>
          </motion.div>

          {/* Result */}
          <AnimatePresence mode="wait">
            {isFinished && gameState && (
              <motion.div
                key="result"
                initial={{ opacity: 0, y: 20, scale: 0.9 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -20, scale: 0.9 }}
                transition={{ duration: 0.4, type: 'spring' }}
                className={`border-2 rounded-2xl p-4 shadow-2xl ${
                  playerWon
                    ? 'bg-gradient-to-br from-amber-900/80 via-yellow-800/60 to-amber-900/80 border-amber-400/60'
                    : 'bg-gradient-to-br from-slate-900/80 via-[#1a0505]/80 to-slate-900/80 border-slate-700/50'
                }`}
              >
                <div className="text-center mb-3">
                  <div
                    className={`text-xl font-black mb-1 ${
                      playerWon ? 'text-amber-200' : 'text-slate-400'
                    }`}
                  >
                    {playerWon ? (
                      <span className="flex items-center justify-center gap-2">
                        <Trophy className="w-6 h-6 text-amber-300" />
                        恭 喜 获 胜
                        <Trophy className="w-6 h-6 text-amber-300" />
                      </span>
                    ) : (
                      <span>很遗憾，本局失利</span>
                    )}
                  </div>
                  <div className="text-sm text-amber-200/70">
                    {gameState.message}
                  </div>
                </div>

                <div
                  className={`text-center py-3 rounded-xl mb-3 ${
                    playerWon
                      ? 'bg-gradient-to-r from-amber-600/30 via-yellow-500/30 to-amber-600/30'
                      : 'bg-slate-900/50'
                  }`}
                >
                  <div className="text-xs text-amber-300/70 mb-1">
                    {playerWon ? '净赢利' : '损失金额'}
                  </div>
                  <div
                    className={`text-3xl font-black ${
                      playerWon ? 'text-amber-200' : 'text-slate-400'
                    }`}
                  >
                    {playerWon ? '+' : ''}
                    {formatChips(Math.abs(gameState.winAmount))}
                    <span className="text-sm font-semibold ml-1 text-amber-300/70">
                      筹码
                    </span>
                  </div>
                </div>

                <div className="flex items-center justify-center gap-2 text-sm">
                  <Zap className="w-4 h-4 text-amber-400" />
                  <span className="text-amber-200">
                    获得经验{' '}
                    <span className="font-bold text-amber-300">
                      +{gameState.expGained}
                    </span>
                  </span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Bet panel - before deal */}
          {!gameState && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.2 }}
              className="bg-[#2a0a0a]/80 border border-amber-800/40 rounded-2xl p-4 shadow-lg backdrop-blur-sm"
            >
              <div className="text-xs font-semibold text-amber-300/80 mb-2 flex items-center gap-1.5">
                <Coins className="w-3.5 h-3.5" />
                下注金额（底注）
                <span className="ml-auto text-amber-400/60 font-normal">
                  最低 {formatChips(minBet)}
                </span>
              </div>

              <div className="grid grid-cols-4 gap-2 mb-3">
                {QUICK_CHIPS.map((chip: number) => (
                  <motion.button
                    key={chip}
                    type="button"
                    whileHover={!isProcessing && unlocked ? { scale: 1.05 } : {}}
                    whileTap={!isProcessing && unlocked ? { scale: 0.95 } : {}}
                    onClick={() => handleQuickChip(chip)}
                    disabled={isProcessing || !unlocked}
                    className={`py-2 rounded-lg text-xs font-bold transition-all ${
                      betAmount === chip && !customInput
                        ? 'bg-gradient-to-br from-amber-500 to-yellow-600 text-white shadow-md shadow-amber-500/30'
                        : 'bg-amber-950/60 text-amber-200/80 border border-amber-800/40 hover:border-amber-600/60'
                    } ${!unlocked ? 'opacity-50 cursor-not-allowed' : ''}`}
                  >
                    {chip >= 10000 ? `${chip / 10000}万` : formatChips(chip)}
                  </motion.button>
                ))}
              </div>

              <div className="relative mb-4">
                <input
                  type="text"
                  value={customInput || (betAmount ? formatChips(betAmount) : '')}
                  onChange={handleCustomChange}
                  disabled={isProcessing || !unlocked}
                  placeholder={`输入金额，最低 ${formatChips(minBet)}`}
                  className="w-full bg-amber-950/60 border border-amber-800/40 rounded-xl px-4 py-3 text-amber-100 text-center font-bold text-lg placeholder:text-amber-600/50 focus:outline-none focus:border-amber-500/60 focus:ring-2 focus:ring-amber-500/30 disabled:opacity-50"
                />
                <div className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-amber-400/60">
                  筹码
                </div>
              </div>

              <motion.button
                type="button"
                whileHover={canDeal ? { scale: 1.02 } : {}}
                whileTap={canDeal ? { scale: 0.98 } : {}}
                onClick={handleDeal}
                disabled={!canDeal}
                className={`relative w-full py-4 rounded-2xl font-black text-lg tracking-wider overflow-hidden ${
                  canDeal
                    ? 'text-white shadow-2xl shadow-amber-500/40'
                    : 'bg-slate-900/50 text-amber-600/40 cursor-not-allowed'
                }`}
                style={
                  canDeal
                    ? {
                        background:
                          'linear-gradient(135deg, #f59e0b 0%, #d97706 50%, #f59e0b 100%)',
                        backgroundSize: '200% 100%',
                        boxShadow:
                          '0 4px 20px rgba(245, 158, 11, 0.4), inset 0 1px 0 rgba(255,255,255,0.3)',
                      }
                    : undefined
                }
              >
                {canDeal && (
                  <motion.div
                    className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent"
                    animate={{ x: ['-100%', '200%'] }}
                    transition={{
                      duration: 2.5,
                      repeat: Infinity,
                      ease: 'easeInOut',
                    }}
                  />
                )}
                <span className="relative z-10 flex items-center justify-center gap-2 text-white drop-shadow-md">
                  <Crown className="w-5 h-5" />
                  发 牌
                  <Crown className="w-5 h-5" />
                </span>
              </motion.button>

              {playerState && betAmount > playerState.chipBalance && (
                <div className="mt-3 text-center text-xs text-rose-400">
                  余额不足，请减少下注金额
                </div>
              )}
              {betAmount < minBet && betAmount > 0 && (
                <div className="mt-3 text-center text-xs text-amber-400/70">
                  最低下注 {formatChips(minBet)} 筹码
                </div>
              )}
            </motion.div>
          )}

          {/* Action panel - player turn */}
          {isPlayerTurn && gameState && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4 }}
              className="bg-[#2a0a0a]/80 border border-amber-800/40 rounded-2xl p-4 shadow-lg backdrop-blur-sm"
            >
              <div className="text-center text-xs text-amber-300/70 mb-3">
                底注 <span className="font-bold text-amber-200">
                  {formatChips(gameState.betAmount)}
                </span> 筹码
                {' · '}
                跟注需再加 <span className="font-bold text-amber-200">
                  {formatChips(gameState.callAmount)}
                </span> 筹码
              </div>

              <div className="grid grid-cols-2 gap-3">
                <motion.button
                  type="button"
                  whileHover={!isProcessing ? { scale: 1.03 } : {}}
                  whileTap={!isProcessing ? { scale: 0.97 } : {}}
                  onClick={handleFold}
                  disabled={isProcessing}
                  className="py-3.5 rounded-xl font-bold text-sm bg-slate-800/60 text-slate-300 border border-slate-700/50 hover:border-rose-500/50 hover:text-rose-300 transition-all disabled:opacity-50"
                >
                  弃 牌
                  <div className="text-[10px] font-normal text-slate-400 mt-0.5">
                    损失底注
                  </div>
                </motion.button>

                <motion.button
                  type="button"
                  whileHover={!isProcessing ? { scale: 1.03 } : {}}
                  whileTap={!isProcessing ? { scale: 0.97 } : {}}
                  onClick={handleCall}
                  disabled={isProcessing}
                  className="relative py-3.5 rounded-xl font-bold text-sm overflow-hidden text-white shadow-lg shadow-amber-600/40 disabled:opacity-50"
                  style={{
                    background:
                      'linear-gradient(135deg, #f59e0b 0%, #d97706 50%, #f59e0b 100%)',
                    backgroundSize: '200% 100%',
                  }}
                >
                  {!isProcessing && (
                    <motion.div
                      className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent"
                      animate={{ x: ['-100%', '200%'] }}
                      transition={{
                        duration: 2,
                        repeat: Infinity,
                        ease: 'easeInOut',
                      }}
                    />
                  )}
                  <span className="relative z-10">
                    跟注开牌
                    <div className="text-[10px] font-normal text-amber-100/80 mt-0.5">
                      再加 {formatChips(gameState.callAmount)}
                    </div>
                  </span>
                </motion.button>
              </div>
            </motion.div>
          )}

          {/* Reset panel - after game */}
          {isFinished && gameState && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4 }}
              className="bg-[#2a0a0a]/80 border border-amber-800/40 rounded-2xl p-4 shadow-lg backdrop-blur-sm"
            >
              <motion.button
                type="button"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                onClick={handleReset}
                className="relative w-full py-4 rounded-2xl font-black text-lg tracking-wider overflow-hidden text-white shadow-2xl shadow-amber-500/40"
                style={{
                  background:
                    'linear-gradient(135deg, #f59e0b 0%, #d97706 50%, #f59e0b 100%)',
                  backgroundSize: '200% 100%',
                  boxShadow:
                    '0 4px 20px rgba(245, 158, 11, 0.4), inset 0 1px 0 rgba(255,255,255,0.3)',
                }}
              >
                <motion.div
                  className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent"
                  animate={{ x: ['-100%', '200%'] }}
                  transition={{
                    duration: 2.5,
                    repeat: Infinity,
                    ease: 'easeInOut',
                  }}
                />
                <span className="relative z-10 flex items-center justify-center gap-2 text-white drop-shadow-md">
                  <Sparkles className="w-5 h-5" />
                  再 来 一 局
                  <Sparkles className="w-5 h-5" />
                </span>
              </motion.button>
            </motion.div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TexasArena;
