import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAnimate, motion } from 'framer-motion';
import { toast } from 'sonner';
import {
  Coins,
  RotateCcw,
  ArrowLeft,
  Lock,
  Trophy,
  Sparkles,
  Lamp,
  Building2,
  Zap,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { soundManager, playSound } from '@client/src/utils/sound';
import { SoundToggleButton } from '@client/src/hooks/useSound';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { casinoApi } from '@client/src/api';
import type { PlayerState, SpinResult, CasinoInfo } from '@shared/api.interface';
import {
  CASINOS,
  getPlayerLevelInfo,
  getNextCasinoToUnlock,
  getWheelLevelByExp,
  getWheelExpProgress,
} from '@client/src/utils/casino-levels';
import WheelSvg, { WHEEL_SIZE, WHEEL_CONFIGS, buildSectors } from './WheelSvg';
import WheelLights from './WheelLights';
import ResultModal from './ResultModal';
import CasinoUnlockModal from './CasinoUnlockModal';

const MAX_RETRIES = 10;
const LEVEL_NAMES = ['一级轮盘', '二级轮盘', '三级轮盘'];
const WHEEL_COSTS: Record<number, number> = { 1: 0, 2: 200, 3: 1000 };

// ─── Helpers ──────────────────────────────────────────────────────────────────

function findResultSectorIndex(result: SpinResult, level: number): number {
  const cfg = WHEEL_CONFIGS[level];
  if (result.type === 'chip' && result.chipAmount !== undefined) {
    const idx = cfg.chipAmounts.indexOf(result.chipAmount);
    return idx >= 0 ? idx : 0;
  }
  if (result.type === 'retry') return 5;
  return 6;
}

function calcStopAngle(
  result: SpinResult,
  level: number,
  currentRotation: number,
): { angle: number; landingSectorIndex: number } {
  const sectors = buildSectors(level);
  const idx = findResultSectorIndex(result, level);
  const sector = sectors[idx];
  const margin = 2;
  const randomInSector =
    sector.startAngle +
    margin +
    Math.random() * (sector.endAngle - sector.startAngle - margin * 2);
  const targetMod = (360 - randomInSector + 360) % 360;
  const currentMod = ((currentRotation % 360) + 360) % 360;
  let delta = targetMod - currentMod;
  if (delta <= 0) delta += 360;
  const angle = delta + 360 * 5;
  return { angle, landingSectorIndex: idx };
}

// ─── Component ────────────────────────────────────────────────────────────────

const TenYuanArena: React.FC = () => {
  const navigate = useNavigate();
  const { playerState, setPlayerState, loading, token } = useGameAuth();
  const [currentLevel, setCurrentLevel] = useState<number>(1);
  const [isSpinning, setIsSpinning] = useState(false);
  const [showResult, setShowResult] = useState(false);
  const [lastResult, setLastResult] = useState<SpinResult | null>(null);
  const [currentRotation, setCurrentRotation] = useState(0);
  const rotationRef = useRef<number>(0);
  const [unlockedCasino, setUnlockedCasino] = useState<CasinoInfo | null>(null);
  const [wheelRef, animate] = useAnimate<SVGSVGElement>();
  const retryCountRef = useRef<number>(0);
  const autoSpinTriggeredRef = useRef<boolean>(false);
  const autoSpinStopRef = useRef<boolean>(false);

  // Redirect to login if not authenticated
  useEffect(() => {
    if (!loading && !token) {
      navigate('/login', { replace: true });
    }
  }, [loading, token, navigate]);

  const sectors = useMemo(() => buildSectors(currentLevel), [currentLevel]);

  const levelInfo = useMemo(
    () => (playerState ? getPlayerLevelInfo(playerState.experience) : null),
    [playerState],
  );

  const nextCasino = useMemo(
    () => (playerState ? getNextCasinoToUnlock(playerState.experience) : null),
    [playerState],
  );

  const wheelLevel = useMemo(
    () => (playerState ? getWheelLevelByExp(playerState.experience) : 1),
    [playerState],
  );

  const wheelProgress = useMemo(
    () => getWheelExpProgress(playerState?.experience ?? 0, currentLevel),
    [playerState, currentLevel],
  );

  useEffect(() => {
    if (playerState) {
      setCurrentLevel(getWheelLevelByExp(playerState.experience));
    }
  }, [playerState]);

  const handleLevelSwitch = useCallback(
    (level: number) => {
      if (isSpinning) return;
      if (wheelLevel < level) return;
      setCurrentLevel(level);
      setShowResult(false);
    },
    [isSpinning, wheelLevel],
  );

  const checkNewCasinoUnlock = useCallback((oldExp: number, newExp: number): CasinoInfo | null => {
    for (const casino of CASINOS) {
      if (oldExp < casino.unlockExp && newExp >= casino.unlockExp) {
        return casino;
      }
    }
    return null;
  }, []);

  const performSpin = useCallback(
    async (level: number, retryDepth: number = 0) => {
      if (!playerState) return;
      const prevExp = playerState.experience;

      setIsSpinning(true);
      setShowResult(false);

      try {
        // Call backend to settle the spin
        const result = await casinoApi.spinWheel(level);
        const { angle: relativeAngle } = calcStopAngle(
          result,
          level,
          rotationRef.current,
        );
        const targetRotation = rotationRef.current + relativeAngle;

        playSound('spinStart');
        await animate(
          wheelRef.current,
          { rotate: targetRotation },
          { duration: 3.5, ease: [0.17, 0.67, 0.24, 1] },
        );

        soundManager.playSpinSlowdown();
        setTimeout(() => {
          soundManager.stopSpin();
          playSound('tick');
        }, 200);

        setCurrentRotation(targetRotation);
        rotationRef.current = targetRotation;
        setPlayerState(result.player);
        setLastResult(result);
        setIsSpinning(false);

        const newCasino = checkNewCasinoUnlock(prevExp, result.player.experience);
        if (newCasino && newCasino.tier > 1) {
          setShowResult(true);
          setTimeout(() => {
            setUnlockedCasino(newCasino);
            playSound('levelUp');
          }, 800);
        } else if (result.type === 'retry' && retryDepth < MAX_RETRIES) {
          retryCountRef.current = retryDepth + 1;
          setShowResult(true);
          setTimeout(() => {
            setShowResult(false);
            void performSpin(level, retryDepth + 1);
          }, 1400);
         } else {
          if (result.type === 'chip') {
            playSound('win');
          } else if (result.type === 'thanks') {
            playSound('lose');
          }
          setShowResult(true);
          if (!autoSpinStopRef.current && playerState && getActiveAutoSpinLevel(playerState) > 0) {
            setTimeout(() => {
              setShowResult(false);
              scheduleNextAutoSpin();
            }, 1200);
          }
        }
      } catch (err) {
        logger.error('转动失败', err);
        const message =
          (err as { response?: { data?: { message?: string } } }).response?.data
            ?.message ?? '转动失败，请稍后再试';
        if (message.includes('筹码不足') || message.includes('不足')) {
          toast.error(message);
        }
        setIsSpinning(false);
        autoSpinStopRef.current = true;
      }
    },
    [animate, wheelRef, playerState, setPlayerState, checkNewCasinoUnlock],
  );

  const getActiveAutoSpinLevel = (state: PlayerState): 0 | 1 | 2 | 3 => {
    const unlocked = state.unlockedWheelLevel;
    let level: 0 | 1 | 2 | 3 = 0;
    if (state.zd1 && unlocked >= 1) level = 1;
    if (state.zd2 && unlocked >= 2) level = 2;
    if (state.zd3 && unlocked >= 3) level = 3;
    return level;
  };

  const scheduleNextAutoSpin = useCallback(() => {
    if (autoSpinStopRef.current) return;
    if (!playerState) return;
    const activeLevel = getActiveAutoSpinLevel(playerState);
    if (activeLevel === 0) {
      autoSpinStopRef.current = true;
      return;
    }
    const cost = WHEEL_COSTS[activeLevel] ?? 0;
    if (cost > 0 && playerState.chipBalance < cost) {
      toast.warning(`自动转盘已停止：${activeLevel}级轮盘需要 ${cost} 筹码，余额不足`);
      autoSpinStopRef.current = true;
      return;
    }
    setCurrentLevel(activeLevel);
    setTimeout(() => {
      if (autoSpinStopRef.current) return;
      void performSpin(activeLevel);
    }, 400);
  }, [playerState, performSpin]);

  const handleSpin = useCallback(() => {
    if (isSpinning) return;
    if (!playerState) return;
    const cost = WHEEL_COSTS[currentLevel] ?? 0;
    if (cost > 0 && playerState.chipBalance < cost) {
      toast.error('筹码不足，请前往贷款或先赚钱');
      return;
    }
    void performSpin(currentLevel);
  }, [isSpinning, playerState, performSpin, currentLevel]);

  useEffect(() => {
    if (
      !playerState ||
      isSpinning ||
      autoSpinTriggeredRef.current
    ) {
      return;
    }
    const activeLevel = getActiveAutoSpinLevel(playerState);
    if (activeLevel === 0) {
      const anyZdOn = playerState.zd1 || playerState.zd2 || playerState.zd3;
      if (anyZdOn) {
        const lockedLevel = playerState.zd3 ? 3 : playerState.zd2 ? 2 : 1;
        const expNeeded = lockedLevel === 2 ? 100 : lockedLevel === 3 ? 1000 : 0;
        toast.warning(`${lockedLevel}级轮盘未解锁（需${expNeeded}经验），无法自动转`);
      }
      autoSpinTriggeredRef.current = true;
      return;
    }
    const cost = WHEEL_COSTS[activeLevel] ?? 0;
    if (cost > 0 && playerState.chipBalance < cost) {
      toast.warning(`自动转盘取消：${activeLevel}级轮盘需要 ${cost} 筹码，余额不足`);
      autoSpinTriggeredRef.current = true;
      return;
    }
    autoSpinTriggeredRef.current = true;
    autoSpinStopRef.current = false;
    setCurrentLevel(activeLevel);
    setTimeout(() => {
      if (autoSpinStopRef.current) return;
      void performSpin(activeLevel);
    }, 600);
  }, [playerState, isSpinning, performSpin]);

  useEffect(() => {
    if (!playerState) return;
    if (getActiveAutoSpinLevel(playerState) === 0) {
      autoSpinStopRef.current = true;
    }
  }, [playerState?.zd1, playerState?.zd2, playerState?.zd3, playerState?.unlockedWheelLevel]);

  useEffect(() => {
    return () => {
      autoSpinStopRef.current = true;
    };
  }, []);

  const closeResult = useCallback(() => {
    setShowResult(false);
  }, []);

  const closeUnlockModal = useCallback(() => {
    setUnlockedCasino(null);
  }, []);

  const goToCasino = useCallback(() => {
    if (unlockedCasino) {
      navigate(unlockedCasino.path);
    }
  }, [unlockedCasino, navigate]);

  const formatChips = (n: number): string => n.toLocaleString('zh-CN');

  const getWheelUnlockExp = (lv: number): number => {
    if (lv === 1) return 0;
    if (lv === 2) return 100;
    return 1000;
  };

  const spinCost = WHEEL_COSTS[currentLevel] ?? 0;
  const canAfford = playerState ? playerState.chipBalance >= spinCost : false;
  const buttonDisabled = isSpinning || !playerState || !canAfford;

  const getButtonLabel = (): string => {
    if (currentLevel === 1) return '免费转动';
    if (currentLevel === 2) return '消耗 200 筹码';
    return '消耗 1000 筹码';
  };

  const getButtonDisabledLabel = (): string => {
    if (!canAfford && spinCost > 0) return '筹码不足';
    return '转动中...';
  };

  return (
    <div className="min-h-screen text-foreground flex flex-col relative overflow-hidden">
      {/* 街边赌场背景：深棕木纹 + 暖黄灯光 */}
      <div
        className="absolute inset-0 -z-10"
        style={{
          background: `
            radial-gradient(ellipse at 50% 0%, hsl(40 60% 25%) 0%, hsl(30 40% 12%) 40%, hsl(25 30% 8%) 80%),
            linear-gradient(180deg, hsl(25 35% 10%) 0%, hsl(20 25% 6%) 100%)
          `,
        }}
      />
      <div
        className="absolute inset-0 -z-10 opacity-20"
        style={{
          backgroundImage: `repeating-linear-gradient(
            90deg, transparent 0px, transparent 2px,
            hsl(25 40% 20%) 2px, hsl(25 40% 20%) 3px
          )`,
        }}
      />
      <div
        className="absolute top-0 left-1/2 -translate-x-1/2 -z-10 w-[600px] h-[400px] opacity-30"
        style={{
          background: 'radial-gradient(ellipse at center top, hsl(40 100% 55%) 0%, transparent 70%)',
        }}
      />

      {/* 顶部标题栏 */}
      <header className="flex items-center justify-between px-4 py-3 border-b border-amber-900/50 bg-[hsl(25_35%_12%)]/80 backdrop-blur-sm">
        <button
          type="button"
          onClick={() => {
            playSound('click');
            navigate('/');
          }}
          className="p-2 rounded-lg hover:bg-amber-900/30 transition-colors"
          aria-label="返回"
        >
          <ArrowLeft className="w-5 h-5 text-amber-200" />
        </button>
        <div className="flex items-center gap-2">
          <Lamp className="w-5 h-5 text-amber-400" />
          <h1 className="text-base font-bold text-amber-100 tracking-wide">街边赌场 · 幸运轮盘</h1>
        </div>
        <div className="flex items-center gap-2">
          <SoundToggleButton className="text-amber-200 hover:text-amber-100" />
          <div className="flex items-center gap-1.5 bg-amber-950/60 px-3 py-1.5 rounded-full border border-amber-700/40">
            <Coins className="w-4 h-4 text-amber-400" />
            <span className="text-sm font-semibold text-amber-200">
              {playerState ? formatChips(playerState.chipBalance) : '--'}
            </span>
          </div>
        </div>
      </header>

      {/* 玩家信息区 */}
      <div className="px-4 pt-4">
        <div className="bg-[hsl(25_35%_14%)]/90 border border-amber-800/40 rounded-xl p-4 shadow-lg">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-amber-500 to-amber-700 flex items-center justify-center shadow-md shadow-amber-900/50">
                <Trophy className="w-5 h-5 text-amber-100" />
              </div>
              <div>
                <div className="text-sm font-bold text-amber-100">
                  Lv.{levelInfo?.level ?? 1} · {levelInfo?.levelName ?? '新手赌客'}
                </div>
                <div className="text-xs text-amber-400/70">
                  经验 {levelInfo?.currentExp ?? 0} / {levelInfo?.nextLevelExp ?? 50}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-1 text-xs text-amber-300/80">
              <Coins className="w-3.5 h-3.5 text-amber-400" />
              <span className="font-semibold">{playerState ? formatChips(playerState.chipBalance) : '--'}</span>
            </div>
          </div>
          <div className="h-1.5 bg-amber-950/60 rounded-full overflow-hidden mb-3">
            <motion.div
              className="h-full bg-gradient-to-r from-amber-500 to-amber-300 rounded-full"
              initial={{ width: 0 }}
              animate={{ width: `${levelInfo?.progress ?? 0}%` }}
              transition={{ duration: 0.6, ease: 'easeOut' }}
            />
          </div>
          {nextCasino ? (
            <div className="flex items-center justify-between text-xs bg-amber-950/40 rounded-lg px-3 py-2 border border-amber-800/30">
              <div className="flex items-center gap-2">
                <Building2 className="w-3.5 h-3.5 text-amber-500" />
                <span className="text-amber-300/90">下一座：{nextCasino.name}</span>
              </div>
              <div className="flex items-center gap-1 text-amber-400">
                <Zap className="w-3 h-3" />
                <span>还差 {nextCasino.unlockExp - (playerState?.experience ?? 0)} 经验</span>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-center gap-1 text-xs text-amber-400 py-1">
              <Sparkles className="w-3 h-3" />
              <span>已解锁全部赌场，传奇玩家！</span>
            </div>
          )}
        </div>
      </div>

      {/* 轮盘等级 Tab */}
      <div className="px-4 pt-4">
        <div className="flex gap-2 bg-[hsl(25_35%_14%)]/70 p-1.5 rounded-xl border border-amber-800/40">
          {[1, 2, 3].map((lv) => {
            const unlocked = wheelLevel >= lv;
            const active = currentLevel === lv;
            return (
              <button
                key={lv}
                type="button"
                onClick={() => handleLevelSwitch(lv)}
                disabled={!unlocked || isSpinning}
                className={`
                  flex-1 flex flex-col items-center gap-1 py-2 rounded-lg transition-all text-xs
                  ${active
                    ? 'bg-gradient-to-b from-amber-500 to-amber-600 text-amber-950 font-bold shadow-md shadow-amber-900/50'
                    : ''
                  }
                  ${!active && unlocked ? 'text-amber-300/70 hover:bg-amber-900/30 hover:text-amber-200' : ''}
                  ${!unlocked ? 'text-amber-700/60 cursor-not-allowed' : ''}
                `}
              >
                {unlocked ? (
                  <Trophy className={`w-4 h-4 ${active ? 'text-amber-950' : 'text-amber-400'}`} />
                ) : (
                  <Lock className="w-4 h-4" />
                )}
                <span>{LEVEL_NAMES[lv - 1]}</span>
                <span className="text-[10px] opacity-80">
                  {lv === 1
                    ? '初始解锁'
                    : unlocked ? '已解锁' : `${getWheelUnlockExp(lv)}经验解锁`}
                </span>
              </button>
            );
          })}
        </div>
        {!wheelProgress.isMax && (
          <div className="mt-2 px-1">
            <div className="flex items-center justify-between text-[11px] text-amber-400/60 mb-1">
              <span>距下一级轮盘</span>
              <span>{wheelProgress.progress}%</span>
            </div>
            <div className="h-1 bg-amber-950/50 rounded-full overflow-hidden">
              <motion.div
                className="h-full bg-amber-500/60 rounded-full"
                initial={{ width: 0 }}
                animate={{ width: `${wheelProgress.progress}%` }}
                transition={{ duration: 0.5 }}
              />
            </div>
          </div>
        )}
      </div>

      {/* 轮盘主体 */}
      <div className="flex-1 flex flex-col items-center justify-center px-4 py-6">
        <div className="relative" style={{ width: WHEEL_SIZE + 40, height: WHEEL_SIZE + 60 }}>
          {/* 赌桌底座 */}
          <div
            className="absolute bottom-0 left-1/2 -translate-x-1/2 rounded-[50%]"
            style={{
              width: WHEEL_SIZE + 40,
              height: 50,
              background: `linear-gradient(180deg,
                hsl(25 50% 30%) 0%, hsl(20 45% 20%) 50%, hsl(15 40% 15%) 100%)`,
              boxShadow: `inset 0 2px 6px hsl(40 60% 40% / 0.4),
                inset 0 -4px 8px hsl(0 0% 0% / 0.5),
                0 8px 20px hsl(0 0% 0% / 0.6)`,
              borderTop: '2px solid hsl(25 40% 40%)',
            }}
          />
          <div
            className="absolute bottom-8 left-1/2 -translate-x-1/2 rounded-t-2xl"
            style={{
              width: WHEEL_SIZE + 20,
              height: 20,
              background: `linear-gradient(90deg,
                hsl(25 40% 25%) 0%, hsl(30 45% 30%) 25%,
                hsl(25 40% 28%) 50%, hsl(30 45% 32%) 75%,
                hsl(25 40% 25%) 100%)`,
              borderTop: '1px solid hsl(25 40% 45%)',
              borderLeft: '1px solid hsl(25 40% 35%)',
              borderRight: '1px solid hsl(25 40% 35%)',
            }}
          />

          {/* 轮盘 + 装饰灯 */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2" style={{ width: WHEEL_SIZE, height: WHEEL_SIZE }}>
            <WheelLights />
            <WheelSvg ref={wheelRef} sectors={sectors} />
          </div>

          {/* 指针 */}
          <div className="absolute left-1/2 -translate-x-1/2 z-20" style={{ top: -4 }}>
            <svg width="32" height="40" viewBox="0 0 32 40">
              <polygon points="16,40 0,6 32,6" fill="hsl(30 90% 50%)" stroke="hsl(20 80% 30%)" strokeWidth="2" />
              <circle cx="16" cy="10" r="5" fill="hsl(20 80% 25%)" />
              <circle cx="16" cy="10" r="2.5" fill="hsl(40 100% 60%)" />
            </svg>
          </div>
        </div>

        {/* 转动按钮 */}
        <button
          type="button"
          onClick={handleSpin}
          disabled={buttonDisabled}
          className={`
            mt-8 w-36 h-36 rounded-full font-bold text-base
            flex flex-col items-center justify-center gap-1
            transition-all relative
            ${buttonDisabled
              ? 'bg-amber-900/50 text-amber-600/70 cursor-not-allowed'
              : 'bg-gradient-to-b from-amber-400 via-amber-500 to-amber-600 text-amber-950 hover:scale-105 active:scale-95 shadow-xl shadow-amber-900/60'
            }
          `}
          style={{
            border: '4px solid hsl(25 70% 40%)',
            boxShadow: buttonDisabled ? 'none' : `
              inset 0 2px 4px hsl(40 100% 80% / 0.6),
              inset 0 -4px 8px hsl(20 80% 30% / 0.6),
              0 8px 20px hsl(0 0% 0% / 0.5)
            `,
          }}
        >
          {isSpinning ? (
            <>
              <RotateCcw className="w-7 h-7 animate-spin" />
              <span>转动中...</span>
            </>
          ) : !canAfford && spinCost > 0 ? (
            <>
              <Coins className="w-7 h-7" />
              <span className="font-black tracking-wider">筹码不足</span>
              <span className="text-[11px] opacity-80 font-normal">去贷款赚钱</span>
            </>
          ) : (
            <>
              <Sparkles className="w-7 h-7" />
              <span className="font-black tracking-wider">转动轮盘</span>
              <span className="text-[11px] opacity-80 font-normal">{getButtonLabel()}</span>
            </>
          )}
        </button>
      </div>

      {/* 结果弹窗 */}
      <ResultModal
        result={lastResult}
        show={showResult}
        onClose={closeResult}
        formatChips={formatChips}
      />

      {/* 新赌场解锁成就弹窗 */}
      <CasinoUnlockModal
        casino={unlockedCasino}
        onClose={closeUnlockModal}
        onGo={goToCasino}
      />
    </div>
  );
};

export default TenYuanArena;
