import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Coins,
  ArrowLeft,
  Trophy,
  Sparkles,
  Zap,
  Building2,
  Lock,
  AlertTriangle,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { useAutoSave } from '@client/src/hooks/useAutoSave';
import { casinoApi } from '@client/src/api';
import type {
  PlayerState,
  BetResult,
  SicBoBetType,
  SicBoResultDetail,
  CasinoInfo,
  CasinoTier,
} from '@shared/api.interface';
import {
  CASINOS,
  getPlayerLevelInfo,
  getNextCasinoToUnlock,
  isCasinoUnlocked,
} from '@client/src/utils/casino-levels';
import { playSound } from '@client/src/utils/sound';

const DEFAULT_MIN_BET = 10;
const QUICK_CHIPS = [10, 50, 100, 500];

const TIER_MIN_BET: Record<number, number> = {
  2: 10,
  3: 100,
  4: 1000,
  5: 10000,
};

const TIER_PATH: Record<number, string> = {
  2: '/hundred-yuan',
  3: '/thousand-yuan',
  4: '/ten-thousand-yuan',
  5: '/million-yuan',
};

const BET_OPTIONS: { type: SicBoBetType; label: string; sub: string; color: string }[] = [
  { type: 'big', label: '大', sub: '11-17 不含全围', color: 'fuchsia' },
  { type: 'small', label: '小', sub: '4-10 不含全围', color: 'cyan' },
  { type: 'odd', label: '单', sub: '奇数和 不含全围', color: 'fuchsia' },
  { type: 'even', label: '双', sub: '偶数和 不含全围', color: 'cyan' },
];

function DiceFace({ value, size = 70 }: { value: number; size?: number }): React.ReactElement {
  const dotPositions: Record<number, [number, number][]> = {
    1: [[50, 50]],
    2: [[25, 25], [75, 75]],
    3: [[25, 25], [50, 50], [75, 75]],
    4: [[25, 25], [75, 25], [25, 75], [75, 75]],
    5: [[25, 25], [75, 25], [50, 50], [25, 75], [75, 75]],
    6: [[25, 20], [75, 20], [25, 50], [75, 50], [25, 80], [75, 80]],
  };
  const dots = dotPositions[value] ?? dotPositions[1];
  const dotR = size * 0.09;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      className="drop-shadow-[0_0_12px_rgba(217_70_239_0.5)]"
    >
      <defs>
        <linearGradient id={`dice-bg-${value}`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#2d0a4e" />
          <stop offset="50%" stopColor="#1a0533" />
          <stop offset="100%" stopColor="#0a0a2e" />
        </linearGradient>
      </defs>
      <rect
        x="2"
        y="2"
        width="96"
        height="96"
        rx="18"
        fill={`url(#dice-bg-${value})`}
        stroke="url(#dice-border)"
        strokeWidth="2"
      />
      <defs>
        <linearGradient id="dice-border" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#d946ef" />
          <stop offset="100%" stopColor="#22d3ee" />
        </linearGradient>
      </defs>
      {dots.map(([cx, cy], i) => (
        <circle
          key={i}
          cx={cx}
          cy={cy}
          r={dotR * (100 / size)}
          fill="#f0abfc"
          style={{
            filter: 'drop-shadow(0 0 4px rgba(240, 171, 252, 0.8))',
          }}
        />
      ))}
    </svg>
  );
}

const SicBoArena: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const path = location.pathname;
  let tier: CasinoTier | null = null;
  if (path.startsWith('/hundred-yuan')) tier = 2;
  else if (path.startsWith('/thousand-yuan')) tier = 3;
  else if (path.startsWith('/ten-thousand-yuan')) tier = 4;
  else if (path.startsWith('/million-yuan')) tier = 5;

  const minBet = tier ? TIER_MIN_BET[tier] ?? DEFAULT_MIN_BET : DEFAULT_MIN_BET;
  const backPath = tier ? TIER_PATH[tier] ?? '/' : '/';

  const { playerState, setPlayerState, loading, token } = useGameAuth();
  const [selectedBet, setSelectedBet] = useState<SicBoBetType>('big');
  const [betAmount, setBetAmount] = useState<number>(minBet);
  const [customAmount, setCustomAmount] = useState<string>('');
  const [isRolling, setIsRolling] = useState(false);
  const [diceValues, setDiceValues] = useState<[number, number, number]>([1, 1, 1]);
  const [lastResult, setLastResult] = useState<BetResult | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [unlockedCasino, setUnlockedCasino] = useState<CasinoInfo | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');

  useAutoSave(playerState);

  useEffect(() => {
    if (!loading && !token) {
      navigate('/login', { replace: true });
    }
  }, [loading, token, navigate]);

  useEffect(() => {
    setBetAmount(minBet);
  }, [minBet]);

  const levelInfo = useMemo(
    () => (playerState ? getPlayerLevelInfo(playerState.experience) : null),
    [playerState],
  );

  const nextCasino = useMemo(
    () => (playerState ? getNextCasinoToUnlock(playerState.experience) : null),
    [playerState],
  );

  const isUnlocked = useMemo(
    () => (playerState ? isCasinoUnlocked(playerState.experience, 2) : false),
    [playerState],
  );

  const checkNewCasinoUnlock = useCallback(
    (oldExp: number, newExp: number): CasinoInfo | null => {
      for (const casino of CASINOS) {
        if (oldExp < casino.unlockExp && newExp >= casino.unlockExp) {
          return casino;
        }
      }
      return null;
    },
    [],
  );

  const formatChips = (n: number): string => n.toLocaleString('zh-CN');

  const canBet = useMemo(() => {
    if (!playerState) return false;
    if (!isUnlocked) return false;
    if (isRolling) return false;
    if (betAmount < minBet) return false;
    if (betAmount > playerState.chipBalance) return false;
    return true;
  }, [playerState, isUnlocked, isRolling, betAmount]);

  const handleQuickChip = useCallback((amount: number) => {
    setBetAmount(amount);
    setCustomAmount('');
    setErrorMsg('');
  }, []);

  const handleCustomAmountChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '');
      setCustomAmount(val);
      const num = val === '' ? 0 : parseInt(val, 10);
      setBetAmount(num);
      setErrorMsg('');
    },
    [],
  );

  const handleBetTypeSelect = useCallback((type: SicBoBetType) => {
    if (isRolling) return;
    setSelectedBet(type);
    setShowResult(false);
  }, [isRolling]);

  const rollDiceAnimation = useCallback(async (): Promise<void> => {
    const totalDuration = 1500;
    const intervalMs = 100;
    const steps = totalDuration / intervalMs;
    for (let i = 0; i < steps; i++) {
      setDiceValues([
        Math.floor(Math.random() * 6) + 1,
        Math.floor(Math.random() * 6) + 1,
        Math.floor(Math.random() * 6) + 1,
      ]);
      await new Promise<void>((resolve) => {
        setTimeout(resolve, intervalMs);
      });
    }
  }, []);

  const handleStart = useCallback(async () => {
    if (!playerState || !canBet) return;
    const prevExp = playerState.experience;

    playSound('chip');
    setIsRolling(true);
    setShowResult(false);
    setErrorMsg('');
    playSound('diceRoll', 1000);

    try {
      const resultPromise = casinoApi.placeSicBoBet(selectedBet, betAmount, tier ?? 2);

      void rollDiceAnimation();

      const result: BetResult = await resultPromise;
      const detail = result.result as unknown as SicBoResultDetail;

      setDiceValues(detail.dice);
      setPlayerState(result.player);
      setLastResult(result);
      setIsRolling(false);
      setShowResult(true);
      if (result.win) {
        playSound('win');
      } else {
        playSound('lose');
      }

      const newCasino = checkNewCasinoUnlock(prevExp, result.player.experience);
      if (newCasino && newCasino.tier > 2) {
        setTimeout(() => {
          setUnlockedCasino(newCasino);
        }, 1200);
      }
    } catch (err) {
      const message =
        (err as { response?: { data?: { message?: string } } }).response?.data
          ?.message ?? (err as Error).message ?? '下注失败';
      setErrorMsg(message);
      setIsRolling(false);
      logger.error('骰宝下注失败', err);
    }
  }, [
    playerState,
    canBet,
    selectedBet,
    betAmount,
    rollDiceAnimation,
    setPlayerState,
    checkNewCasinoUnlock,
  ]);

  const closeUnlockModal = useCallback(() => {
    setUnlockedCasino(null);
  }, []);

  const goToCasino = useCallback(() => {
    if (unlockedCasino) {
      navigate(unlockedCasino.path);
    }
  }, [unlockedCasino, navigate]);

  const resultDetail = lastResult
    ? (lastResult.result as unknown as SicBoResultDetail)
    : null;

  const getBetLabel = (type: SicBoBetType): string => {
    const opt = BET_OPTIONS.find((o) => o.type === type);
    return opt?.label ?? type;
  };

  return (
    <div className="min-h-screen text-foreground flex flex-col relative overflow-hidden">
      <div
        className="absolute inset-0 -z-10"
        style={{
          background: `
            radial-gradient(ellipse at 50% 0%, hsl(280 70% 25%) 0%, hsl(260 50% 10%) 40%, hsl(240 60% 6%) 80%),
            linear-gradient(180deg, hsl(260 50% 8%) 0%, hsl(240 60% 4%) 100%)
          `,
        }}
      />
      <div
        className="absolute inset-0 -z-10 opacity-10"
        style={{
          backgroundImage: `repeating-linear-gradient(
            90deg, transparent 0px, transparent 2px,
            hsl(280 60% 40%) 2px, hsl(280 60% 40%) 3px
          ), repeating-linear-gradient(
            0deg, transparent 0px, transparent 2px,
            hsl(200 60% 40%) 2px, hsl(200 60% 40%) 3px
          )`,
        }}
      />
      <div
        className="absolute top-0 left-1/2 -translate-x-1/2 -z-10 w-[600px] h-[500px] opacity-40"
        style={{
          background:
            'radial-gradient(ellipse at center top, hsl(300 100% 60%) 0%, transparent 50%), radial-gradient(ellipse at 30% 20%, hsl(190 100% 50%) 0%, transparent 40%)',
        }}
      />

      <header className="flex items-center justify-between px-4 py-3 border-b border-fuchsia-900/40 bg-[hsl(260_50%_10%)]/80 backdrop-blur-sm">
        <button
          type="button"
          onClick={() => {
            playSound('click');
            navigate(backPath);
          }}
          className="p-2 rounded-lg hover:bg-fuchsia-900/30 transition-colors"
          aria-label="返回"
        >
          <ArrowLeft className="w-5 h-5 text-fuchsia-200" />
        </button>
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-fuchsia-400" />
          <h1 className="text-base font-bold bg-gradient-to-r from-fuchsia-300 via-fuchsia-200 to-cyan-300 bg-clip-text text-transparent tracking-wide">
            霓虹赌场 · 骰宝
          </h1>
        </div>
        <div className="flex items-center gap-1.5 bg-fuchsia-950/60 px-3 py-1.5 rounded-full border border-fuchsia-700/40">
          <Coins className="w-4 h-4 text-fuchsia-400" />
          <span className="text-sm font-semibold text-fuchsia-200">
            {playerState ? formatChips(playerState.chipBalance) : '--'}
          </span>
        </div>
      </header>

      <div className="px-4 pt-4">
        <div className="bg-[hsl(260_50%_12%)]/90 border border-fuchsia-800/40 rounded-xl p-4 shadow-lg backdrop-blur-sm">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-fuchsia-500 to-cyan-500 flex items-center justify-center shadow-md shadow-fuchsia-900/50">
                <Trophy className="w-5 h-5 text-white" />
              </div>
              <div>
                <div className="text-sm font-bold text-fuchsia-100">
                  Lv.{levelInfo?.level ?? 1} · {levelInfo?.levelName ?? '新手赌客'}
                </div>
                <div className="text-xs text-fuchsia-400/70">
                  经验 {levelInfo?.currentExp ?? 0} / {levelInfo?.nextLevelExp ?? 50}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-1 text-xs text-cyan-300/80">
              <Coins className="w-3.5 h-3.5 text-cyan-400" />
              <span className="font-semibold">
                {playerState ? formatChips(playerState.chipBalance) : '--'}
              </span>
            </div>
          </div>
          <div className="h-1.5 bg-fuchsia-950/60 rounded-full overflow-hidden mb-3">
            <motion.div
              className="h-full bg-gradient-to-r from-fuchsia-500 to-cyan-400 rounded-full"
              initial={{ width: 0 }}
              animate={{ width: `${levelInfo?.progress ?? 0}%` }}
              transition={{ duration: 0.6, ease: 'easeOut' }}
            />
          </div>
          {nextCasino ? (
            <div className="flex items-center justify-between text-xs bg-fuchsia-950/40 rounded-lg px-3 py-2 border border-fuchsia-800/30">
              <div className="flex items-center gap-2">
                <Building2 className="w-3.5 h-3.5 text-cyan-400" />
                <span className="text-cyan-300/90">下一座：{nextCasino.name}</span>
              </div>
              <div className="flex items-center gap-1 text-fuchsia-400">
                <Zap className="w-3 h-3" />
                <span>还差 {nextCasino.unlockExp - (playerState?.experience ?? 0)} 经验</span>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-center gap-1 text-xs text-cyan-400 py-1">
              <Sparkles className="w-3 h-3" />
              <span>已解锁全部赌场，传奇玩家！</span>
            </div>
          )}
        </div>
      </div>

      <div className="px-4 pt-5">
        <div className="text-center mb-3">
          <h2 className="text-sm font-medium text-fuchsia-200/80">
            三颗骰子定乾坤，大小单双任你选
          </h2>
          <p className="text-[11px] text-fuchsia-500/60 mt-0.5">庄家优势约 2.78%（全围通杀）</p>
        </div>

        <div
          className="flex justify-center items-center gap-6 py-8 rounded-2xl border border-fuchsia-800/30 bg-[hsl(260_50%_10%)]/60 backdrop-blur-sm"
          style={{
            boxShadow:
              'inset 0 0 30px rgba(217, 70, 239, 0.1), 0 0 20px rgba(34, 211, 238, 0.1)',
          }}
        >
          <motion.div
            animate={
              isRolling
                ? {
                    y: [0, -15, 0, -10, 0],
                    rotate: [0, -15, 10, -5, 0],
                    x: [0, 5, -3, 2, 0],
                  }
                : { y: 0, rotate: 0, x: 0 }
            }
            transition={
              isRolling
                ? { duration: 0.3, repeat: Infinity, ease: 'easeInOut' }
                : { duration: 0.3, ease: 'easeOut' }
            }
          >
            <DiceFace value={diceValues[0]} size={70} />
          </motion.div>
          <motion.div
            animate={
              isRolling
                ? {
                    y: [0, -18, 0, -12, 0],
                    rotate: [0, 15, -10, 8, 0],
                    x: [0, -3, 5, -2, 0],
                  }
                : { y: 0, rotate: 0, x: 0 }
            }
            transition={
              isRolling
                ? { duration: 0.32, repeat: Infinity, ease: 'easeInOut' }
                : { duration: 0.3, ease: 'easeOut' }
            }
          >
            <DiceFace value={diceValues[1]} size={70} />
          </motion.div>
          <motion.div
            animate={
              isRolling
                ? {
                    y: [0, -12, 0, -16, 0],
                    rotate: [0, -10, 12, -8, 0],
                    x: [0, 4, -5, 3, 0],
                  }
                : { y: 0, rotate: 0, x: 0 }
            }
            transition={
              isRolling
                ? { duration: 0.35, repeat: Infinity, ease: 'easeInOut' }
                : { duration: 0.3, ease: 'easeOut' }
            }
          >
            <DiceFace value={diceValues[2]} size={70} />
          </motion.div>
        </div>

        <AnimatePresence mode="wait">
          {showResult && resultDetail && lastResult && (
            <motion.div
              key="result"
              initial={{ opacity: 0, y: -10, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.95 }}
              transition={{ duration: 0.3 }}
              className={`mt-4 rounded-xl p-4 text-center border ${
                resultDetail.isTriple
                  ? 'bg-amber-950/40 border-amber-500/60'
                  : lastResult.win
                    ? 'bg-cyan-950/40 border-cyan-500/50'
                    : 'bg-fuchsia-950/40 border-fuchsia-700/40'
              }`}
              style={{
                boxShadow: resultDetail.isTriple
                  ? '0 0 25px rgba(245, 158, 11, 0.5)'
                  : lastResult.win
                    ? '0 0 20px rgba(34, 211, 238, 0.3)'
                    : '0 0 15px rgba(217, 70, 239, 0.15)',
              }}
            >
              {resultDetail.isTriple && (
                <div className="flex items-center justify-center gap-1.5 mb-2">
                  <AlertTriangle className="w-4 h-4 text-amber-400" />
                  <span className="text-sm font-bold text-amber-300 tracking-wider">
                    全围通杀！
                  </span>
                </div>
              )}
              <div className="flex items-center justify-center gap-2 mb-2">
                <span className="text-xs text-fuchsia-300/70">点数</span>
                <span
                  className={`text-xl font-bold ${
                    resultDetail.isTriple
                      ? 'text-amber-300'
                      : lastResult.win
                        ? 'text-cyan-300'
                        : 'text-fuchsia-400'
                  }`}
                >
                  {resultDetail.sum}
                </span>
                <span className="text-xs text-fuchsia-300/70">
                  ({resultDetail.isBig ? '大' : '小'} · {resultDetail.isOdd ? '单' : '双'})
                </span>
              </div>
              <div
                className={`text-lg font-bold ${
                  resultDetail.isTriple
                    ? 'text-amber-300'
                    : lastResult.win
                      ? 'text-cyan-300'
                      : 'text-fuchsia-400'
                }`}
              >
                {lastResult.win ? (
                  <>
                    <Sparkles className="w-5 h-5 inline mr-1 text-cyan-300" />
                    赢了 +{formatChips(lastResult.winAmount)} 筹码
                  </>
                ) : (
                  <>
                    输了 {formatChips(Math.abs(lastResult.winAmount))} 筹码
                  </>
                )}
              </div>
              <div className="text-[11px] text-fuchsia-400/60 mt-1">
                +{lastResult.expGained} 经验
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {isRolling && (
          <div className="mt-4 text-center">
            <span className="text-sm text-cyan-300/80 animate-pulse">开骰中...</span>
          </div>
        )}
      </div>

      <div className="px-4 pt-5 pb-8">
        <div className="text-xs text-fuchsia-300/60 mb-2 font-medium">选择下注类型</div>
        <div className="grid grid-cols-2 gap-3 mb-5">
          {BET_OPTIONS.map((opt) => {
            const active = selectedBet === opt.type;
            const isFuchsia = opt.color === 'fuchsia';
            return (
              <motion.button
                key={opt.type}
                type="button"
                onClick={() => handleBetTypeSelect(opt.type)}
                disabled={isRolling || !isUnlocked}
                whileHover={!isRolling && isUnlocked ? { scale: 1.02 } : {}}
                whileTap={!isRolling && isUnlocked ? { scale: 0.97 } : {}}
                className={`
                  relative py-4 rounded-xl font-bold text-lg
                  transition-all border
                  ${active
                    ? isFuchsia
                      ? 'bg-gradient-to-br from-fuchsia-600/40 to-fuchsia-900/40 border-fuchsia-400/70 text-fuchsia-100'
                      : 'bg-gradient-to-br from-cyan-600/40 to-cyan-900/40 border-cyan-400/70 text-cyan-100'
                    : 'bg-[hsl(260_50%_12%)]/70 border-fuchsia-900/40 text-fuchsia-200/70 hover:border-fuchsia-700/50'
                  }
                  ${!isUnlocked ? 'opacity-50 cursor-not-allowed' : ''}
                `}
                style={
                  active && isUnlocked
                    ? {
                        boxShadow: isFuchsia
                          ? '0 0 20px rgba(217, 70, 239, 0.4), inset 0 0 15px rgba(217, 70, 239, 0.2)'
                          : '0 0 20px rgba(34, 211, 238, 0.4), inset 0 0 15px rgba(34, 211, 238, 0.2)',
                      }
                    : {}
                }
              >
                <div className="text-2xl font-black tracking-wider">{opt.label}</div>
                <div className="text-[11px] font-normal opacity-70 mt-0.5">
                  {opt.sub}
                </div>
              </motion.button>
            );
          })}
        </div>

        <div className="text-xs text-fuchsia-300/60 mb-2 font-medium">下注金额</div>
        <div className="grid grid-cols-4 gap-2 mb-3">
          {QUICK_CHIPS.map((chip) => {
            const active = betAmount === chip && customAmount === '';
            return (
              <motion.button
                key={chip}
                type="button"
                onClick={() => handleQuickChip(chip)}
                disabled={isRolling || !isUnlocked}
                whileHover={!isRolling && isUnlocked ? { scale: 1.05 } : {}}
                whileTap={!isRolling && isUnlocked ? { scale: 0.95 } : {}}
                className={`
                  py-2.5 rounded-lg text-sm font-bold border transition-all
                  ${active
                    ? 'bg-gradient-to-br from-fuchsia-500/80 to-cyan-500/80 border-fuchsia-400/70 text-white'
                    : 'bg-[hsl(260_50%_12%)]/70 border-fuchsia-900/40 text-fuchsia-200/80 hover:border-fuchsia-700/50'
                  }
                  ${!isUnlocked ? 'opacity-50 cursor-not-allowed' : ''}
                `}
                style={
                  active && isUnlocked
                    ? { boxShadow: '0 0 12px rgba(217, 70, 239, 0.4)' }
                    : {}
                }
              >
                {chip}
              </motion.button>
            );
          })}
        </div>

        <div className="relative mb-4">
          <input
            type="text"
            value={customAmount}
            onChange={handleCustomAmountChange}
            disabled={isRolling || !isUnlocked}
            placeholder="自定义金额"
            className="w-full px-4 py-3 rounded-xl bg-[hsl(260_50%_12%)]/70 border border-fuchsia-900/40 text-fuchsia-100 placeholder:text-fuchsia-500/40 text-sm focus:outline-none focus:border-cyan-400/60 focus:ring-1 focus:ring-cyan-400/40 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 text-fuchsia-400/70">
            <Coins className="w-4 h-4" />
            <span className="text-xs">筹码</span>
          </div>
        </div>

        {errorMsg && (
          <div className="mb-3 text-xs text-fuchsia-300/80 bg-fuchsia-950/40 border border-fuchsia-700/40 rounded-lg px-3 py-2">
            {errorMsg}
          </div>
        )}

        {playerState && betAmount > playerState.chipBalance && (
          <div className="mb-3 text-xs text-fuchsia-300/80 bg-fuchsia-950/40 border border-fuchsia-700/40 rounded-lg px-3 py-2">
            余额不足，当前筹码 {formatChips(playerState.chipBalance)}
          </div>
        )}

        <motion.button
          type="button"
          onClick={handleStart}
          disabled={!canBet}
          whileHover={canBet ? { scale: 1.02 } : {}}
          whileTap={canBet ? { scale: 0.98 } : {}}
          className={`
            w-full py-4 rounded-xl font-bold text-base
            transition-all relative overflow-hidden
            ${canBet
              ? 'bg-gradient-to-r from-fuchsia-600 via-fuchsia-500 to-cyan-500 text-white cursor-pointer'
              : 'bg-fuchsia-950/40 text-fuchsia-600/60 cursor-not-allowed border border-fuchsia-900/40'
            }
          `}
          style={
            canBet
              ? {
                  boxShadow:
                    '0 0 25px rgba(217, 70, 239, 0.5), 0 0 15px rgba(34, 211, 238, 0.3)',
                }
              : {}
          }
        >
          {isRolling ? (
            <span className="flex items-center justify-center gap-2">
              <motion.span
                animate={{ rotate: 360 }}
                transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
              >
                <Sparkles className="w-5 h-5" />
              </motion.span>
              开骰中...
            </span>
          ) : (
            <span className="flex items-center justify-center gap-2">
              <Zap className="w-5 h-5" />
              下注 {getBetLabel(selectedBet)} · {formatChips(betAmount)} 筹码
            </span>
          )}
          {canBet && (
            <motion.div
              className="absolute inset-0 bg-white/20"
              initial={{ x: '-100%', skewX: -12 }}
              animate={{ x: '200%' }}
              transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
            />
          )}
        </motion.button>

        <div className="mt-3 text-center text-[11px] text-fuchsia-500/50">
          最低下注 {minBet} 筹码
        </div>
      </div>

      <AnimatePresence>
        {!isUnlocked && playerState && (
          <motion.div
            key="lock-overlay"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-40 flex items-center justify-center bg-black/70 backdrop-blur-md px-4"
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ type: 'spring', stiffness: 200, damping: 25 }}
              className="w-full max-w-sm rounded-2xl p-6 text-center relative overflow-hidden"
              style={{
                background:
                  'linear-gradient(135deg, hsl(260 50% 12%) 0%, hsl(240 60% 8%) 100%)',
                border: '1px solid hsla(280, 70%, 50%, 0.4)',
                boxShadow:
                  '0 0 40px rgba(217, 70, 239, 0.25), 0 0 60px rgba(34, 211, 238, 0.1)',
              }}
            >
              <div className="relative">
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-fuchsia-800/60 to-fuchsia-950/80 flex items-center justify-center border border-fuchsia-700/50">
                  <Lock className="w-8 h-8 text-fuchsia-300" />
                </div>
                <h3 className="text-xl font-bold bg-gradient-to-r from-fuchsia-300 to-cyan-300 bg-clip-text text-transparent mb-2">
                  霓虹赌场尚未解锁
                </h3>
                <div className="text-sm text-fuchsia-300/80 mb-1">
                  骰宝玩法需要 200 经验解锁
                </div>
                <div className="text-xs text-fuchsia-500/70 mb-6">
                  当前经验：{playerState.experience} / 200
                </div>
                <div className="h-2 bg-fuchsia-950/60 rounded-full overflow-hidden mb-6">
                  <motion.div
                    className="h-full bg-gradient-to-r from-fuchsia-500 to-cyan-400 rounded-full"
                    initial={{ width: 0 }}
                    animate={{
                      width: `${Math.min(100, Math.round((playerState.experience / 200) * 100))}%`,
                    }}
                    transition={{ duration: 0.8, ease: 'easeOut' }}
                  />
                </div>
                <p className="text-xs text-fuchsia-400/70 mb-6">
                  去街边赌场玩幸运轮盘积累经验，解锁更多精彩玩法！
                </p>
                <button
                  type="button"
                  onClick={() => navigate(backPath)}
                  className="w-full py-3 rounded-xl bg-gradient-to-r from-fuchsia-500 to-cyan-400 text-white text-sm font-bold hover:opacity-90 transition-opacity"
                  style={{ boxShadow: '0 0 15px rgba(217, 70, 239, 0.4)' }}
                >
                  返回首页
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {unlockedCasino && (
          <motion.div
            key="unlock-modal"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4"
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 200, damping: 25 }}
              className="w-full max-w-sm rounded-2xl p-6 text-center relative overflow-hidden"
              style={{
                background:
                  'linear-gradient(135deg, hsl(260 50% 15%) 0%, hsl(240 60% 10%) 100%)',
                border: '1px solid hsla(280, 70%, 50%, 0.5)',
                boxShadow:
                  '0 0 40px rgba(217, 70, 239, 0.4), 0 0 60px rgba(34, 211, 238, 0.2)',
              }}
            >
              <div
                className="absolute inset-0 opacity-30"
                style={{
                  background:
                    'radial-gradient(circle at 50% 0%, rgba(217, 70, 239, 0.4) 0%, transparent 60%)',
                }}
              />
              <div className="relative">
                <motion.div
                  initial={{ scale: 0, rotate: -180 }}
                  animate={{ scale: 1, rotate: 0 }}
                  transition={{ delay: 0.1, type: 'spring', stiffness: 200, damping: 20 }}
                  className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-fuchsia-500 to-cyan-400 flex items-center justify-center shadow-lg"
                >
                  <Trophy className="w-8 h-8 text-white" />
                </motion.div>
                <h3 className="text-xl font-bold bg-gradient-to-r from-fuchsia-300 to-cyan-300 bg-clip-text text-transparent mb-1">
                  新赌场解锁！
                </h3>
                <div className="text-lg font-bold text-fuchsia-100 mb-1">
                  {unlockedCasino.name}
                </div>
                <div className="text-xs text-fuchsia-400/70 mb-1">
                  {unlockedCasino.subtitle}
                </div>
                <p className="text-xs text-fuchsia-300/60 mb-6">
                  {unlockedCasino.description}
                </p>
                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={closeUnlockModal}
                    className="flex-1 py-2.5 rounded-xl border border-fuchsia-700/50 text-fuchsia-200/80 text-sm font-medium hover:bg-fuchsia-900/30 transition-colors"
                  >
                    继续游戏
                  </button>
                  <button
                    type="button"
                    onClick={goToCasino}
                    className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-fuchsia-500 to-cyan-400 text-white text-sm font-bold hover:opacity-90 transition-opacity"
                    style={{ boxShadow: '0 0 15px rgba(217, 70, 239, 0.4)' }}
                  >
                    立即前往
                  </button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default SicBoArena;
