import { motion } from 'framer-motion';
import { Medal, Crown, TrendingUp, TrendingDown, Minus } from 'lucide-react';
import type { LeaderboardEntry, LeaderboardType } from '@shared/api.interface';

interface PodiumEntryProps {
  entry: LeaderboardEntry;
  rank: number;
  podiumIdx: number;
  isMe: boolean;
  activeTab: LeaderboardType;
  formatValue: (value: number, type: LeaderboardType) => string;
}

interface PodiumCardProps {
  entries: LeaderboardEntry[];
  activeTab: LeaderboardType;
  isMyEntry: (entry: LeaderboardEntry) => boolean;
  formatValue: (value: number, type: LeaderboardType) => string;
}

const podiumColors = [
  {
    bg: 'from-amber-400 via-yellow-300 to-amber-500',
    border: 'border-amber-300/70',
    shadow: 'shadow-amber-400/40',
    ring: 'ring-amber-300/30',
    text: 'text-amber-950',
  },
  {
    bg: 'from-slate-200 via-gray-300 to-slate-400',
    border: 'border-slate-300/70',
    shadow: 'shadow-slate-400/40',
    ring: 'ring-slate-300/30',
    text: 'text-slate-800',
  },
  {
    bg: 'from-amber-700 via-orange-600 to-amber-800',
    border: 'border-orange-400/60',
    shadow: 'shadow-orange-500/40',
    ring: 'ring-orange-400/30',
    text: 'text-amber-50',
  },
];

const itemVariants = {
  hidden: { opacity: 0, y: 12 },
  show: { opacity: 1, y: 0, transition: { duration: 0.35 } },
};

const PodiumEntry = ({
  entry,
  rank,
  podiumIdx,
  isMe,
  activeTab,
  formatValue,
}: PodiumEntryProps) => {
  const colors = podiumColors[podiumIdx];
  return (
    <div
      className={`flex flex-col items-center justify-end ${
        podiumIdx === 0 ? 'order-2 -mt-4' : podiumIdx === 1 ? 'order-1' : 'order-3'
      }`}
    >
      <div
        className={`w-full relative rounded-xl p-3 border ${colors.border} bg-gradient-to-br ${colors.bg} shadow-xl ${colors.shadow} ring-2 ${colors.ring} ${
          isMe ? 'ring-2 ring-emerald-400/60' : ''
        }`}
      >
        <div className="flex flex-col items-center text-center">
          <div className="mb-1">
            {podiumIdx === 0 ? (
              <Crown
                className={`w-6 h-6 ${colors.text}`}
                strokeWidth={1.5}
              />
            ) : (
              <Medal
                className={`w-5 h-5 ${colors.text}`}
                strokeWidth={1.5}
              />
            )}
          </div>
          <div className={`text-xs font-bold ${colors.text} opacity-70 mb-1`}>
            第 {rank} 名
          </div>
          <div
            className={`text-sm font-bold ${colors.text} truncate w-full mb-0.5`}
            title={entry.username}
          >
            {entry.username}
          </div>
          {activeTab === 'level' && entry.levelName && (
            <div className={`text-xs ${colors.text} opacity-80 mb-1`}>
              {entry.levelName}
            </div>
          )}
          <div className={`text-base font-extrabold ${colors.text}`}>
            {activeTab === 'cashflow' ? (
              <span
                className={
                  entry.value < 0
                    ? 'text-red-700'
                    : entry.value > 0
                      ? ''
                      : ''
                }
              >
                {formatValue(entry.value, activeTab)}
              </span>
            ) : (
              <>{formatValue(entry.value, activeTab)} EXP</>
            )}
          </div>
        </div>
        {isMe && (
          <div className="absolute -top-2 -right-2 bg-emerald-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full shadow-md">
            我
          </div>
        )}
      </div>
    </div>
  );
};

export const PodiumCard = ({
  entries,
  activeTab,
  isMyEntry,
  formatValue,
}: PodiumCardProps) => {
  const topThree = entries.slice(0, 3);
  return (
    <motion.div
      variants={itemVariants}
      className="grid grid-cols-3 gap-3 mb-6"
    >
      {[1, 0, 2].map((podiumIdx: number) => {
        const entry = topThree[podiumIdx];
        const rank = podiumIdx + 1;
        if (!entry) {
          return (
            <div
              key={podiumIdx}
              className="flex flex-col items-center justify-end h-32"
            >
              <div className="w-full h-24 bg-card/40 rounded-xl border border-border/40" />
            </div>
          );
        }
        return (
          <PodiumEntry
            key={entry.username}
            entry={entry}
            rank={rank}
            podiumIdx={podiumIdx}
            isMe={isMyEntry(entry)}
            activeTab={activeTab}
            formatValue={formatValue}
          />
        );
      })}
    </motion.div>
  );
};

interface MyRankFooterProps {
  myRank: number;
  myValue: number;
  username: string;
  activeTab: LeaderboardType;
  formatValue: (value: number, type: LeaderboardType) => string;
}

export const MyRankFooter = ({
  myRank,
  myValue,
  username,
  activeTab,
  formatValue,
}: MyRankFooterProps) => {
  return (
    <motion.div
      variants={itemVariants}
      className="mt-4 pt-4 border-t border-border/60"
    >
      <div className="text-xs text-muted-foreground mb-2 text-center">
        我的排名
      </div>
      <div className="flex items-center gap-3 p-3 rounded-lg border bg-gradient-to-r from-emerald-500/10 to-primary/10 border-emerald-500/40 ring-1 ring-emerald-400/30 backdrop-blur-sm">
        <div className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0 bg-emerald-500/20 text-emerald-300">
          {myRank}
        </div>
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <span className="text-sm font-medium truncate text-emerald-300">
            {username}
          </span>
          <span className="text-[10px] bg-emerald-500/20 text-emerald-300 px-1.5 py-0.5 rounded-full font-semibold flex-shrink-0">
            我
          </span>
        </div>
        <div className="text-sm font-bold">
          {activeTab === 'cashflow' ? (
            <span
              className={
                myValue < 0
                  ? 'text-red-400'
                  : myValue > 0
                    ? 'text-emerald-400'
                    : 'text-muted-foreground'
              }
            >
              {myValue > 0 && (
                <TrendingUp
                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                  strokeWidth={2}
                />
              )}
              {myValue < 0 && (
                <TrendingDown
                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                  strokeWidth={2}
                />
              )}
              {myValue === 0 && (
                <Minus
                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                  strokeWidth={2}
                />
              )}
              {formatValue(myValue, activeTab)}
            </span>
          ) : (
            <span className="text-foreground">
              {formatValue(myValue, activeTab)}{' '}
              <span className="text-xs text-muted-foreground font-normal">
                EXP
              </span>
            </span>
          )}
        </div>
      </div>
    </motion.div>
  );
};
