import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import { WHEEL_SIZE } from './WheelSvg';

const LIGHT_COUNT = 12;

const WheelLights: React.FC = () => {
  const lights = useMemo(() => {
    const arr: { angle: number; delay: number }[] = [];
    for (let i = 0; i < LIGHT_COUNT; i++) {
      const angle = (i / LIGHT_COUNT) * 360;
      arr.push({ angle, delay: i * 0.15 });
    }
    return arr;
  }, []);

  const radius = WHEEL_SIZE / 2 + 18;
  const center = WHEEL_SIZE / 2;

  return (
    <div className="absolute inset-0 pointer-events-none" style={{ width: WHEEL_SIZE, height: WHEEL_SIZE }}>
      {lights.map((l, i) => {
        const rad = ((l.angle - 90) * Math.PI) / 180;
        const x = center + radius * Math.cos(rad);
        const y = center + radius * Math.sin(rad);
        return (
          <motion.div
            key={i}
            className="absolute rounded-full"
            style={{
              left: x - 4,
              top: y - 4,
              width: 8,
              height: 8,
              backgroundColor: i % 2 === 0 ? '#FFD700' : '#FF8C00',
              boxShadow: `0 0 8px ${i % 2 === 0 ? '#FFD700' : '#FF8C00'}`,
            }}
            animate={{ opacity: [0.4, 1, 0.4], scale: [0.8, 1.2, 0.8] }}
            transition={{ duration: 1.5, repeat: Infinity, delay: l.delay, ease: 'easeInOut' }}
          />
        );
      })}
    </div>
  );
};

export default WheelLights;
