import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { gameAuthApi } from '@client/src/api';
import type {
  PlayerState,
  GameAccountAuthResponse,
  CheckInResponse,
} from '@shared/api.interface';

interface GameAuthContextValue {
  username: string | null;
  token: string | null;
  playerState: PlayerState | null;
  loading: boolean;
  error: string | null;
  checkInLoading: boolean;
  redeemLoading: boolean;
  login: (username: string, password: string) => Promise<void>;
  register: (username: string, password: string) => Promise<void>;
  logout: () => void;
  refreshPlayerState: () => Promise<PlayerState>;
  handleCheckIn: () => Promise<void>;
  handleRedeemCode: (code: string) => Promise<{ success: boolean; message: string; zdAutoSpin: boolean }>;
  setPlayerState: (state: PlayerState) => void;
}

const GameAuthContext = createContext<GameAuthContextValue | null>(null);

export function GameAuthProvider({ children }: { children: ReactNode }) {
  const [token, setToken] = useState<string | null>(() =>
    gameAuthApi.tokenStorage.get(),
  );
  const [username, setUsername] = useState<string | null>(() =>
    gameAuthApi.tokenStorage.getUsername(),
  );
  const [playerState, setPlayerState] = useState<PlayerState | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [checkInLoading, setCheckInLoading] = useState<boolean>(false);
  const [redeemLoading, setRedeemLoading] = useState<boolean>(false);

  const refreshPlayerState = useCallback(async () => {
    const state = await gameAuthApi.getMe();
    setPlayerState(state);
    return state;
  }, []);

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    gameAuthApi
      .getMe()
      .then((state: PlayerState) => {
        if (cancelled) return;
        setPlayerState(state);
        setLoading(false);
      })
      .catch((err: Error) => {
        if (cancelled) return;
        gameAuthApi.tokenStorage.clear();
        setToken(null);
        setUsername(null);
        setPlayerState(null);
        setError('会话已过期，请重新登录');
        setLoading(false);
        logger.error('useGameAuth refresh failed', err);
      });

    return () => {
      cancelled = true;
    };
  }, [token]);

  const login = useCallback(
    async (usernameValue: string, password: string) => {
      setLoading(true);
      setError(null);
      try {
        const result: GameAccountAuthResponse = await gameAuthApi.login(
          usernameValue,
          password,
        );
        setToken(result.token);
        setUsername(result.username);
        setPlayerState(result.player);
      } catch (err) {
        const message =
          (err as { response?: { data?: { message?: string } } }).response
            ?.data?.message ?? (err as Error).message ?? '登录失败';
        setError(message);
        throw err;
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  const register = useCallback(
    async (usernameValue: string, password: string) => {
      setLoading(true);
      setError(null);
      try {
        const result: GameAccountAuthResponse = await gameAuthApi.register(
          usernameValue,
          password,
        );
        setToken(result.token);
        setUsername(result.username);
        setPlayerState(result.player);
      } catch (err) {
        const message =
          (err as { response?: { data?: { message?: string } } }).response
            ?.data?.message ?? (err as Error).message ?? '注册失败';
        setError(message);
        throw err;
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  const logout = useCallback(() => {
    gameAuthApi.tokenStorage.clear();
    setToken(null);
    setUsername(null);
    setPlayerState(null);
    setError(null);
  }, []);

  const handleCheckIn = useCallback(async () => {
    if (!token) return;
    setCheckInLoading(true);
    try {
      const result: CheckInResponse = await gameAuthApi.checkIn();
      if (result.success && result.player) {
        setPlayerState(result.player);
        import('@client/src/utils/sound').then(({ playSound }) => {
          playSound('checkin');
        });
      }
    } catch (err) {
      logger.error('useGameAuth checkIn failed', err);
      throw err;
    } finally {
      setCheckInLoading(false);
    }
  }, [token]);

  const handleRedeemCode = useCallback(
    async (code: string) => {
      if (!token) return { success: false, message: '请先登录', zdAutoSpin: false };
      setRedeemLoading(true);
      try {
        const result = await gameAuthApi.redeemCode(code);
        if (result.player) {
          setPlayerState(result.player);
        }
        return {
          success: result.success,
          message: result.message,
          zdAutoSpin: result.zdAutoSpin,
        };
      } catch (err) {
        const message =
          (err as { response?: { data?: { message?: string } } }).response?.data
            ?.message ?? (err as Error).message ?? '兑换码提交失败';
        return { success: false, message, zdAutoSpin: false };
      } finally {
        setRedeemLoading(false);
      }
    },
    [token],
  );

  const value = useMemo<GameAuthContextValue>(
    () => ({
      username,
      token,
      playerState,
      loading,
      error,
      checkInLoading,
      redeemLoading,
      login,
      register,
      logout,
      refreshPlayerState,
      handleCheckIn,
      handleRedeemCode,
      setPlayerState,
    }),
    [
      username,
      token,
      playerState,
      loading,
      error,
      checkInLoading,
      redeemLoading,
      login,
      register,
      logout,
      refreshPlayerState,
      handleCheckIn,
      handleRedeemCode,
    ],
  );

  return (
    <GameAuthContext.Provider value={value}>
      {children}
    </GameAuthContext.Provider>
  );
}

export function useGameAuth(): GameAuthContextValue {
  const ctx = useContext(GameAuthContext);
  if (!ctx) {
    throw new Error('useGameAuth must be used within a GameAuthProvider');
  }
  return ctx;
}
