import { motion } from 'framer-motion';
import {
  Crown,
  Lock,
  Sparkles,
  Trophy,
  ArrowRight,
  Gem,
  Lamp,
  Building2,
} from 'lucide-react';
import type { CasinoInfo, CasinoTier, PlayerLevelInfo } from '@shared/api.interface';

const ROMAN_NUMERALS: Record<number, string> = {
  1: 'Ⅰ',
  2: 'Ⅱ',
  3: 'Ⅲ',
  4: 'Ⅳ',
  5: 'Ⅴ',
};

const tierIcon = (tier: CasinoTier) => {
  switch (tier) {
    case 1:
      return <Lamp className="w-5 h-5" strokeWidth={1.5} />;
    case 2:
      return <Sparkles className="w-5 h-5" strokeWidth={1.5} />;
    case 3:
      return <Trophy className="w-5 h-5" strokeWidth={1.5} />;
    case 4:
      return <Gem className="w-5 h-5" strokeWidth={1.5} />;
    case 5:
      return <Crown className="w-5 h-5" strokeWidth={1.5} />;
    default:
      return <Building2 className="w-5 h-5" strokeWidth={1.5} />;
  }
};

export const cardVariants = {
  hidden: { opacity: 0, y: 24 },
  show: { opacity: 1, y: 0, transition: { duration: 0.5 } },
};

interface CasinoCardProps {
  casino: CasinoInfo;
  unlocked: boolean;
  isCurrent: boolean;
  experience: number;
  onEnter: (path: string) => void;
}

export const CasinoCard = ({
  casino,
  unlocked,
  isCurrent,
  experience,
  onEnter,
}: CasinoCardProps) => {
  const tier = casino.tier;
  const hasGame = casino.hasGame;
  const expNeeded = casino.unlockExp - experience;

  const bgClasses: Record<number, string> = {
    1: 'bg-gradient-to-br from-amber-950/60 via-stone-900/70 to-amber-950/40',
    2: 'bg-gradient-to-br from-fuchsia-950/60 via-purple-950/50 to-pink-950/60',
    3: 'bg-gradient-to-br from-amber-900/60 via-yellow-900/40 to-amber-950/60',
    4: 'bg-gradient-to-br from-slate-800/60 via-cyan-950/40 to-slate-900/60',
    5: 'bg-gradient-to-br from-red-950/70 via-amber-900/50 to-red-950/70',
  };

  const borderClasses: Record<number, string> = {
    1: 'border-amber-800/40',
    2: 'border-fuchsia-500/50',
    3: 'border-amber-500/60',
    4: 'border-cyan-400/40',
    5: 'border-yellow-500/70',
  };

  const glowClasses: Record<number, string> = {
    1: '',
    2: 'shadow-[0_0_20px_rgba(217_70_239_0.15)]',
    3: 'shadow-[0_0_25px_rgba(245_158_11_0.2)]',
    4: 'shadow-[0_0_30px_rgba(34_211_238_0.15)]',
    5: 'shadow-[0_0_35px_rgba(234_179_8_0.25)]',
  };

  const titleClasses: Record<number, string> = {
    1: 'bg-gradient-to-r from-amber-200 to-amber-400 bg-clip-text text-transparent',
    2: 'bg-gradient-to-r from-fuchsia-300 via-pink-300 to-purple-300 bg-clip-text text-transparent',
    3: 'bg-gradient-to-r from-amber-200 via-yellow-200 to-amber-300 bg-clip-text text-transparent',
    4: 'bg-gradient-to-r from-cyan-200 via-white to-cyan-100 bg-clip-text text-transparent',
    5: 'bg-gradient-to-r from-yellow-200 via-amber-100 to-yellow-300 bg-clip-text text-transparent',
  };

  const badgeClasses: Record<number, string> = {
    1: 'bg-amber-900/60 text-amber-300 border-amber-700/50',
    2: 'bg-fuchsia-900/50 text-fuchsia-200 border-fuchsia-500/40',
    3: 'bg-amber-800/60 text-amber-100 border-amber-500/40',
    4: 'bg-cyan-900/50 text-cyan-100 border-cyan-400/40',
    5: 'bg-yellow-900/60 text-yellow-100 border-yellow-500/40',
  };

  const glowColor: Record<number, string> = {
    2: 'bg-fuchsia-500',
    3: 'bg-amber-400',
    4: 'bg-cyan-300',
    5: 'bg-yellow-400',
  };

  return (
    <motion.div
      variants={cardVariants}
      whileHover={unlocked && hasGame ? { y: -4, scale: 1.01 } : {}}
      whileTap={unlocked && hasGame ? { scale: 0.99 } : {}}
      onClick={() => unlocked && hasGame && onEnter(casino.path)}
      className={`relative rounded-xl border p-5 md:p-6 transition-all duration-300 overflow-hidden ${bgClasses[tier]} ${borderClasses[tier]} ${unlocked ? glowClasses[tier] : ''} ${unlocked && hasGame ? 'cursor-pointer hover:shadow-2xl' : ''}`}
    >
      {/* 顶部装饰光晕 */}
      {unlocked && tier >= 2 && (
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-1/2 h-20 pointer-events-none opacity-40 blur-2xl">
          <div className={`w-full h-full rounded-full ${glowColor[tier]}`} />
        </div>
      )}

      {/* 锁定蒙层 */}
      {!unlocked && (
        <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px] z-10 flex flex-col items-center justify-center pointer-events-none">
          <Lock
            className="w-10 h-10 text-muted-foreground/70 mb-2"
            strokeWidth={1.5}
          />
          <p className="text-sm text-muted-foreground/80 font-medium">
            需要 {casino.unlockExp.toLocaleString()} 经验解锁
          </p>
          <p className="text-xs text-muted-foreground/60 mt-1">
            还差 {expNeeded.toLocaleString()} EXP
          </p>
        </div>
      )}

      <div className="relative z-0 flex items-start gap-4">
        {/* 等级徽章 */}
        <div
          className={`flex-shrink-0 w-14 h-14 md:w-16 md:h-16 rounded-xl border flex flex-col items-center justify-center ${badgeClasses[tier]}`}
        >
          <span className="text-xl md:text-2xl font-bold tracking-wider">
            {ROMAN_NUMERALS[tier]}
          </span>
          <span className="text-[10px] mt-0.5 opacity-80">TIER</span>
        </div>

        {/* 内容区 */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <h3
              className={`text-xl md:text-2xl font-bold truncate ${titleClasses[tier]}`}
            >
              {casino.name}
            </h3>
            {isCurrent && (
              <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-primary/20 text-primary text-[10px] font-semibold border border-primary/40">
                当前
              </span>
            )}
          </div>
          <p className="text-sm text-muted-foreground mb-2">
            {casino.subtitle}
          </p>
          <p className="text-xs text-muted-foreground/70 leading-relaxed mb-3 line-clamp-2">
            {casino.description}
          </p>

          {/* 底部 */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1.5 text-muted-foreground/60">
              {tierIcon(tier)}
              <span className="text-xs">
                第 {tier} 级 ·{' '}
                {casino.unlockExp === 0
                  ? '初始'
                  : `${casino.unlockExp.toLocaleString()} EXP`}
              </span>
            </div>

            {unlocked &&
              (hasGame ? (
                <span className="flex items-center gap-1 text-sm text-primary font-semibold">
                  进入{' '}
                  <ArrowRight className="w-4 h-4" strokeWidth={2} />
                </span>
              ) : (
                <span className="px-2 py-0.5 rounded-full bg-muted/60 text-muted-foreground text-xs border border-border/60">
                  敬请期待
                </span>
              ))}
          </div>
        </div>
      </div>
    </motion.div>
  );
};
