import { useEffect, useRef } from 'react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { gameAuthApi } from '@client/src/api';
import type { GameSaveSyncRequest, PlayerState } from '@shared/api.interface';

const DEBOUNCE_MS = 1500;

function buildSaveData(playerState: PlayerState): GameSaveSyncRequest {
  return {
    chipBalance: playerState.chipBalance,
    experience: playerState.experience,
    unlockedWheelLevel: playerState.unlockedWheelLevel,
    lastCheckinDate: playerState.lastCheckinDate,
    loanPrincipal: playerState.loanPrincipal,
    loanInterestRate: playerState.loanInterestRate,
    loanGamesRemaining: playerState.loanGamesRemaining,
    loanTimesToday: playerState.loanTimesToday,
    lastLoanDate: playerState.lastLoanDate,
  };
}

export function useAutoSave(playerState: PlayerState | null): void {
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastSavedRef = useRef<string>('');
  const playerStateRef = useRef<PlayerState | null>(playerState);

  // Keep ref up-to-date for exit-save
  useEffect(() => {
    playerStateRef.current = playerState;
  }, [playerState]);

  // ─── Debounced save on data change ───────────────────────────────────────
  useEffect(() => {
    if (!playerState) return;
    if (!gameAuthApi.tokenStorage.get()) return;

    const snapshot = JSON.stringify(buildSaveData(playerState));
    if (snapshot === lastSavedRef.current) return;

    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    debounceTimerRef.current = setTimeout(() => {
      const data = buildSaveData(playerState);
      void gameAuthApi
        .syncSave(data)
        .then(() => {
          lastSavedRef.current = JSON.stringify(data);
        })
        .catch((err) => {
          logger.error('自动保存失败', err);
        });
    }, DEBOUNCE_MS);

    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
        debounceTimerRef.current = null;
      }
    };
  }, [playerState]);

  // ─── Save on page hide / unload ──────────────────────────────────────────
  useEffect(() => {
    const performExitSave = (): void => {
      const state = playerStateRef.current;
      const token = gameAuthApi.tokenStorage.get();
      if (!state || !token) return;

      const data = buildSaveData(state);
      const snapshot = JSON.stringify(data);
      if (snapshot === lastSavedRef.current) return;

      try {
        gameAuthApi.syncSave(data).catch((err: unknown) => {
          logger.error('退出时保存失败', err);
        });
        lastSavedRef.current = snapshot;
      } catch (err) {
        logger.error('退出时保存失败', err);
      }
    };

    const handleVisibilityChange = (): void => {
      if (document.visibilityState === 'hidden') {
        performExitSave();
      }
    };

    const handleBeforeUnload = (): void => {
      performExitSave();
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('beforeunload', handleBeforeUnload);
      // Flush pending debounced save on unmount
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
        debounceTimerRef.current = null;
      }
    };
  }, []);
}
