import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Coins, RotateCcw, XCircle, Sparkles } from 'lucide-react';
import type { SpinResult } from '@shared/api.interface';

const LEVEL_NAMES = ['一级轮盘', '二级轮盘', '三级轮盘'];

interface ResultModalProps {
  result: SpinResult | null;
  show: boolean;
  onClose: () => void;
  formatChips: (n: number) => string;
}

const ResultModal: React.FC<ResultModalProps> = ({ result, show, onClose, formatChips }) => {
  if (!result) return null;

  return (
    <AnimatePresence>
      {show && (
        <motion.div
          className="fixed inset-0 bg-black/75 flex items-center justify-center z-50 px-6"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
        >
          <motion.div
            className="bg-[hsl(25_35%_14%)] border-2 border-amber-500 rounded-2xl p-6 w-full max-w-sm text-center relative"
            style={{ boxShadow: '0 0 40px hsl(40 100% 50% / 0.3)' }}
            initial={{ scale: 0.7, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.8, opacity: 0 }}
            transition={{ type: 'spring', stiffness: 300, damping: 20 }}
            onClick={(e) => e.stopPropagation()}
          >
            {result.type === 'chip' && (
              <>
                <div className="w-16 h-16 mx-auto mb-3 rounded-full bg-amber-500/20 flex items-center justify-center border border-amber-500/30">
                  <Coins className="w-8 h-8 text-amber-400" />
                </div>
                <h2 className="text-xl font-bold text-amber-100 mb-1">恭喜中奖！</h2>
                <motion.div
                  className="text-4xl font-black text-amber-400 my-3"
                  style={{ textShadow: '0 0 20px hsl(40 100% 50% / 0.5)' }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: 0.2, type: 'spring', stiffness: 300, damping: 15 }}
                >
                  +{formatChips(result.chipAmount ?? 0)}
                </motion.div>
                <p className="text-sm text-amber-300/70 mb-4">筹码已到账</p>
                <div className="flex items-center justify-center gap-2 text-sm text-amber-200">
                  <Sparkles className="w-4 h-4 text-amber-400" />
                  <span>获得 {result.expGained ?? 0} 经验值</span>
                </div>
                {result.newLevelUnlocked !== undefined && (
                  <motion.div
                    className="mt-4 p-3 bg-amber-500/10 rounded-lg border border-amber-500/30"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.4 }}
                  >
                    <p className="text-amber-400 font-bold text-sm">
                      🔓 解锁{LEVEL_NAMES[result.newLevelUnlocked - 1]}！
                    </p>
                  </motion.div>
                )}
              </>
            )}

            {result.type === 'retry' && (
              <>
                <div className="w-16 h-16 mx-auto mb-3 rounded-full bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30">
                  <RotateCcw className="w-8 h-8 text-emerald-400" />
                </div>
                <h2 className="text-2xl font-bold text-emerald-400 mb-2">再来一次！</h2>
                <p className="text-sm text-amber-300/70">幸运加持，马上再转一次</p>
              </>
            )}

            {result.type === 'thanks' && (
              <>
                <div className="w-16 h-16 mx-auto mb-3 rounded-full bg-red-500/20 flex items-center justify-center border border-red-500/30">
                  <XCircle className="w-8 h-8 text-red-400" />
                </div>
                <h2 className="text-2xl font-bold text-amber-100 mb-2">感谢参与</h2>
                <p className="text-sm text-amber-300/70 mb-2">下次一定能中大奖！</p>
              </>
            )}

            {result.type !== 'retry' && (
              <button
                type="button"
                onClick={onClose}
                className="mt-6 w-full py-3 bg-gradient-to-r from-amber-500 to-amber-600 text-amber-950 font-bold rounded-xl hover:from-amber-400 hover:to-amber-50 transition-all shadow-md shadow-amber-90/50"
              >
                确定
              </button>
            )}
            {result.type === 'retry' && (
              <p className="mt-6 text-xs text-amber-400/50">
                点击任意位置继续
              </p>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default ResultModal;
