import { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Trophy,
  Medal,
  Coins,
  RefreshCw,
  TrendingUp,
  TrendingDown,
  Minus,
  User,
  Sparkles,
  ArrowLeft,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { getLeaderboard } from '@client/src/api/casino';
import { PodiumCard, MyRankFooter } from './LeaderboardComponents';
import type {
  LeaderboardEntry,
  LeaderboardResponse,
  LeaderboardType,
} from '@shared/api.interface';

const containerVariants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.06 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 12 },
  show: { opacity: 1, y: 0, transition: { duration: 0.35 } },
};

const LeaderboardPage = () => {
  const navigate = useNavigate();
  const { username } = useGameAuth();
  const [activeTab, setActiveTab] = useState<LeaderboardType>('level');
  const [data, setData] = useState<LeaderboardResponse | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const [manualRefreshing, setManualRefreshing] = useState<boolean>(false);

  const fetchData = useCallback(
    async (isManual: boolean = false) => {
      if (isManual) {
        setManualRefreshing(true);
      } else {
        setLoading(true);
      }
      setError(null);
      try {
        const result: LeaderboardResponse = await getLeaderboard(activeTab, 50);
        setData(result);
        setLastRefresh(new Date());
      } catch (err) {
        const message =
          (err as { response?: { data?: { message?: string } } }).response
            ?.data?.message ??
          (err as Error).message ??
          '获取排行榜失败';
        setError(message);
        logger.error('获取排行榜失败', err);
      } finally {
        setLoading(false);
        setManualRefreshing(false);
      }
    },
    [activeTab],
  );

  useEffect(() => {
    void fetchData();
  }, [fetchData]);

  useEffect(() => {
    const intervalId = setInterval(() => {
      void fetchData();
    }, 15000);
    return () => clearInterval(intervalId);
  }, [fetchData]);

  const handleTabChange = (tab: LeaderboardType) => {
    if (tab === activeTab) return;
    setActiveTab(tab);
  };

  const handleManualRefresh = () => {
    if (manualRefreshing || loading) return;
    void fetchData(true);
  };

  const isMyEntry = useCallback(
    (entry: LeaderboardEntry): boolean => {
      return entry.username === username;
    },
    [username],
  );

  const myRankInList = data?.items.some(
    (item: LeaderboardEntry) => item.username === username,
  );

  const formatValue = (value: number, type: LeaderboardType): string => {
    if (type === 'cashflow') {
      const prefix = value > 0 ? '+' : value < 0 ? '−' : '';
      return `${prefix}${Math.abs(value).toLocaleString()}`;
    }
    return value.toLocaleString();
  };

  const formatTime = (date: Date | null): string => {
    if (!date) return '';
    return date.toLocaleTimeString('zh-CN', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  const restItems: LeaderboardEntry[] = data?.items.slice(3) ?? [];

  return (
    <div className="min-h-screen w-full bg-background text-foreground relative overflow-hidden">
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/60" />
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-primary/10 rounded-full blur-[120px]" />
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-[800px] h-[300px] bg-amber-800/10 rounded-full blur-[140px]" />
      </div>

      <div className="relative z-10 max-w-3xl mx-auto px-4 md:px-6 py-8 md:py-10">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="flex items-center justify-between mb-6"
        >
          <button
            type="button"
            onClick={() => navigate('/')}
            className="flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-primary/10 transition-colors text-muted-foreground hover:text-foreground"
            aria-label="返回大厅"
          >
            <ArrowLeft className="w-5 h-5" />
            <span className="text-sm font-medium">返回大厅</span>
          </button>
          <div className="flex items-center gap-1.5 bg-card/60 px-3 py-1.5 rounded-full border border-border/60 backdrop-blur-sm">
            <User className="w-4 h-4 text-primary/60" />
            <span className="text-sm font-semibold text-foreground/80">
              {username || '访客'}
            </span>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.05 }}
          className="text-center mb-8"
        >
          <div className="flex items-center justify-center gap-3 mb-2">
            <Trophy
              className="w-5 h-5 md:w-6 md:h-6 text-primary/60"
              strokeWidth={1.5}
            />
            <h1 className="text-3xl md:text-4xl font-bold tracking-widest bg-gradient-to-r from-amber-300 via-primary to-amber-300 bg-clip-text text-transparent">
              实时排行榜
            </h1>
            <Trophy
              className="w-5 h-5 md:w-6 md:h-6 text-primary/60"
              strokeWidth={1.5}
            />
          </div>
          <div className="flex items-center justify-center gap-3 mt-3">
            <div className="h-px w-12 md:w-20 bg-gradient-to-r from-transparent to-primary/40" />
            <Sparkles
              className="w-4 h-4 text-primary/50"
              strokeWidth={1.5}
            />
            <p className="text-xs md:text-sm text-muted-foreground tracking-wider">
              全服玩家排名
            </p>
            <Sparkles
              className="w-4 h-4 text-primary/50"
              strokeWidth={1.5}
            />
            <div className="h-px w-12 md:w-20 bg-gradient-to-l from-transparent to-primary/40" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1 }}
          className="mb-6"
        >
          <div className="flex items-center gap-2 p-1 bg-card/60 border border-border/60 rounded-xl backdrop-blur-sm">
            <button
              onClick={() => handleTabChange('level')}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg text-sm font-semibold transition-all ${
                activeTab === 'level'
                  ? 'bg-gradient-to-r from-primary to-amber-400 text-primary-foreground shadow-lg shadow-primary/30'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
              data-ai-section-type="button"
            >
              <Medal className="w-4 h-4" strokeWidth={1.5} />
              等级称号榜
            </button>
            <button
              onClick={() => handleTabChange('cashflow')}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded-lg text-sm font-semibold transition-all ${
                activeTab === 'cashflow'
                  ? 'bg-gradient-to-r from-primary to-amber-400 text-primary-foreground shadow-lg shadow-primary/30'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
              data-ai-section-type="button"
            >
              <Coins className="w-4 h-4" strokeWidth={1.5} />
              筹码现金流榜
            </button>
          </div>

          {activeTab === 'cashflow' && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
              className="mt-3 p-3 bg-amber-900/10 border border-amber-600/20 rounded-lg"
            >
              <p className="text-xs text-amber-200/80 leading-relaxed">
                <span className="font-semibold text-amber-300">说明：</span>
                净现金流 = 当前筹码 − 未还贷款本息。负债玩家排名靠后，负数以红色显示。
              </p>
            </motion.div>
          )}
        </motion.div>

        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.4, delay: 0.15 }}
          className="flex items-center justify-between mb-4"
        >
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            <span>
              {lastRefresh
                ? `上次刷新 ${formatTime(lastRefresh)}`
                : '实时更新中'}
            </span>
          </div>
          <button
            onClick={handleManualRefresh}
            disabled={manualRefreshing || loading}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-primary/80 hover:text-primary bg-primary/10 hover:bg-primary/20 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            data-ai-section-type="button"
          >
            <RefreshCw
              className={`w-3.5 h-3.5 ${
                manualRefreshing || loading ? 'animate-spin' : ''
              }`}
              strokeWidth={1.5}
            />
            {manualRefreshing ? '刷新中...' : '手动刷新'}
          </button>
        </motion.div>

        <AnimatePresence mode="wait">
          {loading && !data ? (
            <motion.div
              key="loading"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="space-y-3"
            >
              <div className="flex gap-3 mb-6">
                {[1, 0, 2].map((idx: number) => (
                  <div
                    key={idx}
                    className="flex-1 h-32 bg-card/40 rounded-xl animate-pulse border border-border/40"
                  />
                ))}
              </div>
              {Array.from({ length: 7 }).map((_, i: number) => (
                <div
                  key={i}
                  className="h-14 bg-card/40 rounded-lg animate-pulse border border-border/40"
                  style={{ animationDelay: `${i * 0.05}s` }}
                />
              ))}
            </motion.div>
          ) : error ? (
            <motion.div
              key="error"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className="text-center py-16 text-muted-foreground"
            >
              <p className="text-sm">{error}</p>
              <button
                onClick={handleManualRefresh}
                className="mt-4 text-primary text-sm hover:underline"
                data-ai-section-type="button"
              >
                点击重试
              </button>
            </motion.div>
          ) : !data || data.items.length === 0 ? (
            <motion.div
              key="empty"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className="text-center py-16 text-muted-foreground"
            >
              <Trophy
                className="w-12 h-12 mx-auto mb-3 opacity-30"
                strokeWidth={1.5}
              />
              <p className="text-sm">暂无数据</p>
            </motion.div>
          ) : (
            <motion.div
              key="content"
              initial="hidden"
              animate="show"
              variants={containerVariants}
            >
              <PodiumCard
                entries={data.items}
                activeTab={activeTab}
                isMyEntry={isMyEntry}
                formatValue={formatValue}
              />

              <motion.div variants={itemVariants} className="space-y-2">
                {restItems.map((entry: LeaderboardEntry) => {
                  const isMe = isMyEntry(entry);
                  return (
                    <motion.div
                      key={entry.username}
                      variants={itemVariants}
                      whileHover={{ scale: 1.01, x: 2 }}
                      transition={{ duration: 0.15 }}
                      className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${
                        isMe
                          ? 'bg-emerald-500/10 border-emerald-500/40 ring-1 ring-emerald-400/30'
                          : 'bg-card/60 border-border/60 hover:border-primary/40 hover:bg-card/80 backdrop-blur-sm'
                      }`}
                    >
                      <div
                        className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0 ${
                          isMe
                            ? 'bg-emerald-500/20 text-emerald-300'
                            : 'bg-muted text-muted-foreground'
                        }`}
                      >
                        {entry.rank}
                      </div>

                      <div className="flex items-center gap-2 flex-1 min-w-0">
                        <User
                          className="w-4 h-4 text-muted-foreground/60 flex-shrink-0"
                          strokeWidth={1.5}
                        />
                        <span
                          className={`text-sm font-medium truncate ${
                            isMe ? 'text-emerald-300' : 'text-foreground'
                          }`}
                        >
                          {entry.username}
                        </span>
                        {isMe && (
                          <span className="text-[10px] bg-emerald-500/20 text-emerald-300 px-1.5 py-0.5 rounded-full font-semibold flex-shrink-0">
                            我
                          </span>
                        )}
                      </div>

                      <div className="flex flex-col items-end gap-0.5 flex-shrink-0">
                        {activeTab === 'level' && entry.levelName && (
                          <span className="text-[11px] text-primary/70 font-medium">
                            {entry.levelName}
                          </span>
                        )}
                        <div className="text-sm font-bold">
                          {activeTab === 'cashflow' ? (
                            <span
                              className={
                                entry.value < 0
                                  ? 'text-red-400'
                                  : entry.value > 0
                                    ? 'text-emerald-400'
                                    : 'text-muted-foreground'
                              }
                            >
                              {entry.value > 0 && (
                                <TrendingUp
                                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                                  strokeWidth={2}
                                />
                              )}
                              {entry.value < 0 && (
                                <TrendingDown
                                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                                  strokeWidth={2}
                                />
                              )}
                              {entry.value === 0 && (
                                <Minus
                                  className="inline w-3.5 h-3.5 mr-0.5 -mt-0.5"
                                  strokeWidth={2}
                                />
                              )}
                              {formatValue(entry.value, activeTab)}
                            </span>
                          ) : (
                            <span className="text-foreground">
                              {formatValue(entry.value, activeTab)}{' '}
                              <span className="text-xs text-muted-foreground font-normal">
                                EXP
                              </span>
                            </span>
                          )}
                        </div>
                      </div>
                    </motion.div>
                  );
                })}

                {!myRankInList && data.myRank > 0 && username && (
                  <MyRankFooter
                    myRank={data.myRank}
                    myValue={data.myValue}
                    username={username}
                    activeTab={activeTab}
                    formatValue={formatValue}
                  />
                )}
              </motion.div>

              <motion.div
                variants={itemVariants}
                className="mt-6 text-center text-xs text-muted-foreground/60"
              >
                共 {data.total.toLocaleString()} 位玩家参与排名
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default LeaderboardPage;
