import React from 'react';
import { Route, Routes } from 'react-router-dom';
import { GameAuthProvider } from './hooks/useGameAuth';

import Layout from './components/Layout';
import HomePage from './pages/HomePage/HomePage';
import TenYuanArena from './pages/TenYuanArena/TenYuanArena';
import HundredYuanPage from './pages/HundredYuanPage';
import ThousandYuanPage from './pages/ThousandYuanPage';
import TenThousandYuanPage from './pages/TenThousandYuanPage';
import MillionYuanPage from './pages/MillionYuanPage';
import SicBoArena from './pages/SicBoArena/SicBoArena';
import BlackjackArena from './pages/BlackjackArena/BlackjackArena';
import BaccaratArena from './pages/BaccaratArena/BaccaratArena';
import TexasArena from './pages/TexasArena/TexasArena';
import LeaderboardPage from './pages/LeaderboardPage/LeaderboardPage';
import LoginPage from './pages/LoginPage/LoginPage';
import NotFound from './pages/NotFound/NotFound';

const RoutesComponent = () => {
  return (
    <GameAuthProvider>
      <Routes>
      <Route path="login" element={<LoginPage />} />
      <Route element={<Layout />}>
        <Route index element={<HomePage />} />
        <Route path="ten-yuan" element={<TenYuanArena />} />
        <Route path="hundred-yuan" element={<HundredYuanPage />} />
        <Route path="hundred-yuan/sicbo" element={<SicBoArena />} />
        <Route path="thousand-yuan" element={<ThousandYuanPage />} />
        <Route path="thousand-yuan/sicbo" element={<SicBoArena />} />
        <Route path="thousand-yuan/blackjack" element={<BlackjackArena />} />
        <Route path="ten-thousand-yuan" element={<TenThousandYuanPage />} />
        <Route path="ten-thousand-yuan/sicbo" element={<SicBoArena />} />
        <Route path="ten-thousand-yuan/blackjack" element={<BlackjackArena />} />
        <Route path="ten-thousand-yuan/baccarat" element={<BaccaratArena />} />
        <Route path="million-yuan" element={<MillionYuanPage />} />
        <Route path="million-yuan/sicbo" element={<SicBoArena />} />
        <Route path="million-yuan/blackjack" element={<BlackjackArena />} />
        <Route path="million-yuan/baccarat" element={<BaccaratArena />} />
        <Route path="million-yuan/texas" element={<TexasArena />} />
        <Route path="leaderboard" element={<LeaderboardPage />} />
      </Route>
      <Route path="*" element={<NotFound />} />
      </Routes>
    </GameAuthProvider>
  );
};

export default RoutesComponent;
