import { useCallback, useEffect, useState } from 'react';
import { Volume2, VolumeX } from 'lucide-react';
import { soundManager, playSound } from '@client/src/utils/sound';

export function useSoundToggle(): [boolean, (v: boolean) => void, () => boolean] {
  const [enabled, setEnabled] = useState<boolean>(soundManager.isEnabled());

  const setSoundEnabled = useCallback((v: boolean) => {
    soundManager.setEnabled(v);
    setEnabled(v);
    if (v) {
      playSound('click');
    }
  }, []);

  const toggle = useCallback(() => {
    const next = soundManager.toggle();
    setEnabled(next);
    if (next) {
      playSound('click');
    }
    return next;
  }, []);

  useEffect(() => {
    setEnabled(soundManager.isEnabled());
  }, []);

  return [enabled, setSoundEnabled, toggle];
}

interface SoundToggleButtonProps {
  className?: string;
}

export const SoundToggleButton: React.FC<SoundToggleButtonProps> = ({ className }) => {
  const [enabled, , toggle] = useSoundToggle();
  return (
    <button
      type="button"
      onClick={() => toggle()}
      className={`p-2 rounded-lg hover:bg-primary/10 transition-colors text-muted-foreground hover:text-foreground ${className ?? ''}`}
      aria-label={enabled ? '关闭音效' : '开启音效'}
      title={enabled ? '关闭音效' : '开启音效'}
    >
      {enabled ? (
        <Volume2 className="w-5 h-5" />
      ) : (
        <VolumeX className="w-5 h-5" />
      )}
    </button>
  );
};
