// ─── 玩法定义 ────────────────────────────────────────────────────────────────

interface GameInfo {
  game: string;
  name: string;
  subtitle: string;
  path: string;
  desc: string;
  minBetByTier: Partial<Record<CasinoTier, number>>;
  icon: 'dices' | 'swords' | 'crown' | 'sparkles';
}

const GAMES: GameInfo[] = [
  {
    game: 'sicbo',
    name: '骰宝',
    subtitle: '猜大小·单双',
    path: 'sicbo',
    desc: '三颗骰子定乾坤，大小单双任你选',
    minBetByTier: { 2: 10, 3: 100, 4: 1000, 5: 10000 },
    icon: 'dices',
  },
  {
    game: 'blackjack',
    name: '21点',
    subtitle: 'Blackjack',
    path: 'blackjack',
    desc: '与庄家斗智斗勇，最接近21点者胜',
    minBetByTier: { 3: 100, 4: 1000, 5: 10000 },
    icon: 'swords',
  },
  {
    game: 'baccarat',
    name: '百家乐',
    subtitle: 'Baccarat',
    path: 'baccarat',
    desc: '押庄押闲押和，上流社会经典玩法',
    minBetByTier: { 4: 1000, 5: 10000 },
    icon: 'crown',
  },
  {
    game: 'texas',
    name: '德州扑克',
    subtitle: '五张比大小',
    path: 'texas',
    desc: '五张牌型比拼，跟注还是弃牌？',
    minBetByTier: { 5: 10000 },
    icon: 'sparkles',
  },
];

const GameIcon = ({
  icon,
  className,
}: {
  icon: GameInfo['icon'];
  className?: string;
}): React.ReactElement => {
  switch (icon) {
    case 'dices':
      return <Dices className={className} strokeWidth={1.5} />;
    case 'swords':
      return <Swords className={className} strokeWidth={1.5} />;
    case 'crown':
      return <Crown className={className} strokeWidth={1.5} />;
    case 'sparkles':
      return <Sparkles className={className} strokeWidth={1.5} />;
    default:
      return <Sparkles className={className} strokeWidth={1.5} />;
  }
};

