import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { Crown, Sparkles, User, Lock, Eye, EyeOff, Coins } from 'lucide-react';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { Button } from '@client/src/components/ui/button';
import { Input } from '@client/src/components/ui/input';
import { Label } from '@client/src/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@client/src/components/ui/tabs';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@client/src/components/ui/card';
import { Alert, AlertDescription } from '@client/src/components/ui/alert';

const LoginPage = () => {
  const navigate = useNavigate();
  const { username, login, register, loading, error, token } = useGameAuth();

  // Login form
  const [loginUsername, setLoginUsername] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [showLoginPwd, setShowLoginPwd] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);

  // Register form
  const [regUsername, setRegUsername] = useState('');
  const [regPassword, setRegPassword] = useState('');
  const [regConfirmPassword, setRegConfirmPassword] = useState('');
  const [showRegPwd, setShowRegPwd] = useState(false);
  const [regError, setRegError] = useState<string | null>(null);

  // Redirect if already logged in
  useEffect(() => {
    if (token && username) {
      navigate('/', { replace: true });
    }
  }, [token, username, navigate]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(null);
    if (!loginUsername.trim() || !loginPassword) {
      setLoginError('请输入用户名和密码');
      return;
    }
    try {
      await login(loginUsername.trim(), loginPassword);
      navigate('/', { replace: true });
    } catch {
      const msg = error || '登录失败，请检查用户名和密码';
      setLoginError(msg);
      if (msg.includes('已注销')) {
        setLoginError('此账号已注销，请重新注册');
      }
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setRegError(null);
    if (!regUsername.trim()) {
      setRegError('请输入用户名');
      return;
    }
    if (regUsername.trim().length < 3) {
      setRegError('用户名至少 3 个字符');
      return;
    }
    if (!regPassword) {
      setRegError('请输入密码');
      return;
    }
    if (regPassword.length < 6) {
      setRegError('密码至少 6 个字符');
      return;
    }
    if (regPassword !== regConfirmPassword) {
      setRegError('两次输入的密码不一致');
      return;
    }
    try {
      await register(regUsername.trim(), regPassword);
      navigate('/', { replace: true });
    } catch {
      setRegError(error || '注册失败，用户名可能已被占用');
    }
  };

  return (
    <div className="min-h-screen w-full bg-background text-foreground relative flex items-center justify-center overflow-hidden">
      {/* 赌场背景 */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-background to-black/70" />
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[400px] bg-primary/15 rounded-full blur-[140px]" />
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-[800px] h-[300px] bg-amber-700/10 rounded-full blur-[140px]" />
        <div className="absolute top-1/3 -left-20 w-[300px] h-[300px] bg-primary/5 rounded-full blur-[100px]" />
        <div className="absolute top-1/3 -right-20 w-[300px] h-[300px] bg-amber-600/10 rounded-full blur-[100px]" />
      </div>

      <div className="relative z-10 w-full max-w-md px-4">
        {/* Logo / 标题 */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8"
        >
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gradient-to-br from-primary/40 via-amber-500/30 to-amber-700/30 border-2 border-primary/50 shadow-xl shadow-primary/30 mb-4">
            <Coins className="w-10 h-10 text-primary" strokeWidth={1.5} />
          </div>
          <div className="flex items-center justify-center gap-2 mb-1">
            <Crown className="w-5 h-5 text-primary/60" strokeWidth={1.5} />
            <h1 className="text-3xl font-bold tracking-widest bg-gradient-to-r from-amber-300 via-primary to-amber-300 bg-clip-text text-transparent">
              筹码娱乐
            </h1>
            <Crown className="w-5 h-5 text-primary/60" strokeWidth={1.5} />
          </div>
          <div className="flex items-center justify-center gap-2 mt-2">
            <div className="h-px w-12 bg-gradient-to-r from-transparent to-primary/40" />
            <Sparkles className="w-3.5 h-3.5 text-primary/50" strokeWidth={1.5} />
            <p className="text-xs text-muted-foreground tracking-wider">
              欢迎来到赌场，请先登录
            </p>
            <Sparkles className="w-3.5 h-3.5 text-primary/50" strokeWidth={1.5} />
            <div className="h-px w-12 bg-gradient-to-l from-transparent to-primary/40" />
          </div>
        </motion.div>

        {/* 登录/注册卡片 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1 }}
        >
          <Card className="bg-card/80 backdrop-blur-sm border-border/60 shadow-2xl shadow-black/40">
            <CardHeader className="pb-4">
              <CardTitle className="text-center text-xl">
                <span className="bg-gradient-to-r from-amber-300 to-primary bg-clip-text text-transparent">
                  游戏账号
                </span>
              </CardTitle>
              <CardDescription className="text-center text-xs">
                登录或注册以保存你的赌场进度
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Tabs defaultValue="login" className="w-full">
                <TabsList className="grid grid-cols-2 mb-6">
                  <TabsTrigger value="login">登录</TabsTrigger>
                  <TabsTrigger value="register">注册</TabsTrigger>
                </TabsList>

                {/* 登录 Tab */}
                <TabsContent value="login">
                  <form onSubmit={handleLogin} className="space-y-4">
                    {loginError && (
                      <Alert variant="destructive" className="py-2">
                        <AlertDescription className="text-xs">
                          {loginError}
                        </AlertDescription>
                      </Alert>
                    )}
                    <div className="space-y-2">
                      <Label htmlFor="login-username">用户名</Label>
                      <div className="relative">
                        <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                          id="login-username"
                          type="text"
                          placeholder="请输入用户名"
                          value={loginUsername}
                          onChange={(e) => setLoginUsername(e.target.value)}
                          className="pl-10"
                          autoComplete="username"
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="login-password">密码</Label>
                      <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                          id="login-password"
                          type={showLoginPwd ? 'text' : 'password'}
                          placeholder="请输入密码"
                          value={loginPassword}
                          onChange={(e) => setLoginPassword(e.target.value)}
                          className="pl-10 pr-10"
                          autoComplete="current-password"
                        />
                        <button
                          type="button"
                          onClick={() => setShowLoginPwd(!showLoginPwd)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                          aria-label={showLoginPwd ? '隐藏密码' : '显示密码'}
                        >
                          {showLoginPwd ? (
                            <EyeOff className="w-4 h-4" />
                          ) : (
                            <Eye className="w-4 h-4" />
                          )}
                        </button>
                      </div>
                    </div>
                    <Button
                      type="submit"
                      className="w-full bg-gradient-to-r from-primary to-amber-400 text-primary-foreground hover:opacity-90"
                      disabled={loading}
                    >
                      {loading ? '登录中...' : '登 录'}
                    </Button>
                  </form>
                </TabsContent>

                {/* 注册 Tab */}
                <TabsContent value="register">
                  <form onSubmit={handleRegister} className="space-y-4">
                    {regError && (
                      <Alert variant="destructive" className="py-2">
                        <AlertDescription className="text-xs">
                          {regError}
                        </AlertDescription>
                      </Alert>
                    )}
                    <div className="space-y-2">
                      <Label htmlFor="reg-username">用户名</Label>
                      <div className="relative">
                        <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                          id="reg-username"
                          type="text"
                          placeholder="至少 3 个字符"
                          value={regUsername}
                          onChange={(e) => setRegUsername(e.target.value)}
                          className="pl-10"
                          autoComplete="username"
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="reg-password">密码</Label>
                      <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                          id="reg-password"
                          type={showRegPwd ? 'text' : 'password'}
                          placeholder="至少 6 个字符"
                          value={regPassword}
                          onChange={(e) => setRegPassword(e.target.value)}
                          className="pl-10 pr-10"
                          autoComplete="new-password"
                        />
                        <button
                          type="button"
                          onClick={() => setShowRegPwd(!showRegPwd)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                          aria-label={showRegPwd ? '隐藏密码' : '显示密码'}
                        >
                          {showRegPwd ? (
                            <EyeOff className="w-4 h-4" />
                          ) : (
                            <Eye className="w-4 h-4" />
                          )}
                        </button>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="reg-confirm-password">确认密码</Label>
                      <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                          id="reg-confirm-password"
                          type={showRegPwd ? 'text' : 'password'}
                          placeholder="再次输入密码"
                          value={regConfirmPassword}
                          onChange={(e) => setRegConfirmPassword(e.target.value)}
                          className="pl-10"
                          autoComplete="new-password"
                        />
                      </div>
                    </div>
                    <Button
                      type="submit"
                      className="w-full bg-gradient-to-r from-primary to-amber-400 text-primary-foreground hover:opacity-90"
                      disabled={loading}
                    >
                      {loading ? '注册中...' : '注 册'}
                    </Button>
                  </form>
                </TabsContent>
              </Tabs>
            </CardContent>
            <CardFooter className="flex justify-center text-xs text-muted-foreground pt-0">
              <div className="flex items-center gap-1.5">
                <Sparkles className="w-3 h-3 text-primary/50" strokeWidth={1.5} />
                <span>每一次转动，都是命运的邂逅</span>
                <Sparkles className="w-3 h-3 text-primary/50" strokeWidth={1.5} />
              </div>
            </CardFooter>
          </Card>
        </motion.div>

        {/* 底部装饰 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.8, duration: 1 }}
          className="mt-8 flex items-center justify-center gap-3"
        >
          <div className="h-px w-16 bg-gradient-to-r from-transparent to-primary/30" />
          <Crown className="w-4 h-4 text-primary/50" strokeWidth={1.5} />
          <div className="h-px w-16 bg-gradient-to-l from-transparent to-primary/30" />
        </motion.div>
      </div>
    </div>
  );
};

export default LoginPage;
