const STORAGE_KEY = 'lucky_chips_sound_enabled';

class SoundManager {
  private ctx: AudioContext | null = null;
  private enabled: boolean = true;
  private masterGain: GainNode | null = null;
  private rotatingOsc: OscillatorNode | null = null;
  private rotatingGain: GainNode | null = null;

  constructor() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored !== null) {
        this.enabled = stored === 'true';
      }
    } catch {
      this.enabled = true;
    }
  }

  private ensureCtx(): AudioContext | null {
    if (!this.enabled) return null;
    if (this.ctx) {
      if (this.ctx.state === 'suspended') {
        void this.ctx.resume();
      }
      return this.ctx;
    }
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return null;
      this.ctx = new AudioCtx();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.3;
      this.masterGain.connect(this.ctx.destination);
      return this.ctx;
    } catch {
      return null;
    }
  }

  isEnabled(): boolean {
    return this.enabled;
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    try {
      localStorage.setItem(STORAGE_KEY, String(enabled));
    } catch {
      // ignore
    }
    if (!enabled) {
      this.stopSpin();
    }
  }

  toggle(): boolean {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }

  private playTone(
    freq: number,
    duration: number,
    type: OscillatorType = 'sine',
    volume: number = 0.3,
    startOffset: number = 0,
    freqEnd?: number,
  ): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.masterGain) return;
    const now = ctx.currentTime + startOffset;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    if (freqEnd !== undefined) {
      osc.frequency.exponentialRampToValueAtTime(
        Math.max(freqEnd, 0.01),
        now + duration,
      );
    }
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(volume, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  }

  playClick(): void {
    this.playTone(800, 0.05, 'sine', 0.15);
  }

  playChip(): void {
    this.playTone(1200, 0.08, 'square', 0.1);
    this.playTone(1600, 0.06, 'sine', 0.08, 0.01);
  }

  playWin(): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.masterGain) return;
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((freq, i) => {
      this.playTone(freq, 0.18, 'triangle', 0.2, i * 0.08);
    });
    this.playTone(1318.5, 0.3, 'triangle', 0.15, 0.32);
  }

  playLose(): void {
    this.playTone(220, 0.3, 'sine', 0.2, 0, 110);
  }

  playTick(): void {
    this.playTone(2000, 0.02, 'square', 0.08);
  }

  playSpinStart(): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.masterGain) return;
    this.stopSpin();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(80, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(200, ctx.currentTime + 0.5);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0.08, ctx.currentTime + 0.1);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    osc.start();
    this.rotatingOsc = osc;
    this.rotatingGain = gain;
  }

  playSpinSlowdown(): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.rotatingOsc || !this.rotatingGain) return;
    const now = ctx.currentTime;
    this.rotatingOsc.frequency.cancelScheduledValues(now);
    this.rotatingOsc.frequency.setValueAtTime(
      this.rotatingOsc.frequency.value,
      now,
    );
    this.rotatingOsc.frequency.linearRampToValueAtTime(60, now + 2);
    this.rotatingGain.gain.setValueAtTime(this.rotatingGain.gain.value, now);
    this.rotatingGain.gain.linearRampToValueAtTime(0.001, now + 2);
  }

  stopSpin(): void {
    if (this.rotatingOsc) {
      try {
        this.rotatingOsc.stop();
      } catch {
        // ignore
      }
      this.rotatingOsc = null;
      this.rotatingGain = null;
    }
  }

  playDiceRoll(durationMs: number = 800): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.masterGain) return;
    const steps = Math.floor(durationMs / 60);
    for (let i = 0; i < steps; i++) {
      const t = i / steps;
      const freq = 800 + Math.random() * 600;
      this.playTone(freq, 0.03, 'square', 0.06 * (1 - t * 0.5), i * 0.06);
    }
    this.playTone(400, 0.15, 'triangle', 0.2, durationMs / 1000);
  }

  playCardShuffle(): void {
    const ctx = this.ensureCtx();
    if (!ctx || !this.masterGain) return;
    const bufferSize = ctx.sampleRate * 0.25;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize);
    }
    const source = ctx.createBufferSource();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 2000;
    source.buffer = buffer;
    gain.gain.value = 0.15;
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    source.start();
  }

  playCheckin(): void {
    this.playTone(660, 0.1, 'sine', 0.2);
    this.playTone(880, 0.15, 'sine', 0.2, 0.1);
    this.playTone(1100, 0.2, 'sine', 0.2, 0.2);
  }

  playLevelUp(): void {
    const notes = [392, 523.25, 659.25, 783.99, 1046.5];
    notes.forEach((freq, i) => {
      this.playTone(freq, 0.22, 'triangle', 0.22, i * 0.12);
    });
    this.playTone(1318.5, 0.5, 'triangle', 0.2, 0.6);
    this.playTone(1568, 0.6, 'sine', 0.15, 0.7);
  }

  playLoan(): void {
    this.playTone(440, 0.1, 'sine', 0.15);
    this.playTone(550, 0.1, 'sine', 0.15, 0.1);
    this.playTone(660, 0.25, 'sine', 0.2, 0.2);
  }
}

export const soundManager = new SoundManager();

export type SoundName =
  | 'click'
  | 'chip'
  | 'win'
  | 'lose'
  | 'tick'
  | 'spinStart'
  | 'spinSlowdown'
  | 'spinStop'
  | 'diceRoll'
  | 'cardShuffle'
  | 'checkin'
  | 'levelUp'
  | 'loan';

export function playSound(name: SoundName, ...args: any[]): void {
  switch (name) {
    case 'click':
      soundManager.playClick();
      break;
    case 'chip':
      soundManager.playChip();
      break;
    case 'win':
      soundManager.playWin();
      break;
    case 'lose':
      soundManager.playLose();
      break;
    case 'tick':
      soundManager.playTick();
      break;
    case 'spinStart':
      soundManager.playSpinStart();
      break;
    case 'spinSlowdown':
      soundManager.playSpinSlowdown();
      break;
    case 'spinStop':
      soundManager.stopSpin();
      break;
    case 'diceRoll':
      soundManager.playDiceRoll(args[0] as number);
      break;
    case 'cardShuffle':
      soundManager.playCardShuffle();
      break;
    case 'checkin':
      soundManager.playCheckin();
      break;
    case 'levelUp':
      soundManager.playLevelUp();
      break;
    case 'loan':
      soundManager.playLoan();
      break;
  }
}
