// ─── 存储 key ──────────────────────────────────────────────────────
const ACCOUNTS_KEY = 'game5_accounts_v1';
const SAVES_KEY = 'game5_saves_v1';
const TOKEN_KEY = 'game_auth_token';
const USERNAME_KEY = 'game_auth_username';

interface AccountRecord {
  username: string;
  salt: string;
  passwordHash: string;
  createdAt: string;
}

// ─── 存储工具 ──────────────────────────────────────────────────────
function readJSON<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
}
function writeJSON(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // 忽略
  }
}
function loadAccounts(): Record<string, AccountRecord> {
  return readJSON<Record<string, AccountRecord>>(ACCOUNTS_KEY, {});
}
function saveAccounts(accounts: Record<string, AccountRecord>): void {
  writeJSON(ACCOUNTS_KEY, accounts);
}
function loadSaves(): Record<string, PlayerState> {
  return readJSON<Record<string, PlayerState>>(SAVES_KEY, {});
}
function saveSaves(saves: Record<string, PlayerState>): void {
  writeJSON(SAVES_KEY, saves);
}

// ─── tokenStorage（与原 API 兼容）──────────────────────────────────
export const tokenStorage = {
  get: (): string | null => {
    try {
      return localStorage.getItem(TOKEN_KEY);
    } catch {
      return null;
    }
  },
  set: (token: string): void => {
    try {
      localStorage.setItem(TOKEN_KEY, token);
    } catch {
      // ignore
    }
  },
  getUsername: (): string | null => {
    try {
      return localStorage.getItem(USERNAME_KEY);
    } catch {
      return null;
    }
  },
  setUsername: (username: string): void => {
    try {
      localStorage.setItem(USERNAME_KEY, username);
    } catch {
      // ignore
    }
  },
  clear: (): void => {
    try {
      localStorage.removeItem(TOKEN_KEY);
      localStorage.removeItem(USERNAME_KEY);
    } catch {
      // ignore
    }
  },
  key: TOKEN_KEY,
  usernameKey: USERNAME_KEY,
};

// ─── 时间工具（Asia/Shanghai UTC+8）────────────────────────────────
function todayStr(): string {
  const now = new Date();
  const utcMs = now.getTime() + now.getTimezoneOffset() * 60 * 1000;
  const shanghaiMs = utcMs + 8 * 60 * 60 * 1000;
  const s = new Date(shanghaiMs);
  const year = s.getUTCFullYear();
  const month = String(s.getUTCMonth() + 1).padStart(2, '0');
  const day = String(s.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

// ─── 默认存档 ──────────────────────────────────────────────────────
function defaultSave(): PlayerState {
  return {
    chipBalance: 0,
    experience: 0,
    unlockedWheelLevel: 1,
    lastCheckinDate: null,
    hasCheckedInToday: false,
    loanPrincipal: 0,
    loanInterestRate: 0.2,
    loanGamesRemaining: 0,
    loanTimesToday: 0,
    lastLoanDate: null,
    zdAutoSpin: false,
    zd1: false,
    zd2: false,
    zd3: false,
  };
}

function getSave(username: string): PlayerState {
  const saves = loadSaves();
  const s = saves[username];
  if (!s) {
    const def = defaultSave();
    saves[username] = def;
    saveSaves(saves);
    return def;
  }
  const today = todayStr();
  return {
    ...s,
    hasCheckedInToday: s.lastCheckinDate === today,
    loanTimesToday: s.lastLoanDate === today ? s.loanTimesToday : 0,
  };
}
function setSave(username: string, state: PlayerState): void {
  const saves = loadSaves();
  saves[username] = state;
  saveSaves(saves);
}
function requireUser(): string {
  const u = tokenStorage.getUsername();
  if (!u) throw new Error('请先登录');
  return u;
}

// ─── 密码哈希（Web Crypto，仅供本地演示）────────────────────────────
async function sha256Hex(seed: string): Promise<string> {
  const data = new TextEncoder().encode(seed);
  const buf = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}
function randomSalt(): string {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}
async function hashPassword(password: string): Promise<{ salt: string; hash: string }> {
  const salt = randomSalt();
  const hash = await sha256Hex(`${salt}:${password}`);
  return { salt, hash };
}
async function verifyPassword(password: string, salt: string, storedHash: string): Promise<boolean> {
  const hash = await sha256Hex(`${salt}:${password}`);
  return hash === storedHash;
}

// ─── 轮盘配置（移植自 casino.service）──────────────────────────────
type WheelLevel = 1 | 2 | 3;
interface WheelConfig {
  chipSectors: { angle: number; value: number }[];
  retryAngle: number;
  thanksAngle: number;
  cost: number;
  expGain: number;
}
const WHEEL_CONFIGS: Record<WheelLevel, WheelConfig> = {
  1: {
    chipSectors: [
      { angle: 64.8, value: 10 },
      { angle: 64.8, value: 20 },
      { angle: 64.8, value: 30 },
      { angle: 64.8, value: 50 },
      { angle: 64.8, value: 100 },
    ],
    retryAngle: 18,
    thanksAngle: 18,
    cost: 0,
    expGain: 5,
  },
  2: {
    chipSectors: [
      { angle: 50.4, value: 100 },
      { angle: 50.4, value: 200 },
      { angle: 50.4, value: 300 },
      { angle: 50.4, value: 500 },
      { angle: 50.4, value: 1000 },
    ],
    retryAngle: 54,
    thanksAngle: 54,
    cost: 200,
    expGain: 7,
  },
  3: {
    chipSectors: [
      { angle: 36, value: 1000 },
      { angle: 36, value: 2000 },
      { angle: 36, value: 3000 },
      { angle: 36, value: 5000 },
      { angle: 36, value: 10000 },
    ],
    retryAngle: 90,
    thanksAngle: 90,
    cost: 1000,
    expGain: 10,
  },
};
const LEVEL_UNLOCK_EXP: Record<number, number> = { 2: 100, 3: 1000 };

function spinWheelRandom(level: WheelLevel): { type: SpinResultType; value?: number } {
  const config = WHEEL_CONFIGS[level];
  const angle = Math.random() * 360;
  let cumulative = 0;
  for (const sector of config.chipSectors) {
    cumulative += sector.angle;
    if (angle < cumulative) return { type: 'chip', value: sector.value };
  }
  cumulative += config.retryAngle;
  if (angle < cumulative) return { type: 'retry' };
  return { type: 'thanks' };
}

function calcWheelUnlock(
  current: number,
  exp: number,
): { unlockedWheelLevel: number; newLevelUnlocked?: number } {
  let lvl = current;
  let unlocked: number | undefined;
  for (let l = current + 1; l <= 3; l += 1) {
    const need = LEVEL_UNLOCK_EXP[l];
    if (need && exp >= need && lvl < l) {
      lvl = l;
      unlocked = l;
    }
  }
  return { unlockedWheelLevel: lvl, newLevelUnlocked: unlocked };
}

// ─── 贷款规则（移植自 loan.service）────────────────────────────────
const DAILY_LOAN_LIMIT = 1;
const MIN_LOAN_AMOUNT = 1000;
const MAX_LOAN_AMOUNT = 10000;
const LOAN_INTEREST_RATE = 0.2;
const LOAN_GAMES_REMAINING = 10;
const MIN_BALANCE_FOR_LOAN = 1000;
const OVERDUE_COLLECT_RATE = 0.3;

function autoCollectDebt(state: PlayerState, winAmount: number): number {
  if (state.loanPrincipal <= 0) return 0;
  if (state.loanGamesRemaining > 0) return 0;
  if (winAmount <= 0) return 0;
  const totalDebt = Math.ceil(state.loanPrincipal * (1 + state.loanInterestRate));
  return Math.min(Math.floor(winAmount * OVERDUE_COLLECT_RATE), totalDebt);
}

function handleLoanGameEnd(state: PlayerState, extraPrincipalPayment: number): PlayerState {
  if (state.loanPrincipal <= 0) return state;
  const newRemaining = Math.max(0, state.loanGamesRemaining - 1);
  let newPrincipal = state.loanPrincipal;
  if (extraPrincipalPayment > 0 && newPrincipal > 0) {
    newPrincipal -= Math.min(extraPrincipalPayment, newPrincipal);
  }
  return { ...state, loanGamesRemaining: newRemaining, loanPrincipal: newPrincipal };
}

function validateMinBet(amount: number, tier: CasinoTier): void {
  const minByTier: Record<CasinoTier, number> = {
    1: 0,
    2: 10,
    3: 100,
    4: 1000,
    5: 10000,
  };
  const min = minByTier[tier] ?? 0;
  if (min > 0 && amount < min) {
    throw new Error(`该赌场最低下注 ${min} 筹码`);
  }
}

// ─── 账号：注册 / 登录 / 取当前玩家 / 签到 / 兑换码 / 同步存档 ─────────
export async function register(
  username: string,
  password: string,
): Promise<GameAccountAuthResponse> {
  const name = (username || '').trim();
  if (!name || name.length < 2 || name.length > 50) {
    throw new Error('用户名长度需在 2-50 个字符之间');
  }
  if (!password || password.length < 6) {
    throw new Error('密码至少 6 位');
  }
  const accounts = loadAccounts();
  if (accounts[name]) {
    throw new Error('该用户名已被注册');
  }
  const { salt, hash } = await hashPassword(password);
  accounts[name] = {
    username: name,
    salt,
    passwordHash: hash,
    createdAt: new Date().toISOString(),
  };
  saveAccounts(accounts);
  const player = getSave(name);
  setTokenSession(name);
  return { success: true, token: `local_${name}`, username: name, player, message: '注册成功！' };
}

export async function login(
  username: string,
  password: string,
): Promise<GameAccountAuthResponse> {
  const name = (username || '').trim();
  if (!name || !password) {
    throw new Error('请输入用户名和密码');
  }
  const accounts = loadAccounts();
  const account = accounts[name];
  if (!account) {
    throw new Error('用户名或密码错误');
  }
  const valid = await verifyPassword(password, account.salt, account.passwordHash);
  if (!valid) {
    throw new Error('用户名或密码错误');
  }
  const player = getSave(name);
  setTokenSession(name);
  return { success: true, token: `local_${name}`, username: name, player, message: '登录成功' };
}

function setTokenSession(username: string): void {
  tokenStorage.set(`local_${username}`);
  tokenStorage.setUsername(username);
}

export async function getMe(): Promise<PlayerState> {
  return getSave(requireUser());
}

export async function syncSave(data: GameSaveSyncRequest): Promise<GameSaveSyncResponse> {
  const username = requireUser();
  const cur = getSave(username);
  const merged: PlayerState = {
    ...cur,
    chipBalance: data.chipBalance,
    experience: data.experience,
    unlockedWheelLevel: data.unlockedWheelLevel,
    lastCheckinDate: data.lastCheckinDate,
    loanPrincipal: data.loanPrincipal,
    loanInterestRate: data.loanInterestRate,
    loanGamesRemaining: data.loanGamesRemaining,
    loanTimesToday: data.loanTimesToday,
    lastLoanDate: data.lastLoanDate,
  };
  setSave(username, merged);
  return { success: true, message: '存档已保存' };
}

export async function checkIn(): Promise<CheckInResponse> {
  const username = requireUser();
  const state = getSave(username);
  if (state.hasCheckedInToday) {
    return { success: false, reward: 0, message: '今日已签到，明天再来吧', player: state };
  }
  const today = todayStr();
  const newBalance = state.chipBalance + 100;
  const newState: PlayerState = {
    ...state,
    chipBalance: newBalance,
    lastCheckinDate: today,
    hasCheckedInToday: true,
  };
  setSave(username, newState);
  return { success: true, reward: 100, message: '签到成功！获得 100 筹码', player: newState };
}

export interface RedeemCodeResponse {
  success: boolean;
  message: string;
  zdAutoSpin: boolean;
  player?: PlayerState;
}

export async function redeemCode(code: string): Promise<RedeemCodeResponse> {
  const username = requireUser();
  const normalized = (code || '').trim().toUpperCase();
  const levelMap: Record<string, 1 | 2 | 3> = { ZD1: 1, ZD2: 2, ZD3: 3 };
  const level = levelMap[normalized];
  if (!level) {
    return { success: false, message: '兑换码无效', zdAutoSpin: false };
  }
  const state = getSave(username);
  const newValue = !(level === 1 ? state.zd1 : level === 2 ? state.zd2 : state.zd3);
  const newState: PlayerState = {
    ...state,
    zd1: level === 1 ? newValue : state.zd1,
    zd2: level === 2 ? newValue : state.zd2,
    zd3: level === 3 ? newValue : state.zd3,
  };
  setSave(username, newState);
  const levelName = level === 1 ? '一级' : level === 2 ? '二级' : '三级';
  return {
    success: true,
    message: newValue ? `${levelName}自动转盘已开启` : `${levelName}自动转盘已关闭`,
    zdAutoSpin: newValue,
    player: newState,
  };
}

// ─── 轮盘 ──────────────────────────────────────────────────────────
export async function spinWheel(level: number): Promise<SpinResult> {
  const username = requireUser();
  const player = getSave(username);
  if (level !== 1 && level !== 2 && level !== 3) throw new Error('无效的轮盘等级');
  const wheelLevel = level as WheelLevel;
  if (player.unlockedWheelLevel < wheelLevel) throw new Error('该等级轮盘尚未解锁');

  const config = WHEEL_CONFIGS[wheelLevel];
  const cost = config.cost;
  if (cost > 0 && player.chipBalance < cost) throw new Error('筹码不足，请先充值或贷款');

  let newBalance = player.chipBalance - cost;
  const outcome = spinWheelRandom(wheelLevel);
  let type: SpinResultType = outcome.type;
  let chipAmount: number | undefined;
  let message: string;

  if (outcome.type === 'chip') {
    chipAmount = outcome.value;
    newBalance += chipAmount;
    message = `恭喜！获得 ${chipAmount} 筹码`;
  } else if (outcome.type === 'retry') {
    newBalance += cost;
    message = '再来一次！本次免费重转';
  } else {
    message = '谢谢参与，下次好运！';
  }

  const expGained = config.expGain;
  const newExp = player.experience + expGained;
  const { unlockedWheelLevel, newLevelUnlocked } = calcWheelUnlock(
    player.unlockedWheelLevel,
    newExp,
  );
  const afterLoan = handleLoanGameEnd(player, 0);
  const finalPlayer: PlayerState = {
    ...afterLoan,
    chipBalance: newBalance,
    experience: newExp,
    unlockedWheelLevel,
    zdAutoSpin: afterLoan.zdAutoSpin,
  };
  setSave(username, finalPlayer);

  return {
    type,
    chipAmount,
    expGained,
    newLevelUnlocked,
    cost,
    message,
    player: finalPlayer,
  };
}

// ─── 贷款 ──────────────────────────────────────────────────────────
export async function getLoanStatus(): Promise<LoanStatus> {
  const username = requireUser();
  const save = getSave(username);
  const today = todayStr();
  const isLastLoanToday = save.lastLoanDate === today;
  const loanTimesToday = isLastLoanToday ? save.loanTimesToday : 0;
  const principal = save.loanPrincipal;
  const interestRate = save.loanInterestRate ?? LOAN_INTEREST_RATE;
  const totalDebt = Math.ceil(principal * (1 + interestRate));
  return {
    hasLoan: principal > 0,
    principal,
    interestRate,
    totalDebt: principal > 0 ? totalDebt : 0,
    gamesRemaining: save.loanGamesRemaining,
    canApplyToday: loanTimesToday < DAILY_LOAN_LIMIT && principal === 0,
    loanTimesToday,
    dailyLimit: DAILY_LOAN_LIMIT,
  };
}

export async function applyLoan(): Promise<LoanApplyResponse & { player: PlayerState }> {
  const username = requireUser();
  const save = getSave(username);
  const today = todayStr();
  const isLastLoanToday = save.lastLoanDate === today;
  const loanTimesToday = isLastLoanToday ? save.loanTimesToday : 0;

  if (save.loanPrincipal > 0) throw new Error('当前有未还贷款');
  if (loanTimesToday >= DAILY_LOAN_LIMIT) throw new Error('今日贷款次数已用完');
  if (save.chipBalance >= MIN_BALANCE_FOR_LOAN) throw new Error('筹码充足，无需贷款');

  const amount =
    Math.floor(Math.random() * (MAX_LOAN_AMOUNT - MIN_LOAN_AMOUNT + 1)) + MIN_LOAN_AMOUNT;
  const totalDebt = Math.ceil(amount * (1 + LOAN_INTEREST_RATE));
  const newBalance = save.chipBalance + amount;

  const player: PlayerState = {
    ...save,
    chipBalance: newBalance,
    loanPrincipal: amount,
    loanInterestRate: LOAN_INTEREST_RATE,
    loanGamesRemaining: LOAN_GAMES_REMAINING,
    lastLoanDate: today,
    loanTimesToday: loanTimesToday + 1,
  };
  setSave(username, player);

  return {
    success: true,
    amount,
    totalDebt,
    gamesRemaining: LOAN_GAMES_REMAINING,
    message: `贷款成功！获得 ${amount} 筹码，需还款 ${totalDebt} 筹码（${LOAN_GAMES_REMAINING} 局内还清）`,
    player,
  };
}

export async function repayLoan(amount: number): Promise<LoanRepayResponse & { player: PlayerState }> {
  const username = requireUser();
  const save = getSave(username);
  if (save.loanPrincipal <= 0) throw new Error('当前没有未还贷款');

  const principal = save.loanPrincipal;
  const interestRate = save.loanInterestRate ?? LOAN_INTEREST_RATE;
  const totalDebt = Math.ceil(principal * (1 + interestRate));
  const interestAmount = Math.ceil(principal * interestRate);

  const maxRepay = Math.min(amount, save.chipBalance);
  const actualRepay = Math.min(maxRepay, totalDebt);

  let remainingDebt: number;
  let newPrincipal: number;
  let newGamesRemaining: number;
  let newInterestRate: number;

  if (actualRepay >= totalDebt) {
    remainingDebt = 0;
    newPrincipal = 0;
    newInterestRate = LOAN_INTEREST_RATE;
    newGamesRemaining = 0;
  } else {
    let remaining = actualRepay;
    const interestPaid = Math.min(remaining, interestAmount);
    remaining -= interestPaid;
    const principalPaid = remaining;
    newPrincipal = principal - principalPaid;
    newInterestRate = interestRate;
    newGamesRemaining = save.loanGamesRemaining;
    remainingDebt = Math.ceil(newPrincipal * (1 + newInterestRate));
  }

  const newBalance = save.chipBalance - actualRepay;
  const player: PlayerState = {
    ...save,
    chipBalance: newBalance,
    loanPrincipal: newPrincipal,
    loanInterestRate: newInterestRate,
    loanGamesRemaining: newGamesRemaining,
  };
  setSave(username, player);

  return {
    success: true,
    repaidAmount: actualRepay,
    remainingDebt,
    message:
      remainingDebt === 0
        ? `还款成功！已还清全部贷款 ${actualRepay} 筹码`
        : `还款成功！已还 ${actualRepay} 筹码，剩余债务 ${remainingDebt} 筹码`,
    player,
  };
}

// ─── 骰宝（移植自 sicbo.service）──────────────────────────────────
export async function placeSicBoBet(
  betType: string,
  amount: number,
  casinoTier: CasinoTier,
): Promise<BetResult> {
  validateMinBet(amount, casinoTier);
  if (!Number.isFinite(amount) || amount <= 0) throw new Error('下注金额必须大于 0');
  const username = requireUser();
  const player = getSave(username);
  if (player.chipBalance < amount) throw new Error('筹码不足');

  const valid = ['big', 'small', 'odd', 'even'];
  if (!valid.includes(betType)) throw new Error(`无效的下注类型: ${betType}`);

  const dice: [number, number, number] = [
    Math.floor(Math.random() * 6) + 1,
    Math.floor(Math.random() * 6) + 1,
    Math.floor(Math.random() * 6) + 1,
  ];
  const sum = dice[0] + dice[1] + dice[2];
  const isTriple = dice[0] === dice[1] && dice[1] === dice[2];
  const isBig = !isTriple && sum >= 11 && sum <= 17;
  const isSmall = !isTriple && sum >= 4 && sum <= 10;
  const isOdd = !isTriple && sum % 2 === 1;
  const isEven = !isTriple && sum % 2 === 0;

  let win = false;
  if (betType === 'big') win = isBig;
  else if (betType === 'small') win = isSmall;
  else if (betType === 'odd') win = isOdd;
  else if (betType === 'even') win = isEven;

  const winAmount = win ? amount : -amount;
  const diceStr = `${dice[0]}-${dice[1]}-${dice[2]}`;
  let message: string;
  if (isTriple) {
    message = `三颗骰子点数相同（${diceStr} = ${sum}，全围通杀），损失 ${amount} 筹码`;
  } else if (win) {
    const label = ({ big: '大', small: '小', odd: '单', even: '双' } as Record<string, string>)[betType];
    message = `恭喜！掷出 ${diceStr} = ${sum} 点，猜中${label}，净赢 ${amount} 筹码`;
  } else {
    message = `很遗憾，掷出 ${diceStr} = ${sum} 点，猜错了，损失 ${amount} 筹码`;
  }

  const result: Record<string, unknown> = { dice, sum, isBig, isSmall, isOdd, isEven, isTriple };
  return playBetGame(username, player, win, winAmount, amount, result, message);
}

// ─── 百家乐（移植自 baccarat.service）──────────────────────────────
export async function placeBaccaratBet(
  betType: string,
  amount: number,
  casinoTier: CasinoTier,
): Promise<BetResult> {
  validateMinBet(amount, casinoTier);
  if (!Number.isFinite(amount) || amount <= 0) throw new Error('下注金额必须大于 0');
  const username = requireUser();
  const player = getSave(username);
  if (player.chipBalance < amount) throw new Error('筹码不足');

  const valid = ['player', 'banker', 'tie'];
  if (!valid.includes(betType)) throw new Error(`无效的下注类型: ${betType}`);

  const PLAYER_OUTCOME_RATE = 0.46;
  const BANKER_OUTCOME_RATE = 0.45;
  const BANKER_COMMISSION = 0.05;
  const TIE_PAYOUT = 8;

  const r = Math.random();
  const winner: 'player' | 'banker' | 'tie' =
    r < PLAYER_OUTCOME_RATE ? 'player' : r < PLAYER_OUTCOME_RATE + BANKER_OUTCOME_RATE ? 'banker' : 'tie';

  const baccaratPoints = (): number => {
    const rr = Math.random();
    if (rr < 0.1) return Math.random() < 0.5 ? 8 : 9;
    return Math.floor(Math.random() * 8);
  };
  const playerPoints = baccaratPoints();
  let bankerPoints: number;
  if (winner === 'tie') bankerPoints = playerPoints;
  else if (winner === 'player') {
    do { bankerPoints = baccaratPoints(); } while (bankerPoints >= playerPoints);
  } else {
    do { bankerPoints = baccaratPoints(); } while (bankerPoints <= playerPoints);
  }

  let win: boolean;
  let winAmount: number;
  if (betType === 'tie') {
    win = winner === 'tie';
    winAmount = win ? amount * TIE_PAYOUT : -amount;
  } else if (betType === 'player') {
    win = winner === 'player';
    winAmount = win ? amount : -amount;
  } else {
    win = winner === 'banker';
    winAmount = win ? Math.floor(amount * (1 - BANKER_COMMISSION)) : -amount;
  }

  const winnerLabel = ({ player: '闲', banker: '庄', tie: '和' } as Record<string, string>)[winner];
  const betLabel = ({ player: '闲', banker: '庄', tie: '和' } as Record<string, string>)[betType];
  let message: string;
  if (betType === 'tie' && win) {
    message = `恭喜！和牌（闲 ${playerPoints} 点 vs 庄 ${bankerPoints} 点），押中 ${betLabel}，净赢 ${winAmount} 筹码`;
  } else if (win) {
    message = `恭喜！${winnerLabel}赢（闲 ${playerPoints} 点 vs 庄 ${bankerPoints} 点），押中 ${betLabel}，净赢 ${winAmount} 筹码`;
  } else {
    message = `很遗憾，${winnerLabel}赢（闲 ${playerPoints} 点 vs 庄 ${bankerPoints} 点），押 ${betLabel} 未中，损失 ${amount} 筹码`;
  }

  const result: Record<string, unknown> = { playerPoints, bankerPoints, winner };
  return playBetGame(username, player, win, winAmount, amount, result, message);
}

// 下注游戏通用结算（移植自 casino.playBetGame）
function playBetGame(
  username: string,
  player: PlayerState,
  win: boolean,
  winAmount: number,
  amount: number,
  result: Record<string, unknown>,
  baseMessage: string,
): BetResult {
  let newBalance = player.chipBalance + winAmount;
  let actualWinAmount = winAmount;
  const autoCollect = win ? autoCollectDebt(player, winAmount) : 0;
  if (autoCollect > 0) {
    newBalance -= autoCollect;
    actualWinAmount = winAmount - autoCollect;
  }
  const expGained = 2;
  const newExp = player.experience + expGained;
  const { unlockedWheelLevel } = calcWheelUnlock(player.unlockedWheelLevel, newExp);
  const afterLoan = handleLoanGameEnd(player, autoCollect);
  const finalPlayer: PlayerState = {
    ...afterLoan,
    chipBalance: newBalance,
    experience: newExp,
    unlockedWheelLevel,
    zdAutoSpin: afterLoan.zdAutoSpin,
  };
  setSave(username, finalPlayer);
  let message = baseMessage;
  if (autoCollect > 0) message += `（自动偿债 ${autoCollect} 筹码）`;
  return {
    win,
    winAmount: actualWinAmount,
    betAmount: amount,
    result,
    expGained,
    message,
    player: finalPlayer,
  };
}

// ─── 21点（移植自 blackjack.service + casino.blackjackAction）──────
interface BlackjackGameState {
  phase: BlackjackPhase;
  playerHand: BlackjackHand;
  dealerHand: BlackjackHand;
  dealerHidden: boolean;
  result: BlackjackResult | null;
  betAmount: number;
  winAmount: number;
  deck: number[];
}
const blackjackSessions = new Map<string, BlackjackGameState>();

function buildShuffledDeck(): number[] {
  const deck: number[] = [];
  for (let s = 0; s < 4; s += 1) {
    for (let r = 1; r <= 13; r += 1) deck.push(r);
  }
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}
function evaluateHand(cards: number[]): BlackjackHand {
  let value = 0;
  let aces = 0;
  for (const card of cards) {
    if (card === 1) { aces += 1; value += 11; }
    else if (card >= 10) value += 10;
    else value += card;
  }
  while (value > 21 && aces > 0) { value -= 10; aces -= 1; }
  return { cards, value, isBust: value > 21, isBlackjack: cards.length === 2 && value === 21 };
}
function createGame(betAmount: number): BlackjackGameState {
  const deck = buildShuffledDeck();
  const playerCards = [deck.pop()!, deck.pop()!];
  const dealerCards = [deck.pop()!, deck.pop()!];
  const playerHand = evaluateHand(playerCards);
  const dealerHand = evaluateHand(dealerCards);
  let result: BlackjackResult | null = null;
  let phase: BlackjackPhase = 'playerTurn';
  let dealerHidden = true;
  let winAmount = 0;
  if (playerHand.isBlackjack && dealerHand.isBlackjack) { result = 'push'; phase = 'finished'; dealerHidden = false; winAmount = 0; }
  else if (playerHand.isBlackjack) { result = 'blackjack'; phase = 'finished'; dealerHidden = false; winAmount = Math.floor(betAmount * 1.5); }
  else if (dealerHand.isBlackjack) { result = 'lose'; phase = 'finished'; dealerHidden = false; winAmount = -betAmount; }
  return { phase, playerHand, dealerHand, dealerHidden, result, betAmount, winAmount, deck };
}
function hit(state: BlackjackGameState): BlackjackGameState {
  const newCard = state.deck.pop()!;
  const newHand = evaluateHand([...state.playerHand.cards, newCard]);
  if (newHand.isBust) {
    return { ...state, playerHand: newHand, phase: 'finished', dealerHidden: false, result: 'lose', winAmount: -state.betAmount };
  }
  if (newHand.value === 21) return stand({ ...state, playerHand: newHand });
  return { ...state, playerHand: newHand };
}
function stand(state: BlackjackGameState): BlackjackGameState {
  let dealerHand = { ...state.dealerHand };
  const deck = [...state.deck];
  while (dealerHand.value < 17) {
    const card = deck.pop()!;
    dealerHand = evaluateHand([...dealerHand.cards, card]);
  }
  let result: BlackjackResult;
  let winAmount: number;
  if (dealerHand.isBust) { result = 'win'; winAmount = state.betAmount; }
  else if (dealerHand.value > state.playerHand.value) { result = 'lose'; winAmount = -state.betAmount; }
  else if (dealerHand.value < state.playerHand.value) { result = 'win'; winAmount = state.betAmount; }
  else { result = 'push'; winAmount = 0; }
  return { ...state, phase: 'finished', dealerHand, dealerHidden: false, result, winAmount, deck };
}
function blackjackMessage(state: BlackjackGameState): string {
  if (state.phase === 'playerTurn') return `你的点数：${state.playerHand.value}，请选择要牌或停牌`;
  if (state.result === 'blackjack') return `黑杰克！你 21 点 vs 庄家 ${state.dealerHand.value} 点，净赢 ${state.winAmount} 筹码`;
  if (state.result === 'win') return `赢了！你 ${state.playerHand.value} 点 vs 庄家 ${state.dealerHand.value} 点，净赢 ${state.winAmount} 筹码`;
  if (state.result === 'lose') {
    if (state.playerHand.isBust) return `爆牌了！你 ${state.playerHand.value} 点，损失 ${state.betAmount} 筹码`;
    return `输了！你 ${state.playerHand.value} 点 vs 庄家 ${state.dealerHand.value} 点，损失 ${state.betAmount} 筹码`;
  }
  return `平局！你 ${state.playerHand.value} 点 vs 庄家 ${state.dealerHand.value} 点，退还本金`;
}
function dealtBlackjackState(state: BlackjackGameState): BlackjackState {
  return {
    phase: state.phase,
    playerHand: state.playerHand,
    dealerHand: {
      ...state.dealerHand,
      cards: state.dealerHidden ? [state.dealerHand.cards[0]] : state.dealerHand.cards,
      value: state.dealerHidden ? 0 : state.dealerHand.value,
      isBust: false,
      isBlackjack: false,
    },
    dealerHidden: state.dealerHidden,
    result: state.result,
    betAmount: state.betAmount,
    winAmount: state.winAmount,
    expGained: 0,
    message: blackjackMessage(state),
  };
}
function finalizeBlackjack(username: string, state: BlackjackGameState): BlackjackState {
  const player = getSave(username);
  const expGained = 2;
  const newExp = player.experience + expGained;
  const { unlockedWheelLevel } = calcWheelUnlock(player.unlockedWheelLevel, newExp);
  let newBalance = player.chipBalance + state.winAmount;
  let autoCollect = 0;
  if (state.winAmount > 0) {
    autoCollect = autoCollectDebt(player, state.winAmount);
    if (autoCollect > 0) newBalance -= autoCollect;
  }
  const afterLoan = handleLoanGameEnd(player, autoCollect);
  const finalPlayer: PlayerState = {
    ...afterLoan,
    chipBalance: newBalance,
    experience: newExp,
    unlockedWheelLevel,
    zdAutoSpin: afterLoan.zdAutoSpin,
  };
  setSave(username, finalPlayer);
  let message = blackjackMessage(state);
  if (autoCollect > 0) message += `（自动偿债 ${autoCollect} 筹码）`;
  blackjackSessions.delete(username);
  return {
    phase: 'finished',
    playerHand: state.playerHand,
    dealerHand: state.dealerHand,
    dealerHidden: false,
    result: state.result,
    betAmount: state.betAmount,
    winAmount: state.winAmount - autoCollect,
    expGained,
    player: finalPlayer,
    message,
  };
}

export async function blackjackAction(
  action: 'deal' | 'hit' | 'stand',
  amount?: number,
  casinoTier?: CasinoTier,
): Promise<BlackjackState> {
  const username = requireUser();
  if (action === 'deal') {
    if (!amount || amount <= 0) throw new Error('下注金额必须大于 0');
    if (casinoTier) validateMinBet(amount, casinoTier);
    const player = getSave(username);
    if (player.chipBalance < amount) throw new Error('筹码不足');
    const state = createGame(amount);
    blackjackSessions.set(username, state);
    if (state.phase === 'finished') return finalizeBlackjack(username, state);
    return dealtBlackjackState(state);
  }
  const session = blackjackSessions.get(username);
  if (!session || session.phase !== 'playerTurn') throw new Error('没有进行中的21点对局，请先发牌');
  const newState = action === 'hit' ? hit(session) : stand(session);
  blackjackSessions.set(username, newState);
  if (newState.phase === 'finished') return finalizeBlackjack(username, newState);
  return dealtBlackjackState(newState);
}

// ─── 德州扑克简化版（移植自 texas.service + casino.texasAction）────
interface Card { rank: number; suit: number; }
const RANK_VALUES: Record<string, number> = {
  high_card: 0, one_pair: 1, two_pair: 2, three_of_a_kind: 3, straight: 4,
  flush: 5, full_house: 6, four_of_a_kind: 7, straight_flush: 8,
};
interface TexasSessionState {
  playerCards: Card[];
  dealerCards: Card[];
  betAmount: number;
  playerHand: TexasHand;
}
const texasSessions = new Map<string, TexasSessionState>();

function texasDeal(): { playerCards: Card[]; dealerCards: Card[] } {
  const deck: Card[] = [];
  for (let s = 0; s < 4; s += 1) for (let r = 2; r <= 14; r += 1) deck.push({ rank: r, suit: s });
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  const playerCards: Card[] = [];
  const dealerCards: Card[] = [];
  for (let i = 0; i < 5; i += 1) {
    playerCards.push(deck.pop()!);
    dealerCards.push(deck.pop()!);
  }
  return { playerCards, dealerCards };
}
function texasEvaluate(cards: Card[]): TexasHand {
  const sorted = [...cards].sort((a, b) => b.rank - a.rank);
  const ranks = sorted.map((c) => c.rank);
  const suits = sorted.map((c) => c.suit);
  const isFlush = suits.every((s) => s === suits[0]);
  const uniqueRanks = [...new Set(ranks)].sort((a, b) => b - a);
  let isStraight = false;
  let straightHigh = 0;
  if (uniqueRanks.length === 5) {
    if (uniqueRanks[0] - uniqueRanks[4] === 4) { isStraight = true; straightHigh = uniqueRanks[0]; }
    if (uniqueRanks[0] === 14 && uniqueRanks[1] === 5 && uniqueRanks[2] === 4 && uniqueRanks[3] === 3 && uniqueRanks[4] === 2) { isStraight = true; straightHigh = 5; }
  }
  const rankCounts: Record<number, number> = {};
  for (const r of ranks) rankCounts[r] = (rankCounts[r] || 0) + 1;
  const counts = Object.values(rankCounts).sort((a, b) => b - a);
  let rank: string = 'high_card';
  let description = '高牌';
  if (isStraight && isFlush) { rank = 'straight_flush'; description = '同花顺'; }
  else if (counts[0] === 4) { rank = 'four_of_a_kind'; description = '四条'; }
  else if (counts[0] === 3 && counts[1] === 2) { rank = 'full_house'; description = '葫芦'; }
  else if (isFlush) { rank = 'flush'; description = '同花'; }
  else if (isStraight) { rank = 'straight'; description = '顺子'; }
  else if (counts[0] === 3) { rank = 'three_of_a_kind'; description = '三条'; }
  else if (counts[0] === 2 && counts[1] === 2) { rank = 'two_pair'; description = '两对'; }
  else if (counts[0] === 2) { rank = 'one_pair'; description = '一对'; }
  const rankValue = RANK_VALUES[rank] * 1e10 + tiebreakerValue(sorted, rank, straightHigh);
  return { cards: sorted.map((c) => ({ rank: c.rank, suit: c.suit })), rank: rank as TexasHand['rank'], rankValue, description };
}
function tiebreakerValue(sorted: Card[], rank: string, straightHigh: number): number {
  if (rank === 'straight' || rank === 'straight_flush') return straightHigh * 1e8;
  const rankCounts: Record<number, number> = {};
  for (const c of sorted) rankCounts[c.rank] = (rankCounts[c.rank] || 0) + 1;
  const groups = Object.entries(rankCounts)
    .map(([r, c]) => ({ rank: Number(r), count: c }))
    .sort((a, b) => (b.count !== a.count ? b.count - a.count : b.rank - a.rank));
  let value = 0;
  let multiplier = 1e8;
  for (const g of groups) { value += g.rank * multiplier; multiplier /= 100; }
  return value;
}
function texasCompareHands(player: TexasHand, dealer: TexasHand): 'player' | 'dealer' | 'tie' {
  if (player.rankValue > dealer.rankValue) return 'player';
  if (player.rankValue < dealer.rankValue) return 'dealer';
  return 'tie';
}

export async function texasAction(
  action: 'deal' | 'call' | 'fold',
  amount?: number,
  casinoTier?: CasinoTier,
): Promise<TexasState> {
  const username = requireUser();
  if (action === 'deal') {
    if (!amount || amount <= 0) throw new Error('下注金额必须大于 0');
    if (casinoTier) validateMinBet(amount, casinoTier);
    const player = getSave(username);
    if (player.chipBalance < amount) throw new Error('筹码不足');
    const { playerCards, dealerCards } = texasDeal();
    const playerHand = texasEvaluate(playerCards);
    texasSessions.set(username, { playerCards, dealerCards, betAmount: amount, playerHand });
    return {
      phase: 'playerTurn',
      playerHand,
      dealerHand: null,
      betAmount: amount,
      callAmount: amount,
      winAmount: 0,
      expGained: 0,
      playerWon: null,
      message: `你拿到了 ${playerHand.description}，是否跟注开牌？跟注额：${amount} 筹码`,
    };
  }

  const session = texasSessions.get(username);
  if (!session || !session.playerHand) throw new Error('没有进行中的对局，请先发牌');
  const player = getSave(username);
  const expGained = 2;
  const newExp = player.experience + expGained;
  const { unlockedWheelLevel } = calcWheelUnlock(player.unlockedWheelLevel, newExp);

  let winAmount = 0;
  let playerWon: boolean | null = null;
  let message = '';
  let dealerHand: TexasHand | null = null;

  if (action === 'fold') {
    winAmount = -session.betAmount;
    playerWon = false;
    dealerHand = texasEvaluate(session.dealerCards);
    message = `你弃牌了，损失 ${session.betAmount} 筹码。庄家的牌是 ${dealerHand.description}`;
  } else {
    const totalBet = session.betAmount * 2;
    if (player.chipBalance < totalBet) throw new Error('筹码不足，无法跟注');
    dealerHand = texasEvaluate(session.dealerCards);
    const result = texasCompareHands(session.playerHand, dealerHand);
    if (result === 'player') {
      winAmount = session.betAmount;
      playerWon = true;
      message = `你赢了！你的 ${session.playerHand.description} vs 庄家 ${dealerHand.description}，净赢 ${session.betAmount} 筹码`;
    } else if (result === 'dealer') {
      winAmount = -totalBet;
      playerWon = false;
      message = `你输了！你的 ${session.playerHand.description} vs 庄家 ${dealerHand.description}，损失 ${totalBet} 筹码`;
    } else {
      winAmount = -session.betAmount;
      playerWon = false;
      message = `平局！你的 ${session.playerHand.description} vs 庄家 ${dealerHand.description}，损失底注 ${session.betAmount} 筹码`;
    }
  }

  let newBalance = player.chipBalance + winAmount;
  let autoCollect = 0;
  if (winAmount > 0) {
    autoCollect = autoCollectDebt(player, winAmount);
    if (autoCollect > 0) newBalance -= autoCollect;
  }
  const afterLoan = handleLoanGameEnd(player, autoCollect);
  const finalPlayer: PlayerState = {
    ...afterLoan,
    chipBalance: newBalance,
    experience: newExp,
    unlockedWheelLevel,
    zdAutoSpin: afterLoan.zdAutoSpin,
  };
  setSave(username, finalPlayer);
  if (autoCollect > 0) message += `（自动偿债 ${autoCollect} 筹码）`;
  texasSessions.delete(username);
  return {
    phase: 'finished',
    playerHand: session.playerHand,
    dealerHand,
    betAmount: session.betAmount,
    callAmount: session.betAmount,
    winAmount: winAmount - autoCollect,
    expGained,
    playerWon,
    message,
    playerState: finalPlayer,
  };
}

// ─── 排行榜（本地账号之间）──────────────────────────────────────────
const LEVEL_EXP_THRESHOLDS: number[] = [
  0, 50, 120, 210, 320, 450, 600, 780, 1000, 1300,
  1700, 2200, 2800, 3600, 4500, 5600, 7000, 8800, 11000, 14000,
  18000, 23000, 30000, 38000, 50000,
];
const LEVEL_NAMES: string[] = [
  '新手赌客', '初级玩家', '见习赌徒', '熟练玩家', '赌场常客',
  '高手玩家', '赌场精英', '资深赌客', '赌场达人', '半职业玩家',
  '职业赌客', '赌场大师', '赌王传人', '传奇玩家', '赌场神话',
  '至尊赌客', '赌场帝王', '不败传说', '赌神', '永恒神话',
  '混沌赌圣', '虚空赌皇', '命运主宰', '时空赌神', '创世赌王',
];
function calcLevel(exp: number): { level: number; levelName: string } {
  let levelIndex = 0;
  for (let i = 0; i < LEVEL_EXP_THRESHOLDS.length; i += 1) {
    if (exp >= LEVEL_EXP_THRESHOLDS[i]) levelIndex = i;
    else break;
  }
  return { level: levelIndex + 1, levelName: LEVEL_NAMES[levelIndex] ?? LEVEL_NAMES[LEVEL_NAMES.length - 1] };
}
function calcNetWorth(save: PlayerState): number {
  return Math.floor(save.chipBalance - Math.ceil(save.loanPrincipal * (1 + save.loanInterestRate)));
}

export async function getLeaderboard(
  type: LeaderboardType,
  limit: number = 50,
): Promise<LeaderboardResponse> {
  const username = requireUser();
  if (type !== 'level' && type !== 'cashflow') throw new Error('无效的排行榜类型');
  if (limit <= 0) throw new Error('limit 必须大于 0');
  const actualLimit = Math.min(limit, 100);
  const accounts = loadAccounts();
  const saves = loadSaves();
  const rows = Object.keys(accounts).map((u) => ({
    username: u,
    save: saves[u] ?? defaultSave(),
  }));
  const total = rows.length;
  const mySave = saves[username] ?? defaultSave();
  const myValue = type === 'level' ? mySave.experience : calcNetWorth(mySave);

  const sorted =
    type === 'level'
      ? rows.slice().sort((a, b) => b.save.experience - a.save.experience)
      : rows.slice().sort((a, b) => calcNetWorth(b.save) - calcNetWorth(a.save));

  const items: LeaderboardEntry[] = sorted.slice(0, actualLimit).map((r, index) => {
    const value = type === 'level' ? r.save.experience : calcNetWorth(r.save);
    const entry: LeaderboardEntry = { rank: index + 1, username: r.username, value };
    if (type === 'level') {
      const li = calcLevel(r.save.experience);
      entry.level = li.level;
      entry.levelName = li.levelName;
    }
    return entry;
  });

  const myRank =
    type === 'level'
      ? rows.filter((r) => r.save.experience > myValue).length + 1
      : rows.filter((r) => calcNetWorth(r.save) > myValue).length + 1;

  return { items, myRank, myValue, total };
}

