// ─── 存档导入/导出（跨设备手动备份）─────────────────────────────────
export function exportSave(): string {
  const username = requireUser();
  const save = getSave(username);
  return JSON.stringify({ username, savedAt: new Date().toISOString(), ...save }, null, 2);
}
export function importSave(json: string): { success: boolean; message: string } {
  try {
    const data = JSON.parse(json) as Record<string, unknown> & {
      username?: string;
      chipBalance?: unknown;
    };
    const username =
      typeof data.username === 'string' && data.username ? data.username : requireUser();
    if (typeof data.chipBalance !== 'number') throw new Error('存档格式不正确');
    const merged: PlayerState = {
      ...defaultSave(),
      ...(data as Partial<PlayerState>),
    };
    merged.lastCheckinDate = typeof data.lastCheckinDate === 'string' ? data.lastCheckinDate : null;
    merged.lastLoanDate = typeof data.lastLoanDate === 'string' ? data.lastLoanDate : null;
    merged.loanInterestRate = typeof data.loanInterestRate === 'number' ? data.loanInterestRate : 0.2;
    merged.hasCheckedInToday = merged.lastCheckinDate === todayStr();
    setSave(username, merged);
    return { success: true, message: `已导入存档：${username}` };
  } catch (err) {
    return { success: false, message: (err as Error).message || '导入失败' };
  }
}
export function resetLocalAccount(username: string): void {
  const accounts = loadAccounts();
  delete accounts[username];
  saveAccounts(accounts);
  const saves = loadSaves();
  delete saves[username];
  saveSaves(saves);
  if (tokenStorage.getUsername() === username) tokenStorage.clear();
}
