const LEVEL_EXP_THRESHOLDS = [
  0, 50, 120, 210, 320, 450, 600, 780, 1000, 1300,
  1700, 2200, 2800, 3600, 4500, 5600, 7000, 8800, 11000, 14000,
  18000, 23000, 30000, 38000, 50000,
];

const LEVEL_NAMES = [
  '新手赌客', '初级玩家', '见习赌徒', '熟练玩家', '赌场常客',
  '高手玩家', '赌场精英', '资深赌客', '赌场达人', '半职业玩家',
  '职业赌客', '赌场大师', '赌王传人', '传奇玩家', '赌场神话',
  '至尊赌客', '赌场帝王', '不败传说', '赌神', '永恒神话',
  '混沌赌圣', '虚空赌皇', '命运主宰', '时空赌神', '创世赌王',
];

export function getPlayerLevelInfo(experience: number): PlayerLevelInfo {
  let level = 1;
  for (let i = 0; i < LEVEL_EXP_THRESHOLDS.length; i++) {
    if (experience >= LEVEL_EXP_THRESHOLDS[i]) {
      level = i + 1;
    } else {
      break;
    }
  }

  const isMax = level >= LEVEL_EXP_THRESHOLDS.length;
  const currentExp = experience;
  const nextLevelExp = isMax
    ? LEVEL_EXP_THRESHOLDS[LEVEL_EXP_THRESHOLDS.length - 1]
    : LEVEL_EXP_THRESHOLDS[level];
  const currentLevelBase = isMax
    ? LEVEL_EXP_THRESHOLDS[LEVEL_EXP_THRESHOLDS.length - 1]
    : LEVEL_EXP_THRESHOLDS[level - 1];
  const progress = isMax
    ? 100
    : Math.min(
        100,
        Math.round(
          ((currentExp - currentLevelBase) / (nextLevelExp - currentLevelBase)) *
            100,
        ),
      );

  const levelName = isMax
    ? LEVEL_NAMES[LEVEL_NAMES.length - 1]
    : LEVEL_NAMES[level - 1] ?? '未知等级';

  return {
    level,
    levelName,
    currentExp,
    nextLevelExp,
    progress,
    isMax,
  };
}

export function getCurrentCasinoTier(experience: number): CasinoTier {
  let tier: CasinoTier = 1;
  for (const casino of CASINOS) {
    if (experience >= casino.unlockExp) {
      tier = casino.tier as CasinoTier;
    } else {
      break;
    }
  }
  return tier;
}

export function getNextCasinoToUnlock(experience: number): CasinoInfo | null {
  for (const casino of CASINOS) {
    if (experience < casino.unlockExp) {
      return casino;
    }
  }
  return null;
}

export function isCasinoUnlocked(experience: number, tier: CasinoTier): boolean {
  const casino = CASINOS.find(c => c.tier === tier);
  if (!casino) return false;
  return experience >= casino.unlockExp;
}

const WHEEL_UNLOCK_EXP = { 1: 0, 2: 100, 3: 1000 };

export function getWheelLevelByExp(experience: number): 1 | 2 | 3 {
  if (experience >= WHEEL_UNLOCK_EXP[3]) return 3;
  if (experience >= WHEEL_UNLOCK_EXP[2]) return 2;
  return 1;
}

export function getWheelExpProgress(experience: number, currentWheel: number): { progress: number; next: number; isMax: boolean } {
  if (currentWheel >= 3) return { progress: 100, next: 0, isMax: true };
  const next = WHEEL_UNLOCK_EXP[(currentWheel + 1) as 2 | 3];
  const prev = WHEEL_UNLOCK_EXP[currentWheel as 1 | 2];
  const progress = Math.min(100, Math.round(((experience - prev) / (next - prev)) * 100));
  return { progress, next, isMax: false };
}
