import React from 'react';
import type { SpinResultType } from '@shared/api.interface';

// Sector order (clockwise from top=0°): chip1, chip2, chip3, chip4, chip5, retry, thanks
export interface SectorInfo {
  startAngle: number;
  endAngle: number;
  centerAngle: number;
  type: SpinResultType;
  amount?: number;
  color: string;
  label: string;
}

export const WHEEL_SIZE = 300;
export const WHEEL_RADIUS = 140;
const CENTER_X = 150;
const CENTER_Y = 150;

const GOLD_SHADES = ['#FFE066', '#E6B422', '#FFD700', '#C9A227', '#F5C518'];
const RETRY_COLOR = '#16a34a';
const THANKS_COLOR = '#b91c1c';

export interface WheelConfigData {
  chipAmounts: number[];
  chipSectorAngle: number;
  retryAngle: number;
  thanksAngle: number;
}

export const WHEEL_CONFIGS: Record<number, WheelConfigData> = {
  1: { chipAmounts: [10, 20, 30, 50, 100], chipSectorAngle: 64.8, retryAngle: 18, thanksAngle: 18 },
  2: { chipAmounts: [100, 200, 300, 500, 1000], chipSectorAngle: 50.4, retryAngle: 54, thanksAngle: 54 },
  3: { chipAmounts: [1000, 2000, 3000, 5000, 10000], chipSectorAngle: 36, retryAngle: 90, thanksAngle: 90 },
};

export function buildSectors(level: number): SectorInfo[] {
  const cfg = WHEEL_CONFIGS[level];
  const sectors: SectorInfo[] = [];
  let cursor = 0;

  cfg.chipAmounts.forEach((amount: number, i: number) => {
    sectors.push({
      startAngle: cursor,
      endAngle: cursor + cfg.chipSectorAngle,
      centerAngle: cursor + cfg.chipSectorAngle / 2,
      type: 'chip',
      amount,
      color: GOLD_SHADES[i % GOLD_SHADES.length],
      label: `${amount}`,
    });
    cursor += cfg.chipSectorAngle;
  });

  sectors.push({
    startAngle: cursor,
    endAngle: cursor + cfg.retryAngle,
    centerAngle: cursor + cfg.retryAngle / 2,
    type: 'retry',
    color: RETRY_COLOR,
    label: '再来一次',
  });
  cursor += cfg.retryAngle;

  sectors.push({
    startAngle: cursor,
    endAngle: cursor + cfg.thanksAngle,
    centerAngle: cursor + cfg.thanksAngle / 2,
    type: 'thanks',
    color: THANKS_COLOR,
    label: '感谢参与',
  });

  return sectors;
}

function sectorPath(startAngle: number, endAngle: number): string {
  const startRad = ((startAngle - 90) * Math.PI) / 180;
  const endRad = ((endAngle - 90) * Math.PI) / 180;
  const x1 = CENTER_X + WHEEL_RADIUS * Math.cos(startRad);
  const y1 = CENTER_Y + WHEEL_RADIUS * Math.sin(startRad);
  const x2 = CENTER_X + WHEEL_RADIUS * Math.cos(endRad);
  const y2 = CENTER_Y + WHEEL_RADIUS * Math.sin(endRad);
  const largeArc = endAngle - startAngle > 180 ? 1 : 0;
  return `M ${CENTER_X} ${CENTER_Y} L ${x1} ${y1} A ${WHEEL_RADIUS} ${WHEEL_RADIUS} 0 ${largeArc} 1 ${x2} ${y2} Z`;
}

interface WheelSvgProps {
  sectors: SectorInfo[];
}

const WheelSvg = React.forwardRef<SVGSVGElement, WheelSvgProps>(
  ({ sectors }, ref) => {
    return (
      <svg
        ref={ref}
        width={WHEEL_SIZE}
        height={WHEEL_SIZE}
        viewBox={`0 0 ${WHEEL_SIZE} ${WHEEL_SIZE}`}
        style={{ transformOrigin: `${CENTER_X}px ${CENTER_Y}px` }}
      >
        {/* Outer ring */}
        <circle
          cx={CENTER_X}
          cy={CENTER_Y}
          r={WHEEL_RADIUS + 4}
          fill="none"
          stroke="hsl(45 100% 55%)"
          strokeWidth="4"
        />
        <circle
          cx={CENTER_X}
          cy={CENTER_Y}
          r={WHEEL_RADIUS + 1}
          fill="none"
          stroke="hsl(45 80% 30%)"
          strokeWidth="2"
        />

        {/* Sectors */}
        <g>
          {sectors.map((s: SectorInfo, i: number) => (
            <path
              key={i}
              d={sectorPath(s.startAngle, s.endAngle)}
              fill={s.color}
              stroke="hsl(220 30% 8%)"
              strokeWidth="1.5"
            />
          ))}
        </g>

        {/* Sector labels */}
        <g>
          {sectors.map((s: SectorInfo, i: number) => {
            const textRadius = WHEEL_RADIUS * 0.6;
            const angleRad = ((s.centerAngle - 90) * Math.PI) / 180;
            const tx = CENTER_X + textRadius * Math.cos(angleRad);
            const ty = CENTER_Y + textRadius * Math.sin(angleRad);
            const textRotate = s.centerAngle;
            const fontSize = s.type === 'chip' ? 14 : 10;
            return (
              <text
                key={`label-${i}`}
                x={tx}
                y={ty}
                fill="hsl(220 30% 8%)"
                fontSize={fontSize}
                fontWeight="bold"
                textAnchor="middle"
                dominantBaseline="middle"
                transform={`rotate(${textRotate} ${tx} ${ty})`}
                style={{ userSelect: 'none' }}
              >
                {s.type === 'chip' ? s.amount : s.label}
              </text>
            );
          })}
        </g>

        {/* Center hub */}
        <circle
          cx={CENTER_X}
          cy={CENTER_Y}
          r="22"
          fill="hsl(45 100% 55%)"
          stroke="hsl(45 80% 30%)"
          strokeWidth="3"
        />
        <circle
          cx={CENTER_X}
          cy={CENTER_Y}
          r="12"
          fill="hsl(45 80% 25%)"
        />
      </svg>
    );
  },
);

WheelSvg.displayName = 'WheelSvg';

export default WheelSvg;
