import { Outlet, useNavigate, Link } from 'react-router-dom';
import { Coins, LogOut, User, Trophy } from 'lucide-react';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { getPlayerLevelInfo } from '@client/src/utils/casino-levels';
import { Button } from '@client/src/components/ui/button';
import { useEffect } from 'react';

const Layout = () => {
  const navigate = useNavigate();
  const { username, playerState, loading, logout, token } = useGameAuth();

  const levelInfo = playerState ? getPlayerLevelInfo(playerState.experience) : null;

  // Redirect to login if not authenticated
  useEffect(() => {
    if (!loading && !token) {
      navigate('/login', { replace: true });
    }
  }, [loading, token, navigate]);

  const handleLogout = () => {
    logout();
    navigate('/login', { replace: true });
  };

  // If not logged in, don't show the layout chrome (redirecting)
  if (!token && !loading) {
    return null;
  }

  return (
    <div className="min-h-screen w-full bg-background text-foreground">
      {/* Top bar */}
      <header className="sticky top-0 z-40 w-full border-b border-border/60 bg-background/80 backdrop-blur-sm">
        <div className="max-w-3xl mx-auto px-4 md:px-6 h-14 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Coins className="w-5 h-5 text-primary" strokeWidth={1.5} />
            <span className="font-bold text-foreground tracking-wide">
              筹码娱乐
            </span>
          </div>

          <div className="flex items-center gap-3">
            {/* Leaderboard link */}
            <Link
              to="/leaderboard"
              className="p-2 rounded-lg hover:bg-primary/10 transition-colors"
              aria-label="排行榜"
            >
              <Trophy className="w-5 h-5 text-primary" strokeWidth={1.5} />
            </Link>

            {/* Username + level */}
            {username && (
              <div className="flex items-center gap-2">
                <div className="flex items-center gap-1.5">
                  <User className="w-4 h-4 text-primary/70" strokeWidth={1.5} />
                  <span className="text-sm font-medium text-foreground">
                    {username}
                  </span>
                </div>
                {levelInfo && (
                  <span className="text-xs text-primary font-semibold bg-primary/10 px-2 py-0.5 rounded-full">
                    Lv.{levelInfo.level} · {levelInfo.levelName}
                  </span>
                )}
              </div>
            )}

            {/* Chip balance */}
            {playerState && (
              <div className="hidden sm:flex items-center gap-1.5 bg-card/60 px-2.5 py-1 rounded-full border border-border/60">
                <Coins className="w-3.5 h-3.5 text-primary" />
                <span className="text-sm font-semibold text-foreground">
                  {playerState.chipBalance.toLocaleString()}
                </span>
              </div>
            )}

            {/* Logout button */}
            <Button
              variant="ghost"
              size="sm"
              onClick={handleLogout}
              className="gap-1.5 text-muted-foreground hover:text-foreground"
            >
              <LogOut className="w-4 h-4" strokeWidth={1.5} />
              <span className="hidden sm:inline text-xs">退出</span>
            </Button>
          </div>
        </div>
      </header>

      <div className="w-full">
        <Outlet />
      </div>
    </div>
  );
};

export default Layout;
