import { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { playSound } from '@client/src/utils/sound';
import { SoundToggleButton } from '@client/src/hooks/useSound';
import {
  Crown,
  Sparkles,
  Coins,
  Trophy,
  ArrowRight,
  Gift,
  Check,
  Star,
  DoorOpen,
  Lock,
  Wallet,
  CreditCard,
  AlertTriangle,
  CheckCircle,
  X,
  Settings,
  Ticket,
  Power,
  Download,
  Upload,
} from 'lucide-react';
import { useGameAuth } from '@client/src/hooks/useGameAuth';
import { useAutoSave } from '@client/src/hooks/useAutoSave';
import { casinoApi } from '@client/src/api';
import { exportSave, importSave } from '@client/src/api/local-engine';
import {
  CASINOS,
  getPlayerLevelInfo,
  getCurrentCasinoTier,
  getNextCasinoToUnlock,
  isCasinoUnlocked,
} from '@client/src/utils/casino-levels';
import type { CasinoInfo, CasinoTier, LoanStatus } from '@shared/api.interface';
import { CasinoCard, cardVariants } from './CasinoCard';

const ROMAN_NUMERALS: Record<number, string> = {
  1: 'Ⅰ',
  2: 'Ⅱ',
  3: 'Ⅲ',
  4: 'Ⅳ',
  5: 'Ⅴ',
};

const containerVariants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.1 },
  },
};

const HomePage = () => {
  const navigate = useNavigate();
  const { playerState, loading, checkInLoading, handleCheckIn, token, setPlayerState, logout, redeemLoading, handleRedeemCode, refreshPlayerState, username } =
    useGameAuth();

  useAutoSave(playerState);

  useEffect(() => {
    if (!loading && !token) {
      navigate('/login', { replace: true });
    }
  }, [loading, token, navigate]);

  const experience = playerState?.experience ?? 0;
  const chipBalance = playerState?.chipBalance ?? 0;
  const levelInfo = playerState ? getPlayerLevelInfo(experience) : null;
  const currentTier: CasinoTier | null = playerState
    ? getCurrentCasinoTier(experience)
    : null;
  const nextCasino = playerState ? getNextCasinoToUnlock(experience) : null;
  const currentCasinoName = currentTier
    ? CASINOS.find((c: CasinoInfo) => c.tier === currentTier)?.name ?? ''
    : '';

  const [unlockModalCasino, setUnlockModalCasino] = useState<CasinoInfo | null>(
    null,
  );
  const prevTierRef = useRef<CasinoTier | null>(null);

  useEffect(() => {
    if (currentTier && prevTierRef.current !== null) {
      if (currentTier > prevTierRef.current) {
        const newlyUnlocked = CASINOS.find(
          (c: CasinoInfo) => c.tier === currentTier,
        );
        if (newlyUnlocked) {
          setUnlockModalCasino(newlyUnlocked);
          playSound('levelUp');
        }
      }
    }
    if (currentTier !== null) {
      prevTierRef.current = currentTier;
    }
  }, [currentTier]);

  const [loanStatus, setLoanStatus] = useState<LoanStatus | null>(null);
  const [loanLoading, setLoanLoading] = useState<boolean>(false);
  const [applyLoading, setApplyLoading] = useState<boolean>(false);
  const [repayLoading, setRepayLoading] = useState<boolean>(false);
  const [repayModalOpen, setRepayModalOpen] = useState<boolean>(false);
  const [settingsOpen, setSettingsOpen] = useState<boolean>(false);
  const [redeemCodeValue, setRedeemCodeValue] = useState<string>('');
  const [redeemResultMsg, setRedeemResultMsg] = useState<{ text: string; isError: boolean } | null>(null);
  const [repayAmount, setRepayAmount] = useState<string>('');
  const importFileRef = useRef<HTMLInputElement | null>(null);

  const handleExportSave = (): void => {
    try {
      const json = exportSave();
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${username || 'player'}-save.json`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success('存档已导出');
    } catch (err) {
      toast.error((err as Error).message || '导出失败');
    }
  };

  const handleImportFile = (file: File): void => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = importSave(String(reader.result));
      if (result.success) {
        void refreshPlayerState().then(() => toast.success(result.message));
      } else {
        toast.error(result.message);
      }
    };
    reader.onerror = () => toast.error('读取存档文件失败');
    reader.readAsText(file);
  };

  const fetchLoanStatus = async (): Promise<void> => {
    if (!token) return;
    try {
      setLoanLoading(true);
      const status = await casinoApi.getLoanStatus();
      setLoanStatus(status);
    } catch (err) {
      const message =
        (err as { response?: { data?: { message?: string } } }).response?.data
          ?.message ??
        (err as Error).message ??
        '获取贷款状态失败';
      toast.error(message);
    } finally {
      setLoanLoading(false);
    }
  };

  useEffect(() => {
    if (token && !loading) {
      void fetchLoanStatus();
    }
  }, [token, loading]);

  const handleApplyLoan = async (): Promise<void> => {
    if (applyLoading) return;
    try {
      setApplyLoading(true);
      const result = await casinoApi.applyLoan();
      if (result.success) {
        playSound('loan');
        toast.success(result.message);
        if (result.player) {
          setPlayerState(result.player);
        }
        void fetchLoanStatus();
      } else {
        toast.error(result.message);
      }
    } catch (err) {
      const message =
        (err as { response?: { data?: { message?: string } } }).response?.data
          ?.message ??
        (err as Error).message ??
        '申请贷款失败';
      toast.error(message);
    } finally {
      setApplyLoading(false);
    }
  };

  const handleRedeemSubmit = async () => {
    const code = redeemCodeValue.trim();
    if (!code) return;
    setRedeemResultMsg(null);
    const result = await handleRedeemCode(code);
    setRedeemResultMsg({ text: result.message, isError: !result.success });
    if (result.success) {
      setRedeemCodeValue('');
      playSound(result.zdAutoSpin ? 'win' : 'tick');
      toast.success(result.message);
    } else {
      toast.error(result.message);
    }
  };

  const openRepayModal = (): void => {
    const totalDebt = loanStatus?.totalDebt ?? 0;
    const maxRepay = Math.min(chipBalance, totalDebt);
    setRepayAmount(String(Math.floor(maxRepay)));
    setRepayModalOpen(true);
  };

  const handleRepay = async (): Promise<void> => {
    const amount = Number(repayAmount);
    if (!amount || amount <= 0) {
      toast.error('请输入有效的还款金额');
      return;
    }
    if (amount > chipBalance) {
      toast.error('还款金额不能超过筹码余额');
      return;
    }
    if (repayLoading) return;
    try {
      setRepayLoading(true);
      const result = await casinoApi.repayLoan(amount);
      if (result.success) {
        playSound('chip');
        toast.success(result.message);
        if (result.player) {
          setPlayerState(result.player);
        }
        setRepayModalOpen(false);
        void fetchLoanStatus();
      } else {
        toast.error(result.message);
      }
    } catch (err) {
      const message =
        (err as { response?: { data?: { message?: string } } }).response?.data
          ?.message ??
        (err as Error).message ??
        '还款失败';
      toast.error(message);
    } finally {
      setRepayLoading(false);
    }
  };

  const handleEnterCasino = (path: string) => {
    navigate(path);
  };

  const handleGoExplore = () => {
    if (unlockModalCasino) {
      navigate(unlockModalCasino.path);
      setUnlockModalCasino(null);
    }
  };

  const canApply =
    loanStatus?.canApplyToday &&
    !loanStatus?.hasLoan &&
    chipBalance < 1000;

  const remainingLoanTimes = loanStatus
    ? Math.max(0, loanStatus.dailyLimit - loanStatus.loanTimesToday)
    : 0;

  return (
    <div className="min-h-screen w-full bg-background text-foreground relative overflow-hidden">
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/60" />
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-primary/10 rounded-full blur-[120px]" />
        <div className="absolute top-40 right-10 w-[300px] h-[300px] bg-amber-600/10 rounded-full blur-[100px]" />
        <div className="absolute top-60 -left-20 w-[400px] h-[400px] bg-primary/5 rounded-full blur-[120px]" />
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-[800px] h-[300px] bg-amber-800/10 rounded-full blur-[140px]" />
      </div>

      <div className="relative z-10 max-w-3xl mx-auto px-4 md:px-6 py-8 md:py-10">
        <div className="absolute top-4 right-4 z-20 flex items-center gap-2">
          <button
            type="button"
            onClick={() => {
              setSettingsOpen(true);
              setRedeemCodeValue('');
              setRedeemResultMsg(null);
            }}
            className="w-9 h-9 rounded-full flex items-center justify-center text-primary/80 hover:text-primary bg-card/60 border border-border/60 backdrop-blur-sm transition-colors"
            aria-label="设置"
            data-ai-section-type="button"
          >
            <Settings className="w-4 h-4" strokeWidth={1.5} />
          </button>
          <SoundToggleButton className="text-primary/80 hover:text-primary bg-card/60 border border-border/60 backdrop-blur-sm" />
        </div>

        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8"
        >
          <div className="flex items-center justify-center gap-3 mb-2">
            <Star
              className="w-5 h-5 md:w-6 md:h-6 text-primary/60"
              strokeWidth={1.5}
            />
            <h1 className="text-3xl md:text-5xl font-bold tracking-widest bg-gradient-to-r from-amber-300 via-primary to-amber-300 bg-clip-text text-transparent">
              赌场大厅
            </h1>
            <Star
              className="w-5 h-5 md:w-6 md:h-6 text-primary/60"
              strokeWidth={1.5}
            />
          </div>
          <div className="flex items-center justify-center gap-3 mt-3">
            <div className="h-px w-12 md:w-20 bg-gradient-to-r from-transparent to-primary/40" />
            <Sparkles
              className="w-4 h-4 text-primary/50"
              strokeWidth={1.5}
            />
            <p className="text-xs md:text-sm text-muted-foreground tracking-wider">
              逐级攀登 · 见证辉煌
            </p>
            <Sparkles
              className="w-4 h-4 text-primary/50"
              strokeWidth={1.5}
            />
            <div className="h-px w-12 md:w-20 bg-gradient-to-l from-transparent to-primary/40" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1 }}
          className="bg-card/80 backdrop-blur-sm border border-border/60 rounded-xl p-5 mb-8 shadow-2xl shadow-black/40"
          data-ai-section-type="card-stat"
        >
          <div className="flex flex-col gap-5">
            <div className="flex flex-col sm:flex-row sm:items-center gap-4">
              <div className="flex items-center gap-3 flex-1">
                <div className="w-14 h-14 rounded-full bg-gradient-to-br from-primary/40 via-amber-500/30 to-amber-700/30 border-2 border-primary/50 flex items-center justify-center shadow-lg shadow-primary/20">
                  <Trophy
                    className="w-7 h-7 text-primary"
                    strokeWidth={1.5}
                  />
                </div>
                <div>
                  <div className="flex items-baseline gap-2">
                    <span className="text-2xl font-bold text-foreground">
                      Lv.{loading ? '..' : levelInfo?.level ?? 1}
                    </span>
                    <span className="text-sm text-primary font-medium">
                      {loading ? '...' : levelInfo?.levelName ?? '新手赌客'}
                    </span>
                  </div>
                  <div className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1.5">
                    <DoorOpen className="w-3.5 h-3.5" strokeWidth={1.5} />
                    当前：{currentCasinoName || '...'}
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 flex-1">
                <div className="w-12 h-12 rounded-full bg-gradient-to-br from-primary/30 to-amber-700/20 border border-primary/40 flex items-center justify-center">
                  <Coins
                    className="w-6 h-6 text-primary"
                    strokeWidth={1.5}
                  />
                </div>
                <div>
                  <div className="text-xs text-muted-foreground mb-0.5">
                    筹码余额
                  </div>
                  <div className="text-xl font-bold text-foreground">
                    {loading
                      ? '...'
                      : playerState?.chipBalance.toLocaleString() ?? 0}
                  </div>
                </div>
              </div>

              <motion.button
                whileHover={
                  !loading &&
                  !playerState?.hasCheckedInToday &&
                  !checkInLoading
                    ? { scale: 1.03 }
                    : {}
                }
                whileTap={
                  !loading &&
                  !playerState?.hasCheckedInToday &&
                  !checkInLoading
                    ? { scale: 0.97 }
                    : {}
                }
                onClick={handleCheckIn}
                disabled={
                  loading ||
                  playerState?.hasCheckedInToday ||
                  checkInLoading
                }
                className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg font-semibold transition-all text-sm ${
                  playerState?.hasCheckedInToday
                    ? 'bg-muted text-muted-foreground cursor-not-allowed border border-border'
                    : 'bg-gradient-to-r from-primary to-amber-400 text-primary-foreground shadow-lg shadow-primary/30 hover:shadow-primary/50 cursor-pointer'
                }`}
                data-ai-section-type="button"
              >
                {playerState?.hasCheckedInToday ? (
                  <>
                    <Check className="w-4 h-4" strokeWidth={2} />
                    今日已签到
                  </>
                ) : (
                  <>
                    <Gift className="w-4 h-4" strokeWidth={2} />
                    {checkInLoading ? '签到中...' : '每日签到 +100筹码'}
                  </>
                )}
              </motion.button>
            </div>

            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs text-muted-foreground">经验进度</span>
                <span className="text-xs text-muted-foreground">
                  {loading
                    ? '...'
                    : levelInfo?.isMax
                      ? '已满级'
                      : `${levelInfo?.currentExp.toLocaleString() ?? 0} / ${levelInfo?.nextLevelExp.toLocaleString() ?? 0} EXP`}
                </span>
              </div>
              <div className="w-full h-2.5 bg-muted rounded-full overflow-hidden border border-border/40">
                <motion.div
                  initial={{ width: 0 }}
                  animate={{
                    width: loading ? 0 : `${levelInfo?.progress ?? 0}%`,
                  }}
                  transition={{ duration: 1, delay: 0.3, ease: 'easeOut' }}
                  className="h-full bg-gradient-to-r from-amber-600 via-primary to-amber-300 rounded-full relative"
                >
                  <div className="absolute inset-0 bg-white/20 animate-pulse" />
                </motion.div>
              </div>

              {nextCasino && !loading && (
                <div className="mt-2 flex items-center gap-1.5 text-xs text-muted-foreground/70">
                  <Lock className="w-3 h-3" strokeWidth={1.5} />
                  <span>
                    距离{' '}
                    <span className="text-primary/80 font-medium">
                      {nextCasino.name}
                    </span>{' '}
                    还差{' '}
                    <span className="text-primary font-semibold">
                      {(nextCasino.unlockExp - experience).toLocaleString()}
                    </span>{' '}
                    经验
                  </span>
                </div>
              )}
            </div>
          </div>
        </motion.div>

        {loanStatus && !loading && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className={`rounded-xl p-5 mb-6 shadow-2xl shadow-black/40 border backdrop-blur-sm ${
              loanStatus.hasLoan
                ? 'bg-gradient-to-br from-red-950/60 via-red-900/40 to-card/60 border-red-500/40'
                : canApply
                  ? 'bg-gradient-to-br from-amber-950/60 via-primary/20 to-card/60 border-primary/50'
                  : 'bg-card/60 border-border/60'
            }`}
            data-ai-section-type="card-stat"
          >
            <div className="flex items-start gap-4">
              <div
                className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 ${
                  loanStatus.hasLoan
                    ? 'bg-gradient-to-br from-red-500/40 to-red-700/30 border border-red-500/50'
                    : canApply
                      ? 'bg-gradient-to-br from-primary/40 to-amber-600/30 border border-primary/50'
                      : 'bg-gradient-to-br from-emerald-500/30 to-emerald-700/20 border border-emerald-500/40'
                }`}
              >
                {loanStatus.hasLoan ? (
                  <AlertTriangle
                    className="w-6 h-6 text-red-400"
                    strokeWidth={1.5}
                  />
                ) : canApply ? (
                  <CreditCard
                    className="w-6 h-6 text-primary"
                    strokeWidth={1.5}
                  />
                ) : (
                  <CheckCircle
                    className="w-6 h-6 text-emerald-400"
                    strokeWidth={1.5}
                  />
                )}
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between gap-2 mb-1">
                  <h3 className="font-bold text-foreground flex items-center gap-2">
                    <Wallet className="w-4 h-4" strokeWidth={1.5} />
                    贷款状态
                  </h3>
                  <span className="text-xs text-muted-foreground">
                    今日剩余 {remainingLoanTimes}/{loanStatus.dailyLimit} 次
                  </span>
                </div>

                {loanStatus.hasLoan ? (
                  <>
                    <p className="text-sm text-red-200 mb-3">
                      未还本息：
                      <span className="font-bold text-lg text-red-300 ml-1">
                        {loanStatus.totalDebt.toLocaleString()}
                      </span>{' '}
                      筹码
                    </p>
                    <div className="flex items-center justify-between gap-3">
                      <span className="text-xs text-muted-foreground">
                        剩余还款局数：
                        <span className="text-foreground font-medium ml-1">
                          {loanStatus.gamesRemaining} 局
                        </span>
                      </span>
                      <motion.button
                        whileHover={{ scale: 1.03 }}
                        whileTap={{ scale: 0.97 }}
                        onClick={openRepayModal}
                        className="px-4 py-2 rounded-lg text-sm font-semibold bg-gradient-to-r from-red-500 to-red-600 text-white shadow-lg shadow-red-500/30 hover:shadow-red-500/50 transition-all"
                        data-ai-section-type="button"
                      >
                        立即还款
                      </motion.button>
                    </div>
                  </>
                ) : canApply ? (
                  <>
                    <p className="text-sm text-amber-200 mb-3">
                      筹码偏低，可申请贷款翻盘
                    </p>
                    <motion.button
                      whileHover={{ scale: 1.03 }}
                      whileTap={{ scale: 0.97 }}
                      onClick={handleApplyLoan}
                      disabled={applyLoading}
                      className="w-full sm:w-auto px-5 py-2.5 rounded-lg font-semibold bg-gradient-to-r from-primary to-amber-400 text-primary-foreground shadow-lg shadow-primary/30 hover:shadow-primary/50 transition-all flex items-center justify-center gap-2"
                      data-ai-section-type="button"
                    >
                      <CreditCard className="w-4 h-4" strokeWidth={2} />
                      {applyLoading ? '申请中...' : '立即申请贷款'}
                    </motion.button>
                  </>
                ) : (
                  <p className="text-sm text-emerald-200">
                    你的筹码充足，无需贷款
                  </p>
                )}
              </div>
            </div>
          </motion.div>
        )}

        {loanLoading && !loading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="bg-card/60 border border-border/60 rounded-xl p-5 mb-6"
          >
            <div className="text-sm text-muted-foreground text-center">
              加载贷款状态中...
            </div>
          </motion.div>
        )}

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.25 }}
          className="mb-6"
        >
          <motion.div
            whileHover={{ scale: 1.01 }}
            whileTap={{ scale: 0.99 }}
            onClick={() => {
              playSound('click');
              navigate('/leaderboard');
            }}
            className="cursor-pointer bg-gradient-to-r from-purple-950/60 via-indigo-900/40 to-card/60 backdrop-blur-sm border border-purple-500/40 rounded-xl p-5 shadow-2xl shadow-purple-900/30 hover:shadow-purple-500/20 transition-all group"
            data-ai-section-type="button"
          >
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-gradient-to-br from-purple-500/40 to-indigo-600/30 border border-purple-400/50 flex items-center justify-center flex-shrink-0">
                <Trophy
                  className="w-6 h-6 text-purple-300"
                  strokeWidth={1.5}
                />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-bold text-foreground flex items-center gap-2">
                  全服排行榜
                  <span className="text-xs font-normal text-purple-300/80 bg-purple-500/20 px-2 py-0.5 rounded-full">
                    HOT
                  </span>
                </h3>
                <p className="text-sm text-muted-foreground mt-0.5">
                  等级称号榜 · 筹码现金流榜
                </p>
              </div>
              <ArrowRight
                className="w-5 h-5 text-muted-foreground group-hover:text-purple-300 group-hover:translate-x-1 transition-all"
                strokeWidth={1.5}
              />
            </div>
          </motion.div>
        </motion.div>

        <div className="mb-6">
          <h2 className="text-lg font-bold text-foreground mb-1 flex items-center gap-2">
            <span className="w-1 h-5 bg-primary rounded-full" />
            赌场阶梯
          </h2>
          <p className="text-muted-foreground text-xs ml-3">
            从街边小赌场起步，攀登至帝王级殿堂
          </p>
        </div>

        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="show"
          className="flex flex-col gap-4"
          data-ai-section-type="card-list"
        >
          {CASINOS.map((casino: CasinoInfo) => (
            <CasinoCard
              key={casino.id}
              casino={casino}
              unlocked={isCasinoUnlocked(experience, casino.tier)}
              isCurrent={currentTier === casino.tier}
              experience={experience}
              onEnter={handleEnterCasino}
            />
          ))}
        </motion.div>

        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.2, duration: 1 }}
          className="mt-10 flex items-center justify-center gap-3"
        >
          <div className="h-px w-16 bg-gradient-to-r from-transparent to-primary/30" />
          <Crown className="w-4 h-4 text-primary/50" strokeWidth={1.5} />
          <div className="h-px w-16 bg-gradient-to-l from-transparent to-primary/30" />
        </motion.div>
      </div>

      <AnimatePresence>
        {repayModalOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
            onClick={() => setRepayModalOpen(false)}
          >
            <motion.div
              initial={{ scale: 0.85, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.85, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 260, damping: 22 }}
              className="relative max-w-sm w-full rounded-2xl border-2 border-red-500/50 bg-gradient-to-b from-card via-card to-red-950/30 p-6 shadow-[0_0_60px_rgba(239_68_68_0.25)]"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setRepayModalOpen(false)}
                className="absolute top-4 right-4 text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-5 h-5" strokeWidth={1.5} />
              </button>

              <div className="flex items-center gap-3 mb-5">
                <div className="w-12 h-12 rounded-full bg-gradient-to-br from-red-500/40 to-red-700/30 border border-red-500/50 flex items-center justify-center">
                  <CreditCard
                    className="w-6 h-6 text-red-300"
                    strokeWidth={1.5}
                  />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">还款</h3>
                  <p className="text-xs text-muted-foreground">
                    未还本息：
                    <span className="text-red-300 font-medium">
                      {loanStatus?.totalDebt.toLocaleString() ?? 0}
                    </span>{' '}
                    筹码
                  </p>
                </div>
              </div>

              <div className="space-y-3 mb-5">
                <div>
                  <label className="text-xs text-muted-foreground mb-1.5 block">
                    还款金额
                  </label>
                  <input
                    type="number"
                    value={repayAmount}
                    onChange={(e) => setRepayAmount(e.target.value)}
                    className="w-full px-4 py-3 rounded-lg bg-muted/50 border border-border text-foreground text-lg font-bold focus:outline-none focus:border-primary/60 transition-colors"
                    placeholder="输入还款金额"
                  />
                </div>
                <div className="flex items-center justify-between text-xs text-muted-foreground">
                  <span>
                    可还余额：
                    <span className="text-foreground font-medium">
                      {chipBalance.toLocaleString()}
                    </span>{' '}
                    筹码
                  </span>
                  <button
                    onClick={() => {
                      const maxRepay = Math.min(
                        chipBalance,
                        loanStatus?.totalDebt ?? 0,
                      );
                      setRepayAmount(String(Math.floor(maxRepay)));
                    }}
                    className="text-primary hover:text-primary/80 font-medium transition-colors"
                  >
                    全额还款
                  </button>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <motion.button
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={handleRepay}
                  disabled={repayLoading || !repayAmount || Number(repayAmount) <= 0}
                  className="w-full py-3 rounded-lg font-bold bg-gradient-to-r from-red-500 to-red-600 text-white shadow-lg shadow-red-500/30 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                  data-ai-section-type="button"
                >
                  {repayLoading ? '还款中...' : '确认还款'}
                </motion.button>
                <button
                  onClick={() => setRepayModalOpen(false)}
                  className="w-full py-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
                >
                  取消
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {settingsOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
            onClick={() => setSettingsOpen(false)}
          >
            <motion.div
              initial={{ scale: 0.85, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.85, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 260, damping: 22 }}
              className="relative max-w-sm w-full rounded-2xl border-2 border-primary/50 bg-gradient-to-b from-card via-card to-amber-950/30 p-6 shadow-[0_0_60px_rgba(245_158_11_0.25)]"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setSettingsOpen(false)}
                className="absolute top-4 right-4 text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-5 h-5" strokeWidth={1.5} />
              </button>

              <div className="flex items-center gap-3 mb-6">
                <div className="w-12 h-12 rounded-full bg-gradient-to-br from-primary/40 to-amber-700/30 border border-primary/50 flex items-center justify-center">
                  <Settings
                    className="w-6 h-6 text-primary"
                    strokeWidth={1.5}
                  />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">设置</h3>
                  <p className="text-xs text-muted-foreground">
                    账号：{playerState ? '' : '...'}
                  </p>
                </div>
              </div>

              <div className="space-y-4 mb-5">
                <div>
                  <label className="text-xs text-muted-foreground mb-1.5 block flex items-center gap-1.5">
                    <Ticket className="w-3.5 h-3.5" strokeWidth={1.5} />
                    兑换码
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={redeemCodeValue}
                      onChange={(e) => setRedeemCodeValue(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') void handleRedeemSubmit();
                      }}
                      placeholder="输入兑换码"
                      className="flex-1 px-4 py-3 rounded-lg bg-muted/50 border border-border text-foreground font-bold focus:outline-none focus:border-primary/60 transition-colors uppercase"
                    />
                    <motion.button
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={handleRedeemSubmit}
                      disabled={redeemLoading || !redeemCodeValue.trim()}
                      className="px-5 py-3 rounded-lg font-bold bg-gradient-to-r from-primary to-amber-600 text-white shadow-lg shadow-primary/30 disabled:opacity-50 disabled:cursor-not-allowed"
                      data-ai-section-type="button"
                    >
                      {redeemLoading ? '...' : '兑换'}
                    </motion.button>
                  </div>
                  {redeemResultMsg && (
                    <p
                      className={`text-xs mt-2 ${
                        redeemResultMsg.isError
                          ? 'text-red-400'
                          : 'text-emerald-400'
                      }`}
                    >
                      {redeemResultMsg.text}
                    </p>
                  )}
                  {(playerState?.zd1 || playerState?.zd2 || playerState?.zd3) && (
                    <div className="mt-3 flex flex-wrap gap-2 px-3 py-2 rounded-lg bg-emerald-500/10 border border-emerald-500/30">
                      <Power className="w-4 h-4 text-emerald-400" strokeWidth={1.5} />
                      <span className="text-xs text-emerald-300">
                        自动转盘已开启：
                        {playerState?.zd1 && 'ZD1 '}
                        {playerState?.zd2 && 'ZD2 '}
                        {playerState?.zd3 && 'ZD3'}
                      </span>
                    </div>
                  )}
                </div>
              </div>

              <div>
                <label className="text-xs text-muted-foreground mb-1.5 block flex items-center gap-1.5">
                  <Download className="w-3.5 h-3.5" strokeWidth={1.5} />
                  存档备份
                </label>
                <div className="flex gap-2">
                  <button
                    onClick={handleExportSave}
                    className="flex-1 py-2.5 rounded-lg text-sm font-bold bg-gradient-to-r from-primary/80 to-amber-700/60 text-white border border-primary/40 hover:opacity-90 transition-opacity flex items-center justify-center gap-1.5"
                    data-ai-section-type="button"
                  >
                    <Download className="w-4 h-4" strokeWidth={2} />
                    导出存档
                  </button>
                  <button
                    onClick={() => importFileRef.current?.click()}
                    className="flex-1 py-2.5 rounded-lg text-sm font-bold bg-muted text-foreground border border-border hover:bg-muted/70 transition-colors flex items-center justify-center gap-1.5"
                    data-ai-section-type="button"
                  >
                    <Upload className="w-4 h-4" strokeWidth={2} />
                    导入存档
                  </button>
                </div>
                <p className="text-[11px] text-muted-foreground/70 mt-1.5 leading-snug">
                  导出会下载存档 JSON；换浏览器/设备时先注册同名账号，再导入即可恢复。
                </p>
                <input
                  ref={importFileRef}
                  type="file"
                  accept=".json,application/json"
                  className="hidden"
                  onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) handleImportFile(f);
                    e.target.value = '';
                  }}
                />
              </div>

              <div className="flex flex-col gap-2">
                <button
                  onClick={() => {
                    setSettingsOpen(false);
                    logout();
                    navigate('/login', { replace: true });
                  }}
                  className="w-full py-2.5 text-sm text-red-400 hover:text-red-300 transition-colors flex items-center justify-center gap-1.5"
                >
                  <DoorOpen className="w-4 h-4" strokeWidth={1.5} />
                  退出登录
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {unlockModalCasino && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
            onClick={() => setUnlockModalCasino(null)}
          >
            <motion.div
              initial={{ scale: 0.7, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.7, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 260, damping: 20 }}
              className="relative max-w-sm w-full rounded-2xl border-2 border-primary/60 bg-gradient-to-b from-card via-card to-amber-950/30 p-8 text-center shadow-[0_0_60px_rgba(245_158_11_0.3)]"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="absolute inset-0 rounded-2xl pointer-events-none">
                <div className="absolute -inset-20 bg-primary/10 blur-3xl rounded-full" />
              </div>

              <div className="relative z-10">
                <motion.div
                  animate={{
                    scale: [1, 1.1, 1],
                    rotate: [0, -5, 5, 0],
                  }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                  className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gradient-to-br from-primary via-amber-400 to-amber-600 mb-4 shadow-xl shadow-primary/40"
                >
                  <Crown
                    className="w-10 h-10 text-primary-foreground"
                    strokeWidth={1.5}
                  />
                </motion.div>

                <h2 className="text-2xl font-bold mb-1 bg-gradient-to-r from-primary via-amber-200 to-primary bg-clip-text text-transparent">
                  解锁新赌场！
                </h2>
                <p className="text-sm text-muted-foreground mb-5">
                  恭喜你达到新的高度
                </p>

                <div className="bg-card/60 border border-primary/30 rounded-xl p-4 mb-6">
                  <div className="text-xs text-primary/70 mb-1 tracking-widest">
                    TIER {ROMAN_NUMERALS[unlockModalCasino.tier]}
                  </div>
                  <h3 className="text-xl font-bold text-foreground mb-1">
                    {unlockModalCasino.name}
                  </h3>
                  <p className="text-sm text-muted-foreground">
                    {unlockModalCasino.subtitle}
                  </p>
                  <p className="text-xs text-muted-foreground/70 mt-2 leading-relaxed">
                    {unlockModalCasino.description}
                  </p>
                </div>

                <div className="flex flex-col gap-2">
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={handleGoExplore}
                    className="w-full py-3 rounded-lg font-bold bg-gradient-to-r from-primary to-amber-400 text-primary-foreground shadow-lg shadow-primary/30 flex items-center justify-center gap-2"
                    data-ai-section-type="button"
                  >
                    前往探索
                    <ArrowRight className="w-4 h-4" strokeWidth={2} />
                  </motion.button>
                  <button
                    onClick={() => setUnlockModalCasino(null)}
                    className="w-full py-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
                  >
                    稍后再说
                  </button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default HomePage;
